class _EnginesAliasFinder:
    @classmethod
    def find_spec(cls, fullname, path, target=None):
        if fullname == "engines" or fullname.startswith("engines."):
            canonical_name = "aspice_qa_framework." + fullname
            try:
                mod = importlib.import_module(canonical_name)
                sys.modules[fullname] = mod
                return getattr(mod, "__spec__", None)
            except Exception:
                return None
        return None

