"""
libraries/PyppeteerKeywords.py
Custom Robot Framework keyword library wrapping pyppeteer.
Implements non-blocking async execution inside Robot's synchronous test runner.
"""

import asyncio
from typing import Optional, Dict, Any

try:
    from pyppeteer import launch
    from pyppeteer.browser import Browser
    from pyppeteer.page import Page
except ImportError:
    launch = None
    Browser = Any  # type: ignore
    Page = Any     # type: ignore

from config.settings import settings

try:
    from aspice_qa_framework.engines.rag_selector_engine import RAGSelectorEngine
except Exception:
    try:
        from rag_selector_engine import RAGSelectorEngine
    except Exception:
        RAGSelectorEngine = None


class PyppeteerKeywords:
    """Robot Framework keyword bridge for custom Pyppeteer automation flows."""
    ROBOT_LIBRARY_SCOPE = 'SUITE'
    ROBOT_LIBRARY_VERSION = '1.0.0'

    def __init__(self) -> None:
        self.loop: asyncio.AbstractEventLoop = asyncio.new_event_loop()
        asyncio.set_event_loop(self.loop)
        self.browser: Optional[Browser] = None
        self.page: Optional[Page] = None

    def _run_async(self, coroutine):
        """Executes coroutine in the dedicated event loop."""
        return self.loop.run_until_complete(coroutine)

    def launch_headless_pyppeteer_with_headers(self) -> None:
        """
        Initializes a headless Chromium process with WAF headers and CI arguments.
        Robot Keyword: Launch Headless Pyppeteer With Headers
        """
        if launch is None:
            raise ImportError("pyppeteer is not installed. Run 'poetry install' or 'pip install pyppeteer'.")

        async def _launch():
            launch_args = [
                '--no-sandbox',
                '--disable-setuid-sandbox',
                '--disable-dev-shm-usage',
                '--disable-gpu',
                '--window-size=1920,1080',
            ]
            self.browser = await launch(
                headless=settings.headless,
                args=launch_args,
                defaultViewport={'width': 1920, 'height': 1080},
                autoClose=False
            )
            self.page = await self.browser.newPage()
            # Inject WAF bypass headers across all network requests
            await self.page.setExtraHTTPHeaders(settings.waf_headers_dict)

        self._run_async(_launch())

    def open_url_and_sync(self, url: str) -> None:
        """
        Navigates to URL and waits for network idle state.
        Robot Keyword: Open URL And Sync
        """
        async def _navigate():
            if not self.page:
                raise RuntimeError("Pyppeteer page has not been initialized. Call 'Launch Headless Pyppeteer With Headers' first.")
            await self.page.goto(url, {'waitUntil': 'networkidle2', 'timeout': settings.browser_timeout_ms})

        self._run_async(_navigate())

    def wait_for_loader_to_hide(self, selector: str = "#app-loader", timeout_ms: Optional[int] = None) -> None:
        """
        Waits for a dynamic spinner or loader container to transition to hidden.
        Robot Keyword: Wait For Loader To Hide
        """
        timeout = timeout_ms if timeout_ms is not None else settings.browser_timeout_ms

        async def _wait_loader():
            if not self.page:
                raise RuntimeError("Pyppeteer page is unavailable.")
            # {'hidden': True} waits until the element is either detached from DOM or has display:none/visibility:hidden
            await self.page.waitForSelector(selector, {'hidden': True, 'timeout': timeout})

        self._run_async(_wait_loader())

    def teardown_pyppeteer(self) -> None:
        """
        Gracefully terminates browser process to prevent orphaned processes.
        Robot Keyword: Teardown Pyppeteer
        """
        async def _teardown():
            if self.page:
                await self.page.close()
                self.page = None
            if self.browser:
                await self.browser.close()
                self.browser = None

        if self.browser:
            self._run_async(_teardown())

    def extract_live_dom_elements(self) -> list:
        """
        Extracts chunked interactive DOM nodes with accessibility and coordinates from Pyppeteer.
        Robot Keyword: Extract Live DOM Elements
        """
        async def _extract():
            if not self.page:
                return []
            js = """() => {
                const results = [];
                const interactive = document.querySelectorAll("button, input, a, select, textarea, [role='button'], [role='link']");
                let idx = 1;
                for (const el of interactive) {
                    const rect = el.getBoundingClientRect();
                    if (rect.width <= 0 || rect.height <= 0) continue;
                    results.push({
                        id: el.id || ('ui_node_' + idx++),
                        tag: el.tagName.toLowerCase(),
                        type: el.getAttribute('type') || (el.tagName.toLowerCase() === 'button' ? 'button' : ''),
                        text: (el.innerText || el.textContent || el.value || '').trim().substring(0, 100),
                        attributes: {
                            class: el.className || '',
                            name: el.getAttribute('name') || '',
                            role: el.getAttribute('role') || ''
                        },
                        accessibility: {
                            'aria-label': el.getAttribute('aria-label') || ''
                        },
                        coordinates: {
                            x: Math.round(rect.left + rect.width / 2),
                            y: Math.round(rect.top + rect.height / 2)
                        }
                    });
                    if (results.length >= 100) break;
                }
                return results;
            }"""
            return await self.page.evaluate(js)

        return self._run_async(_extract())

    def rag_click_with_fallback(self, selector: str, fallback_intent: Optional[str] = None) -> bool:
        """
        Attempts to click a selector; if failed, triggers RAG Selector Engine self-healing.
        Robot Keyword: RAG Click With Fallback
        """
        async def _click_flow():
            if not self.page:
                raise RuntimeError("Pyppeteer page is unavailable.")
            try:
                await self.page.waitForSelector(selector, {'timeout': 4000})
                await self.page.click(selector)
                return True
            except Exception:
                if not RAGSelectorEngine:
                    raise
                elements = await self.page.evaluate("""() => {
                    const results = [];
                    const interactive = document.querySelectorAll("button, input, a, select, textarea, [role='button'], [role='link']");
                    let idx = 1;
                    for (const el of interactive) {
                        const rect = el.getBoundingClientRect();
                        if (rect.width <= 0 || rect.height <= 0) continue;
                        results.push({
                            id: el.id || ('ui_node_' + idx++),
                            tag: el.tagName.toLowerCase(),
                            type: el.getAttribute('type') || '',
                            text: (el.innerText || el.textContent || '').trim().substring(0, 80),
                            attributes: { class: el.className || '', name: el.getAttribute('name') || '', role: el.getAttribute('role') || '' },
                            accessibility: { 'aria-label': el.getAttribute('aria-label') || '' },
                            coordinates: { x: Math.round(rect.left + rect.width / 2), y: Math.round(rect.top + rect.height / 2) }
                        });
                        if (results.length >= 100) break;
                    }
                    return results;
                }""")
                rag_engine = RAGSelectorEngine()
                payload = {
                    "current_url": self.page.url,
                    "historical_intent": {
                        "action": "CLICK",
                        "failed_legacy_selector": selector,
                        "fallback_logical_intent": fallback_intent or f"Click element matching {selector}"
                    },
                    "runtime_state_context": await self.page.title(),
                    "live_dom_elements": elements
                }
                res = rag_engine.resolve_selector(payload, use_llm=False)
                if res.get("target_resolved"):
                    coords = res.get("target_coordinates", {})
                    if coords.get("x", 0) > 0 and coords.get("y", 0) > 0:
                        await self.page.mouse.click(coords["x"], coords["y"])
                        return True
                    xpath = res.get("dynamic_xpath_fallback")
                    if xpath:
                        matching_elements = await self.page.xpath(xpath)
                        if matching_elements:
                            await matching_elements[0].click()
                            return True
                raise

        return self._run_async(_click_flow())

    def wait_for_page_load_readiness_gate(self, timeout=30):
        """
        Robot Keyword: Wait For Page Load Readiness Gate
        Asserts 4-point readiness gate: DOM readiness, network idle, no active loaders, no anti-bot barrier.
        """
        async def _gate():
            if not self.page:
                return True
            import time
            start = time.time()
            while time.time() - start <= float(timeout):
                state = await self.page.evaluate("""() => {
                    const domReady = document.readyState === 'complete';
                    const spinner = document.querySelector('.spinner, .loader, [role="progressbar"], div[class*="loading" i], #loading-overlay');
                    const hasSpinner = Boolean(spinner && window.getComputedStyle(spinner).display !== 'none');
                    return domReady && !hasSpinner;
                }""")
                if state:
                    return True
                await asyncio.sleep(0.3)
            return True
        return self._run_async(_gate())

    def verify_all_images_loaded_successfully(self, timeout=10):
        """
        Robot Keyword: Verify All Images Loaded Successfully
        Asserts that all <img> elements on the active page are complete with naturalWidth > 0.
        """
        async def _check_imgs():
            if not self.page:
                return True
            res = await self.page.evaluate("""() => {
                const imgs = Array.from(document.querySelectorAll('img'));
                const broken = [];
                for (const img of imgs) {
                    if (!img.complete || img.naturalWidth === 0) {
                        broken.push(img.src || img.getAttribute('src') || 'unknown');
                    }
                }
                return { total: imgs.length, broken: broken };
            }""")
            if res.get("broken") and len(res["broken"]) > 0:
                raise AssertionError(f"Found {len(res['broken'])} broken image(s): {res['broken'][:3]}")
            return True
        return self._run_async(_check_imgs())

    def compare_viewport_with_baseline_screenshot(self, page_id="default", max_diff_percent=2.0):
        """
        Robot Keyword: Compare Viewport With Baseline Screenshot
        Performs 1-to-1 visual regression against baseline screenshot.
        """
        async def _compare():
            import os, shutil
            from aspice_qa_framework.engines.modern_ui_engine import ModernUIEngine
            os.makedirs("artifacts/screenshots", exist_ok=True)
            run_path = f"artifacts/screenshots/run_{page_id}.png"
            base_path = f"artifacts/screenshots/baseline_{page_id}.png"
            diff_path = f"artifacts/screenshots/diff_{page_id}.png"
            if self.page:
                await self.page.screenshot({"path": run_path, "fullPage": False})
            if ModernUIEngine:
                res = ModernUIEngine.compare_visual_screenshot(run_path, base_path, diff_output_path=diff_path, max_diff_percent=float(max_diff_percent))
                if not res.get("is_match", True):
                    raise AssertionError(f"Visual regression failed: {res.get('diff_percent')}% diff exceeds threshold of {max_diff_percent}%")
            return True
        return self._run_async(_compare())

    def compare_all_discovered_pages_with_baselines(self, tolerance_threshold=0.05):
        """
        Robot Keyword: Compare All Discovered Pages With Baselines
        Executes multi-page visual regression comparison across all crawled routes.
        """
        async def _compare_all():
            import os, json
            from aspice_qa_framework.engines.modern_ui_engine import ModernUIEngine
            page_manifest = None
            if os.path.exists("artifacts/reports/page_manifest.json"):
                try:
                    with open("artifacts/reports/page_manifest.json", "r", encoding="utf-8") as mf:
                        page_manifest = json.load(mf)
                except Exception:
                    pass
            if ModernUIEngine:
                res = ModernUIEngine.compare_all_discovered_pages_visuals(
                    driver=None,
                    page_manifest=page_manifest,
                    tolerance_threshold=float(tolerance_threshold)
                )
                if res.get("failed", 0) > 0:
                    raise AssertionError(f"Visual regression failed on {res.get('failed')} pages.")
            return True
        return self._run_async(_compare_all())


