def test_rule_b_auth_wall_and_session_and_modal_interception():
    """
    Tests Rule B:
    - Identifies AUTH_PANEL when type="password" is present.
    - Tracks session state using logout regex.
    - Intercepts blocking modal overlays (Close / Dismiss).
    """
    crawl_payload = {
        "current_url": "https://example.com/dashboard",
        "live_dom_elements": [
            {
                "id": "modal_btn",
                "tag": "button",
                "text": "Dismiss",
                "attributes": {"class": "modal-close-btn"},
                "coordinates": {"x": 950, "y": 50}
            },
            {
                "id": "auth_pass",
                "tag": "input",
                "type": "password",
                "attributes": {"name": "current_password"},
                "coordinates": {"x": 400, "y": 300}
            },
            {
                "id": "nav_logout",
                "tag": "a",
                "text": "Log Out",
                "attributes": {"href": "/logout"},
                "coordinates": {"x": 900, "y": 20}
            }
        ]
    }
    state = RAGSelectorEngine.analyze_spidering_state(crawl_payload)
    assert state["session_state"] == "AUTHENTICATED"
    assert state["has_blocking_overlay"] is True
    assert state["auth_panel_detected"] is True
    assert len(state["recommended_spider_strategies"]) >= 1

    top_strategy = state["recommended_spider_strategies"][0]
    assert top_strategy["action"] == "CLEAR_OVERLAY"
    assert top_strategy["target_node_id"] == "modal_btn"


