def test_rule_c_scenario_matrix_generation():
    """
    Tests Rule C:
    Generates positive fulfilling steps and negative boundary breaking steps.
    """
    component_block = {
        "component_name": "User Registration",
        "elements": [
            {"id": "reg_email", "tag": "input", "type": "email"},
            {"id": "reg_pass", "tag": "input", "type": "password"},
            {"id": "reg_phone", "tag": "input", "type": "tel"},
            {"id": "reg_submit", "tag": "button", "type": "submit"}
        ]
    }
    matrix = RAGSelectorEngine.generate_scenarios_matrix(component_block)
    assert "positive_matrix" in matrix
    assert "negative_matrix" in matrix

    pos_steps = matrix["positive_matrix"]["steps"]
    neg_steps = matrix["negative_matrix"]["steps"]

    assert len(pos_steps) >= 4
    assert len(neg_steps) >= 4

    # Verify email syntax check in positive matrix
    email_pos = next(s for s in pos_steps if s["target_id"] == "reg_email")
    assert "@" in email_pos["value"]

    # Verify injection boundary check in negative matrix
    has_injection_check = any("OR" in s.get("value", "") for s in neg_steps)
    assert has_injection_check is True


