def test_pabot_portable_command_resolution():
    """Verifies that pabot and robot command base resolution handles environments where pabot is not in PATH."""
    pabot_bin = shutil.which("pabot")
    base_cmd = [pabot_bin] if pabot_bin else [sys.executable, "-m", "pabot.pabot"]

    assert len(base_cmd) >= 1
    if pabot_bin:
        assert os.path.exists(base_cmd[0])
    else:
        assert base_cmd == [sys.executable, "-m", "pabot.pabot"]

    # Verify command execution check (help flag)
    res = subprocess.run(base_cmd + ["--help"], capture_output=True, text=True)
    assert res.returncode in [0, 252] or "pabot" in (res.stdout + res.stderr).lower()


