@allure.step("Verify archive_active_run isolates workspace and writes run_metadata.json")
def test_archive_active_run_isolation_and_metadata():
    """Verifies that archive_active_run wipes active allure-results and records complete metadata."""
    results_dir = os.path.abspath(os.path.join("artifacts", "reports", "allure-results"))
    pabot_dir = os.path.abspath(os.path.join("artifacts", "reports", "pabot_results"))
    os.makedirs(results_dir, exist_ok=True)
    os.makedirs(pabot_dir, exist_ok=True)

    # 1. Setup mock run results for Website A
    sample_meta = {
        "run_id": "test_run_a",
        "target_url": "https://example-shop-a.com/checkout",
        "domain": "example-shop-a.com",
        "total_tests": 2,
        "passed": 1,
        "failed": 1
    }
    with open(os.path.join("artifacts", "reports", "run_metadata.json"), "w", encoding="utf-8") as f:
        json.dump(sample_meta, f)

    for item in os.listdir(results_dir):
        p = os.path.join(results_dir, item)
        if os.path.isfile(p):
            os.remove(p)

    res_1 = {"name": "Test Case 1", "status": "passed"}
    res_2 = {"name": "Test Case 2", "status": "failed"}
    with open(os.path.join(results_dir, "test1-result.json"), "w", encoding="utf-8") as f:
        json.dump(res_1, f)
    with open(os.path.join(results_dir, "test2-result.json"), "w", encoding="utf-8") as f:
        json.dump(res_2, f)

    # 2. Trigger archival for a new target Website B
    arch_res = archive_active_run(new_target_url="https://example-portal-b.com", reason="test_isolation")
    
    assert arch_res["status"] == "success"
    assert arch_res["total_tests"] == 2
    assert arch_res["passed"] == 1
    assert arch_res["failed"] == 1

    # 3. Assert active allure-results directory is now clean
    remaining_results = [f for f in os.listdir(results_dir) if f.endswith("-result.json")]
    assert len(remaining_results) == 0, f"Expected 0 active results after archive, found {remaining_results}"

    # 4. Assert archived history directory contains run_metadata.json
    archived_dir = arch_res["archive_dir"]
    assert os.path.exists(archived_dir)
    assert os.path.exists(os.path.join(archived_dir, "run_metadata.json"))
    with open(os.path.join(archived_dir, "run_metadata.json"), "r", encoding="utf-8") as f:
        meta_read = json.load(f)
    assert meta_read["domain"] == "example-shop-a.com"
    assert meta_read["total_tests"] == 2


@allure.step("Verify GET /api/reports/active-run-summary with Boundary Value Analysis")
def test_active_run_summary_bva(client):
    """Verifies that active run summary strictly counts active tests and handles empty/boundary states."""
    results_dir = os.path.abspath(os.path.join("artifacts", "reports", "allure-results"))
    os.makedirs(results_dir, exist_ok=True)

    # Clean active directory
    for f in os.listdir(results_dir):
        if f.endswith("-result.json"):
            os.remove(os.path.join(results_dir, f))

    # Boundary 1: Empty workspace -> 0 counts
    res_empty = client.get("/api/reports/active-run-summary")
    assert res_empty.status_code == 200
    data_empty = res_empty.json()
    assert data_empty["status"] == "success"
    assert data_empty["executed_tests"] == 0
    assert data_empty["has_active_results"] is False
    assert data_empty["passed"] == 0
    assert data_empty["failed"] == 0

    # Boundary 2: Multiple test cases with varying statuses
    test_cases = [
        {"name": "Cart Add", "status": "passed"},
        {"name": "Checkout Flow", "status": "passed"},
        {"name": "Payment Gateway Assert", "status": "failed"},
        {"name": "Timeout Handler", "status": "broken"},
    ]
    for i, tc in enumerate(test_cases):
        with open(os.path.join(results_dir, f"test_{i}-result.json"), "w", encoding="utf-8") as f:
            json.dump(tc, f)

    res_active = client.get("/api/reports/active-run-summary")
    assert res_active.status_code == 200
    data_active = res_active.json()
    assert data_active["total_tests"] == 4
    assert data_active["passed"] == 2
    assert data_active["failed"] == 2  # 'failed' and 'broken' count as failed


