@allure.step("BVA Test: Verify _count_robot_suite_tests does not count unindented [Tags], [Doc], or continuation lines")
def test_count_robot_suite_tests_excludes_metadata_and_tags(tmp_path):
    """
    Verifies that a Robot suite with 20 real test cases containing unindented
    [Tags], [Documentation], continuations (...), comments, and variables
    is strictly counted as 20 tests (never inflated to 21).
    """
    suite_file = tmp_path / "test_suite_with_meta.robot"

    # Construct a suite with 20 test cases, but with metadata and unindented options
    lines = [
        "*** Settings ***",
        "Library    SeleniumLibrary",
        "",
        "*** Variables ***",
        "${GLOBAL_TIMEOUT}    30s",
        "",
        "*** Test Cases ***"
    ]

    for i in range(1, 21):
        lines.append(f"Scenario {i}: Business Action {i}")
        lines.append(f"    [Documentation]    Verifies step {i}")
        lines.append(f"    [Tags]    regression    smoke")
        lines.append(f"    Log    Executing action {i}")

    # Inject traps that naive parsers count as test cases:
    lines.append("# A full line comment inside test cases section")
    lines.append("[Tags]    suite-level-tag-trap")
    lines.append("[Documentation]    unindented doc trap")
    lines.append("...    continuation trap line")
    lines.append("${INLINE_VAR}    inline assignment trap")

    suite_file.write_text("\n".join(lines), encoding="utf-8")

    count = _count_robot_suite_tests(str(suite_file))
    assert count == 20, f"Expected exactly 20 test cases, but got {count} (check metadata exclusion)"


@allure.step("BVA Test: Verify _reconcile_pabot_results_from_xml extracts exact 17 pass / 3 fail (total 20)")
def test_reconcile_pabot_results_from_xml_exact_counts(tmp_path):
    """
    Verifies that _reconcile_pabot_results_from_xml parses Robot output.xml
    and accurately computes (20, 17, 3), ensuring completed == 20 and remaining == 0.
    """
    xml_file = tmp_path / "output.xml"

    # Construct minimal valid Robot Framework output.xml with 17 PASS, 3 FAIL
    tests_xml = []
    for i in range(1, 18):
        tests_xml.append(f"""
        <test id="s1-t{i}" name="Scenario {i}: Pass Case">
            <status status="PASS" starttime="20260918 01:00:00.000" endtime="20260918 01:00:01.000"/>
        </test>
        """)
    for i in range(18, 21):
        tests_xml.append(f"""
        <test id="s1-t{i}" name="Scenario {i}: Fail Case">
            <status status="FAIL" starttime="20260918 01:00:00.000" endtime="20260918 01:00:01.000">AssertionError: Element not found</status>
        </test>
        """)

    full_xml = f"""<?xml version="1.0" encoding="UTF-8"?>
    <robot generator="Robot 7.4.2" generated="20260918 01:00:00.000">
        <suite id="s1" name="Master Suite">
            {''.join(tests_xml)}
            <status status="FAIL" starttime="20260918 01:00:00.000" endtime="20260918 01:00:20.000"/>
        </suite>
        <statistics>
            <total>
                <stat pass="17" fail="3" skip="0">All Tests</stat>
            </total>
        </statistics>
    </robot>
    """
    xml_file.write_text(full_xml, encoding="utf-8")

    rec = _reconcile_pabot_results_from_xml(str(xml_file))
    assert rec is not None
    tot, pas, fai = rec
    assert tot == 20, f"Expected total 20, got {tot}"
    assert pas == 17, f"Expected 17 passed, got {pas}"
    assert fai == 3, f"Expected 3 failed, got {fai}"
    assert pas + fai == tot


