@allure.step("BVA Test: Verify task_status.json transitions step_6 to COMPLETED upon test completion")
def test_pabot_task_status_completion_convergence():
    """Verifies that task_status.json converges to COMPLETED status and correctly preserves test metrics."""
    ts_file = "artifacts/logs/task_status.json"
    os.makedirs("artifacts/logs", exist_ok=True)

    # 1. Simulate active running Pabot state
    running_payload = {
        "status": "running",
        "progress": 85,
        "current_task": "Pabot Parallel Execution",
        "current_command": "Running Pabot Parallel Cluster [3/5 executed • 2 remaining • 0 reruns]",
        "steps": {
            "step_1": {"name": "1. Recon & CVE", "status": "COMPLETED", "required": True},
            "step_2": {"name": "2. Auth & Spider", "status": "COMPLETED", "required": True},
            "step_3": {"name": "3. MCP Synthesis", "status": "COMPLETED", "required": True},
            "step_4": {"name": "4. SDET Validation", "status": "COMPLETED", "required": True},
            "step_5": {"name": "5. Assembly", "status": "COMPLETED", "required": True},
            "step_6": {"name": "6. Pabot Parallel", "status": "RUNNING", "required": False}
        },
        "test_progress": {
            "total": 5,
            "completed": 3,
            "remaining": 2,
            "passed": 3,
            "failed": 0,
            "reruns": 0,
            "rerun_count": 0
        }
    }
    with open(ts_file, "w", encoding="utf-8") as f:
        json.dump(running_payload, f, indent=2)

    # Verify initial running state via telemetry
    telemetry_running = full_telemetry_sync()
    assert telemetry_running["task"]["steps"]["step_6"]["status"] == "RUNNING"
    assert telemetry_running["task"]["test_progress"]["completed"] == 3

    # 2. Simulate terminal completion update (as written by execute endpoint finally block)
    total_tests = 5
    completed_tests = 5
    passed_tests = 5
    failed_tests = 0
    step_status = "COMPLETED"

    with open(ts_file, "r", encoding="utf-8") as tf:
        ts_data = json.load(tf)
    ts_data["status"] = "completed"
    ts_data["current_task"] = "Pabot Execution Completed"
    ts_data["current_command"] = f"Execution finished ({passed_tests} passed, {failed_tests} failed out of {total_tests})."
    ts_data["steps"]["step_6"]["status"] = step_status
    ts_data["test_progress"] = {
        "total": total_tests,
        "completed": completed_tests,
        "remaining": 0,
        "passed": passed_tests,
        "failed": failed_tests,
        "reruns": 0,
        "rerun_count": 0
    }
    with open(ts_file, "w", encoding="utf-8") as tf:
        json.dump(ts_data, tf, indent=2)

    # Verify converged completed state via telemetry
    telemetry_completed = full_telemetry_sync()
    assert telemetry_completed["task"]["status"] == "completed"
    assert telemetry_completed["task"]["steps"]["step_6"]["status"] == "COMPLETED"
    assert telemetry_completed["task"]["test_progress"]["remaining"] == 0
    assert telemetry_completed["task"]["test_progress"]["completed"] == 5


