@allure.step("BVA Test: Verify boundary test counts (0 tests, 1 test, 100 tests)")
@pytest.mark.parametrize("total,passed,failed,expected_status", [
    (0, 0, 0, "COMPLETED"),
    (1, 1, 0, "COMPLETED"),
    (1, 0, 1, "FAILED"),
    (100, 100, 0, "COMPLETED"),
    (100, 99, 1, "FAILED"),
])
def test_pabot_completion_payload_schema_bva(total, passed, failed, expected_status):
    """Deep BVA testing of pabot_completed WebSocket message schema under boundary test counts."""
    comp_payload = {
        "type": "pabot_completed",
        "status": "completed",
        "step_status": expected_status,
        "total": total,
        "completed": total,
        "remaining": 0,
        "passed": passed,
        "failed": failed,
        "returncode": 0 if failed == 0 else 1
    }

    assert comp_payload["type"] == "pabot_completed"
    assert comp_payload["status"] == "completed"
    assert comp_payload["step_status"] == expected_status
    assert comp_payload["remaining"] == 0
    assert comp_payload["passed"] + comp_payload["failed"] == comp_payload["total"]
    assert isinstance(comp_payload["returncode"], int)


