@allure.step("Verification: CoverageMatrixEngine _resolve_target_url ignores stale example.com")
def test_coverage_matrix_engine_ignores_stale_example_com(tmp_path):
    """Verifies CoverageMatrixEngine prefers cached_user_params and pipeline_session over stale example.com."""
    base_dir = str(tmp_path)
    reports_dir = os.path.join(base_dir, "artifacts", "reports")
    logs_dir = os.path.join(base_dir, "artifacts", "logs")
    os.makedirs(reports_dir, exist_ok=True)
