@allure.step("Verification: Cookie Preloader adapts cookies with stale example.com domain to active root domain")
def test_cookie_preloader_normalizes_domain_to_target():
    """Verifies preload_clearance_cookies binds cookies to active root domain via CDP Network.setCookies."""
    mock_driver = MagicMock()

    saved_cookies = [
        {"name": "cf_clearance", "value": "secret_clearance_token_xyz", "domain": ".example.com"},
        {"name": "session_id", "value": "sess_12345"} # missing domain
    ]

    with patch("os.path.exists", return_value=True), \
         patch("builtins.open", MagicMock()), \
         patch("json.load", return_value=saved_cookies):

        injected_count = ModernUIEngine.preload_clearance_cookies(
            driver=mock_driver,
            target_url="https://dashboard.zerodha.com/trade",
            context="test_unit"
        )

        assert injected_count == 2
        assert mock_driver.execute_cdp_cmd.called

        # Verify the CDP payload sent to Chromium Network.setCookies
        set_cookies_calls = [
            call for call in mock_driver.execute_cdp_cmd.call_args_list
            if call[0][0] == "Network.setCookies"
        ]
        assert len(set_cookies_calls) == 1
        cdp_payload = set_cookies_calls[0][0][1]["cookies"]

        # Check domains are mapped to .zerodha.com
        for cookie in cdp_payload:
            assert cookie["domain"] == ".zerodha.com", f"Cookie {cookie['name']} domain was {cookie['domain']}, expected .zerodha.com"


