def test_compare_visual_screenshot(tmp_path):
    baseline_dir = "artifacts/screenshots/baselines"
    os.makedirs(baseline_dir, exist_ok=True)
    
    # Create test image
    img1 = Image.new("RGB", (100, 100), color=(255, 0, 0))
    test_shot = str(tmp_path / "shot.png")
    img1.save(test_shot)

    # First run establishes baseline
    b_name = "test_visual_req_030"
    baseline_target = os.path.abspath(f"{baseline_dir}/{b_name}.png")
    if os.path.exists(baseline_target):
        os.remove(baseline_target)

    res1 = ModernUIEngine.compare_visual_screenshot(test_shot, baseline_name=b_name, tolerance_threshold=0.05)
    assert res1["status"] == "BASELINE_ESTABLISHED"
    assert res1["passed"] is True
    assert os.path.exists(baseline_target)

    # Second run compares identical image
    res2 = ModernUIEngine.compare_visual_screenshot(test_shot, baseline_name=b_name, tolerance_threshold=0.05)
    assert res2["status"] == "PASS"
    assert res2["diff_ratio"] == 0.0
    assert res2["passed"] is True

    # Third run with different image
    img2 = Image.new("RGB", (100, 100), color=(0, 255, 0))
    diff_shot = str(tmp_path / "diff_shot.png")
    img2.save(diff_shot)
    res3 = ModernUIEngine.compare_visual_screenshot(diff_shot, baseline_name=b_name, tolerance_threshold=0.05)
    assert res3["status"] == "REGRESSION_DETECTED"
    assert res3["passed"] is False
    assert res3["diff_ratio"] > 0.05

    # Cleanup baseline
    if os.path.exists(baseline_target):
        os.remove(baseline_target)


