def test_01_log_xhr_requests_to_file():
    """
    REQ-API-029 Event-Driven:
    Validates that log_xhr_requests_to_file saves network requests to
    artifacts/crawl/xhr_requests.json with all required fields:
    method, url, headers, post_data, response_status, response_content_type.
    """
    test_requests = [
        {
            "method": "POST",
            "url": "http://localhost:8000/api/items",
            "headers": {"Content-Type": "application/json"},
            "post_data": '{"name": "test_widget"}',
            "response_status": 201,
            "response_content_type": "application/json"
        },
        {
            "method": "GET",
            "url": "http://localhost:8000/api/users/123",
            "headers": {"Accept": "application/json"},
            "post_data": None,
            "response_status": 200,
            "response_content_type": "application/json"
        }
    ]

    saved_path = ModernUIEngine.log_xhr_requests_to_file(
        driver=None,
        target_url="http://localhost:8000",
        requests_list=test_requests,
        artifacts_dir="artifacts"
    )

    assert os.path.exists(saved_path), f"xhr_requests.json was not created at {saved_path}"
    with open(saved_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    assert isinstance(data, list)
    assert len(data) >= 2

    # Verify field completeness
    first = next((d for d in data if d.get("url") == "http://localhost:8000/api/items"), None)
    assert first is not None
    assert first["method"] == "POST"
    assert "headers" in first
    assert first["response_status"] == 201
    assert "response_content_type" in first


def test_02_api_coverage_generator_full_coverage():
    """
    REQ-API-029 Ubiquitous & Unwanted Behavior:
    Verifies auto_api_tests.py covers:
    (a) GET for crawled URLs
    (b) POST/PUT/PATCH/DELETE endpoints from XHR interception
    (c) GraphQL POST with introspection query and sample query
    (d) Path-parameterized endpoints with deep BVA
    (e) Auth-required skip marking when no session token exists
    (f) Request construction with Content-Type, status assertion, JSON schema validation, and @allure.step
    """
    discovered_apis = [
        {"url": "http://localhost:8000/api/catalog", "method": "GET", "category": "DISCOVERED_ROUTE"},
        {"url": "http://localhost:8000/api/orders", "method": "POST", "category": "XHR_INTERCEPTED"},
        {"url": "http://localhost:8000/api/orders/update", "method": "PUT", "category": "XHR_INTERCEPTED"},
        {"url": "http://localhost:8000/api/orders/cancel", "method": "DELETE", "category": "XHR_INTERCEPTED"},
        {"url": "http://localhost:8000/graphql", "method": "POST", "category": "GRAPHQL"},
        {"url": "http://localhost:8000/api/users/{id}", "method": "GET", "category": "PATH_PARAMETERIZED"},
        {"url": "http://localhost:8000/api/secure/settings", "method": "GET", "requires_auth": True, "category": "AUTH_REQUIRED"}
    ]

    suite_code = APICoverageGenerator.generate_full_rag_api_suite(
        target_url="http://localhost:8000",
        discovered_apis=discovered_apis
    )

    # 1. Check all HTTP methods are covered
    assert "def test_" in suite_code
    assert "@allure.step" in suite_code
    assert "Content-Type" in suite_code

    # 2. Check GraphQL introspection query and sample query
    assert "__schema" in suite_code, "GraphQL introspection query missing from generated suite"
    assert "__typename" in suite_code or "query" in suite_code

    # 3. Check Path-Parameterized BVA
    assert "VALID_ID" in suite_code, "BVA valid ID variant missing"
    assert "INVALID_ID_ZERO" in suite_code, "BVA zero ID variant missing"
    assert "STRING_AS_ID" in suite_code, "BVA string-as-ID variant missing"
    assert "VERY_LARGE_INT" in suite_code, "BVA very large int variant missing"

    # 4. Check Auth-Required skip decorator when no token is in env
    os.environ.pop("AUTH_TOKEN", None)
    os.environ.pop("SESSION_TOKEN", None)
    assert 'pytest.mark.skip(reason="[AUTH_REQUIRED]' in suite_code

    # 5. Check JSON schema assertion
    assert "isinstance(data" in suite_code or "data = res" in suite_code

    # 6. REQ-API-032: Typing imports self-containment
    assert "from typing import Optional" in suite_code, "Typing imports missing from generated API suite"
    compile(suite_code, "<generated_api_suite>", "exec")


