def test_crawl_website_spider_engine():
    """Verify CoverageMatrixEngine.crawl_website_spider discovers pages across relative links."""
    engine = CoverageMatrixEngine(".", target_url="http://testsite.local")
    html_home = """
    <html>
        <head><title>Home Page</title></head>
        <body>
            <a href="/products">Products</a>
            <a href="/about">About Us</a>
            <a href="http://testsite.local/contact">Contact</a>
            <a href="https://external-domain.com/ad">External</a>
            <form action="/login" method="POST">
                <input type="text" name="username" id="user" />
                <input type="password" name="password" id="pwd" />
                <button type="submit">Sign In</button>
            </form>
        </body>
    </html>
    """
    html_products = """
    <html>
        <head><title>Products Page</title></head>
        <body>
            <a href="/">Home</a>
            <a href="/products/item1">Item 1</a>
            <button id="add-to-cart">Add to Cart</button>
        </body>
    </html>
    """

    def mock_get(url, **kwargs):
        resp = MagicMock()
        resp.status_code = 200
        resp.url = url
        resp.headers = {"Content-Type": "text/html"}
        if "/products" in url:
            resp.text = html_products
        else:
            resp.text = html_home
        return resp

    with patch("requests.Session.get", side_effect=mock_get):
        pages = engine.crawl_website_spider("http://testsite.local", max_depth=2, max_routes=10)
        assert len(pages) >= 2
        routes = [p["route"] for p in pages]
        assert "/" in routes
        assert "/products" in routes
        # Check discovered details: inputs, buttons, title
        home_page = next(p for p in pages if p["route"] == "/")
        assert home_page["title"] == "Home Page"
        assert home_page["inputs"] >= 2
        assert home_page["unique_buttons"] >= 1


