import os
import shutil
import tempfile
import unittest
from aspice_qa_framework.engines.modular_framework_generator import ModularTestFrameworkGenerator
from aspice_qa_framework.engines.coverage_engine import CoverageMatrixEngine

class TestModularFrameworkAndShadowDOM(unittest.TestCase):
    def setUp(self):
        self.temp_dir = tempfile.mkdtemp()
        self.generator = ModularTestFrameworkGenerator(base_dir=self.temp_dir)
        self.cov_engine = CoverageMatrixEngine(base_dir=self.temp_dir)

    def tearDown(self):
        shutil.rmtree(self.temp_dir, ignore_errors=True)

    def test_modular_framework_generation_all_tiers(self):
        """Verifies modular framework generates Robot, Python POM, API, and k6 files."""
        res = self.generator.generate_framework(
            target_url="https://example.com",
            language="python",
            framework="all",
            sdet_philosophy="keyword_driven",
            output_dir="artifacts/scripts"
        )
        self.assertEqual(res["status"], "success")
        self.assertGreaterEqual(len(res["generated_files"]), 4)

        # 1. Robot Suite & Keywords
        robot_suite = os.path.join(self.temp_dir, "artifacts", "scripts", "robot", "test_orchestration_suite.robot")
        self.assertTrue(os.path.exists(robot_suite))
        with open(robot_suite, "r", encoding="utf-8") as f:
            robot_content = f.read()
        self.assertIn("TC-JOURNEY-01:", robot_content)
        self.assertIn("Given the user sets viewport resolution", robot_content)

        # 2. Python POM & Shadow DOM
        base_page_file = os.path.join(self.temp_dir, "artifacts", "scripts", "python_pom", "pages", "base_page.py")
        self.assertTrue(os.path.exists(base_page_file))
        with open(base_page_file, "r", encoding="utf-8") as f:
            base_page_content = f.read()
        self.assertIn("def find_shadow_element", base_page_content)
        self.assertIn("def click_shadow_element", base_page_content)
        self.assertIn("def type_shadow_element", base_page_content)
        self.assertIn("allure.step", base_page_content)

        # 3. Python API Test Client & Suite
        api_test_file = os.path.join(self.temp_dir, "artifacts", "scripts", "api_tests", "test_api_endpoints.py")
        self.assertTrue(os.path.exists(api_test_file))
        with open(api_test_file, "r", encoding="utf-8") as f:
            api_content = f.read()
        self.assertIn("allure.step", api_content)

        # 4. k6 Performance Test
        k6_file = os.path.join(self.temp_dir, "artifacts", "scripts", "k6", "load_test_suite.js")
        self.assertTrue(os.path.exists(k6_file))
        with open(k6_file, "r", encoding="utf-8") as f:
            k6_content = f.read()
        self.assertIn("thousandIterationFlow", k6_content)

    def test_coverage_gap_fulfillment_allure_step_instrumentation(self):
        """Verifies synthesized coverage test cases are instrumented with allure.step blocks."""
        api_case = self.cov_engine._generate_api_test_case("/api/v1/orders", "orders", "API", "")
        self.assertIn("with allure.step", api_case)
        self.assertIn("Dispatch HTTP request", api_case)

        ui_case = self.cov_engine._generate_ui_test_case("/checkout", "checkout", "")
        self.assertIn("with allure.step", ui_case)
        self.assertIn("Navigate to target sub-route", ui_case)

if __name__ == "__main__":
    unittest.main()
''')
    create_file("tests/test_coverage_matrix_persistence.py", r'''
import os
import sys
import json
import shutil
import zipfile
import tempfile
import pytest

sys.path.insert(0, os.path.abspath("."))
from aspice_qa_framework.engines.coverage_engine import CoverageMatrixEngine


class TestCoverageMatrixPersistence:

    @pytest.fixture(autouse=True)
    def setup_and_teardown(self):
        self.matrix_path = "artifacts/reports/coverage_matrix.json"
        self.markdown_path = "artifacts/reports/coverage_matrix.md"
        yield

    def test_coverage_matrix_auto_persists_to_disk(self):
        engine = CoverageMatrixEngine(".", target_url="https://example.com")
        res = engine.analyze_coverage()

        assert "summary" in res
        assert "entities" in res
        assert res["summary"]["is_persisted"] is True
        assert os.path.exists(self.matrix_path)
        assert os.path.exists(self.markdown_path)

        with open(self.matrix_path, "r", encoding="utf-8") as f:
            persisted = json.load(f)

        assert persisted["summary"]["total_entities"] == len(res["entities"])
        assert persisted["summary"]["target_url"] == "https://example.com"
        assert len(persisted["entities"]) > 0

    def test_code_snippet_and_context_extraction(self):
        engine = CoverageMatrixEngine(".")
        tests = engine._extract_all_existing_tests()

        assert len(tests) > 0
        for t in tests:
            assert "name" in t
            assert "discipline" in t
            assert "file" in t
            assert "line" in t
            assert "code_snippet" in t
            # Snippet must be populated with executable test code
            assert len(t["code_snippet"].strip()) > 0
            assert t["discipline"] in ["UI", "API", "LOAD", "ACCEPTANCE", "SECURITY"]

    def test_smart_binding_and_route_shielding(self):
        engine = CoverageMatrixEngine(".")
        res = engine.analyze_coverage()

        # Check entity for root route '/'
        root_ent = next(e for e in res["entities"] if e["route"] == "/")
        assert root_ent is not None

        # At least one discipline on root should be covered
        ui_tests = root_ent["disciplines"]["UI"]["tests"]
        if ui_tests:
            t = ui_tests[0]
            assert t["match_type"] in ["EXACT_ROUTE", "SLUG_HEURISTIC", "SEMANTIC_VECTOR"]
            assert t["binding_confidence"] >= 0.65
            assert "binding_context" in t
            assert len(t["code_snippet"]) > 0

        # Negative shielding verification: tests targeting '/' should not falsely cover distinct child forms like '/products'
        prod_ent = next((e for e in res["entities"] if e["route"] in ["/products", "/inventory.html"]), None)
        if prod_ent:
            # The root landing test TC-UI-01 must not falsely bind to products
            prod_ui_tests = prod_ent["disciplines"]["UI"]["tests"]
            for pt in prod_ui_tests:
                assert "landing page" not in pt["name"].lower()

    def test_project_import_rehydration_without_crawl(self):
        """Simulates importing a project package where page_manifest.json is absent but coverage_matrix.json exists."""
        with tempfile.TemporaryDirectory() as temp_dir:
            temp_reports = os.path.join(temp_dir, "artifacts", "reports")
            os.makedirs(temp_reports, exist_ok=True)
            mock_matrix_file = os.path.join(temp_reports, "coverage_matrix.json")

            sample_entities = [
                {"id": "ENT-IMPORTED-01", "name": "Imported Storefront Portal", "route": "/", "type": "WEB_PAGE", "category": "CUSTOMER_JOURNEY", "elements_summary": "Root navbar"},
                {"id": "ENT-IMPORTED-02", "name": "Imported User Sign-In", "route": "/login", "type": "AUTH_FORM", "category": "AUTHENTICATION", "elements_summary": "Password inputs"},
                {"id": "ENT-IMPORTED-03", "name": "Imported Checkout Payment Flow", "route": "/checkout", "type": "CHECKOUT_FLOW", "category": "TRANSACTION", "elements_summary": "Payment inputs"}
            ]

            saved_matrix = {
                "summary": {
                    "target_url": "https://imported-enterprise-app.com",
                    "target_domain": "imported-enterprise-app.com",
                    "total_entities": 3,
                    "overall_coverage_pct": 50.0
                },
                "entities": sample_entities
            }
            with open(mock_matrix_file, "w", encoding="utf-8") as f:
                json.dump(saved_matrix, f, indent=2)

            # Initialize engine in the simulated imported directory
            imported_engine = CoverageMatrixEngine(temp_dir)
            rehydrated = imported_engine.analyze_coverage()

            assert rehydrated["summary"]["target_url"] == "https://imported-enterprise-app.com"
            assert len(rehydrated["entities"]) == 3
            routes = [e["route"] for e in rehydrated["entities"]]
            assert "/" in routes
            assert "/login" in routes
            assert "/checkout" in routes

    def test_export_and_import_roundtrip_preserves_coverage_and_vectors(self):
        """Verifies full roundtrip export to zip and import extraction preserves coverage matrix and vector store."""
        with tempfile.TemporaryDirectory() as export_dir:
            zip_target = os.path.join(export_dir, "test_export.zip")

            # 1. Generate live coverage matrix
            engine = CoverageMatrixEngine(".")
            live_matrix = engine.analyze_coverage()
            assert os.path.exists(self.matrix_path)

            # 2. Package into zip simulating /api/system/export and /api/download/package
            with zipfile.ZipFile(zip_target, "w", zipfile.ZIP_DEFLATED) as zf:
                zf.write(self.matrix_path, "artifacts/reports/coverage_matrix.json")
                if os.path.exists(self.markdown_path):
                    zf.write(self.markdown_path, "artifacts/reports/coverage_matrix.md")
                if os.path.exists("artifacts/db/dom_vector_index.json"):
                    zf.write("artifacts/db/dom_vector_index.json", "artifacts/reports/dom_vector_store.json")

            # 3. Simulate importing into an empty clean destination
            with tempfile.TemporaryDirectory() as import_dest:
                with zipfile.ZipFile(zip_target, "r") as zf:
                    zf.extractall(import_dest)

                extracted_matrix_path = os.path.join(import_dest, "artifacts", "reports", "coverage_matrix.json")
                assert os.path.exists(extracted_matrix_path)

                # If dom_vector_store.json was bundled, verify it can be restored to db
                extracted_dom_store = os.path.join(import_dest, "artifacts", "reports", "dom_vector_store.json")
                if os.path.exists(extracted_dom_store):
                    dest_db_dir = os.path.join(import_dest, "artifacts", "db")
                    os.makedirs(dest_db_dir, exist_ok=True)
                    shutil.copyfile(extracted_dom_store, os.path.join(dest_db_dir, "dom_vector_index.json"))
                    assert os.path.exists(os.path.join(dest_db_dir, "dom_vector_index.json"))

                # Analyze coverage in newly imported destination
                imported_engine = CoverageMatrixEngine(import_dest)
                restored_matrix = imported_engine.analyze_coverage()

                assert len(restored_matrix["entities"]) == len(live_matrix["entities"])
                assert restored_matrix["summary"]["total_entities"] == live_matrix["summary"]["total_entities"]
''')
    create_file("tests/test_cookie_formats.py", r'''
"""
Unit and Integration Tests for Multi-Format Cookie System:
- Netscape (cookies.txt) parsing & formatting (including #HttpOnly_ prefixes)
- Playwright (storageState.json) parsing & formatting
- cURL command parsing (auto URL extraction, -H Cookie, --cookie flags)
- Cache persistence across JSON, Netscape, and Playwright formats
- FastAPI Cookie Injection and Export Endpoints
"""

import os
import json
import pytest
import tempfile
from typing import Dict, Any, List

from aspice_qa_framework.engines.modern_ui_engine import ModernUIEngine


# ---------------------------------------------------------------------------
# 1. Netscape Parser & Formatter Tests
# ---------------------------------------------------------------------------

SAMPLE_NETSCAPE_TXT = """# Netscape HTTP Cookie File
# https://curl.se/docs/http-cookies.html
# This file was generated by libcurl! Edit at your own risk.

.example.com\tTRUE\t/\tTRUE\t1750000000\tsession_id\tabc123xyz
#HttpOnly_.example.com\tTRUE\t/\tTRUE\t1750000000\tcf_clearance\tsec_token_999
dashboard.example.com\tFALSE\t/admin\tFALSE\t0\ttheme_mode\tdark
"""

def test_parse_netscape_cookies():
    cookies = ModernUIEngine.parse_netscape_cookies(SAMPLE_NETSCAPE_TXT)
    assert len(cookies) == 3

    # Check first cookie (standard)
    c1 = next(c for c in cookies if c["name"] == "session_id")
    assert c1["value"] == "abc123xyz"
