def test_save_and_preload_clearance_cookies_filesystem(tmp_path, monkeypatch):
    test_cookies_dir = tmp_path / "artifacts" / "cookies"
    test_cookies_dir.mkdir(parents=True, exist_ok=True)
    
    # Temporarily point storage paths to tmp_path
    monkeypatch.chdir(tmp_path)

    sample_cookies = [
        {"name": "cf_clearance", "value": "synced_cf_pass", "domain": ".testsite.org", "path": "/", "secure": True, "httpOnly": True},
        {"name": "user_id", "value": "42", "domain": ".testsite.org", "path": "/", "secure": False, "httpOnly": False}
    ]

    saved_count = ModernUIEngine.save_clearance_cookies(sample_cookies, base_url="https://testsite.org")
    assert saved_count == 2

    # Verify all 3 files exist
    assert os.path.exists("artifacts/cookies/cf_session.json")
    assert os.path.exists("artifacts/cookies/storageState.json")
    assert os.path.exists("artifacts/cookies/cookies.txt")

    # Verify get_cached_cookies_dict reads from them
    cached_dict = ModernUIEngine.get_cached_cookies_dict()
    assert cached_dict["cf_clearance"] == "synced_cf_pass"
    assert cached_dict["user_id"] == "42"

    # Verify fallback: remove cf_session.json and verify storageState.json fallback
    os.remove("artifacts/cookies/cf_session.json")
    assert not os.path.exists("artifacts/cookies/cf_session.json")
    cached_from_pw = ModernUIEngine.get_cached_cookies_dict()
    assert cached_from_pw["cf_clearance"] == "synced_cf_pass"

    # Verify fallback: remove storageState.json and verify cookies.txt fallback
    os.remove("artifacts/cookies/storageState.json")
    assert not os.path.exists("artifacts/cookies/storageState.json")
    cached_from_ns = ModernUIEngine.get_cached_cookies_dict()
    assert cached_from_ns["cf_clearance"] == "synced_cf_pass"


