def test_deploy_enterprise_qa_engine_parity():
    """Validates that deploy_enterprise_qa.py ModernUIEngine has exact behavioral parity."""
    deploy_enterprise_qa = pytest.importorskip("deploy_enterprise_qa")
    DeployEngine = deploy_enterprise_qa.ModernUIEngine

    # 1. Netscape parsing parity
    ns_cookies = DeployEngine.parse_netscape_cookies(SAMPLE_NETSCAPE_TXT)
