    def test_record_ui_obstructions_manifest_persistence_and_dedup(self):
        """Verify record_ui_obstructions_manifest stores and dedupes entries by URL."""
        entry_1 = {
            "url": "https://example.com/home",
            "chat_widgets": [{"provider": "intercom", "selector": "#intercom-frame"}],
            "carousels": [{"selector": ".swiper", "slides_detected": 4}],
            "media_elements": [{"tag": "video", "selector": "video#hero"}],
            "login_gates": [],
            "total_obstructions": 3
        }
        manifest_path = ModernUIEngine.record_ui_obstructions_manifest(entry_1, artifacts_dir=self.artifacts_dir)
        self.assertTrue(os.path.exists(manifest_path))

        with open(manifest_path, "r", encoding="utf-8") as f:
            data = json.load(f)
        self.assertEqual(len(data), 1)
        self.assertEqual(data[0]["url"], "https://example.com/home")
        self.assertEqual(data[0]["total_obstructions"], 3)

        # Overwrite/dedup entry for same URL with updated status
        entry_1_updated = dict(entry_1)
        entry_1_updated["total_obstructions"] = 4
        ModernUIEngine.record_ui_obstructions_manifest(entry_1_updated, artifacts_dir=self.artifacts_dir)

        with open(manifest_path, "r", encoding="utf-8") as f:
            data_updated = json.load(f)
        self.assertEqual(len(data_updated), 1)
        self.assertEqual(data_updated[0]["total_obstructions"], 4)

