    def test_safe_handle_interaction_failure_recovers_interception(self):
        """Verify safe_handle_interaction_failure triggers universal dismiss and dynamic obstruction neutralization on interception."""
        mock_driver = MagicMock()
        mock_driver.current_url = "https://example.com/checkout"

        calls = {"count": 0}
        def intercepted_action():
            calls["count"] += 1
            if calls["count"] == 1:
                raise Exception("ElementClickInterceptedException: element click intercepted by modal overlay")
            return "SUCCESS_CLICK"

        with patch.object(ModernUIEngine, "universal_dismiss_popups") as mock_pop, \
             patch.object(ModernUIEngine, "handle_dynamic_obstructions") as mock_obs:
            result = ModernUIEngine.safe_handle_interaction_failure(
                mock_driver,
                intercepted_action,
                context_url="https://example.com/checkout",
                artifacts_dir=self.artifacts_dir
            )
            self.assertEqual(result, "SUCCESS_CLICK")
            self.assertEqual(calls["count"], 2)
            mock_pop.assert_called_once()
            mock_obs.assert_called_once()

    def test_coverage_matrix_epistemic_invariants_and_assumptions(self):
        """Verify CoverageMatrixEngine includes dynamic obstruction invariants and assumptions."""
        cov_engine = CoverageMatrixEngine()
        entities = [{"id": "E1", "route": "/home", "category": "GENERAL"}]
        epistemic = cov_engine.synthesize_epistemic_domain_model(entities)

