"""
tests/test_header_cache_health_and_resilience.py
Validates REQ-HEADER-CACHE-HEALTH-049:
- Automated "Request Header Too Large" (HTTP 400/431) & Corrupt Cache Self-Healing
- Pre-Assertion & Pre-Screenshot Page Health Verification
- Cumulative cookie header size bounding under 2500 bytes
- Elimination of corrupt error screenshots in test reports ([PAGE_HEALTH_FAILURE] tagging)
- WebDriver persistent network cache disabling
"""
import os
import json
import pytest
from unittest.mock import MagicMock, patch
from aspice_qa_framework.engines.api_coverage_generator import APICoverageGenerator
from aspice_qa_framework.engines.modern_ui_engine import ModernUIEngine
from aspice_qa_framework.engines.ai_core_engine import generate_guaranteed_pom_suite


class MockResponse:
    def __init__(self, status_code=200, text="", headers=None):
        self.status_code = status_code
        self.text = text
        self.headers = headers or {}


def test_verify_api_response_skips_too_big_request_header():
    """
    REQ-HEADER-CACHE-HEALTH-049:
    HTTP 400 with 'too big request header' or 'size of a request header field exceeds server limit'
    must trigger pytest.skip with [GATEWAY_HEADER_OVERFLOW_BLOCKED].
    """
    res = MockResponse(
        status_code=400,
        text="<html><head><title>400 Bad Request</title></head><body><h1>Bad Request</h1><p>Size of a request header field exceeds server limit (too big request header).</p></body></html>",
        headers={"Server": "nginx", "Content-Type": "text/html"}
    )
    with pytest.raises(pytest.skip.Exception) as exc_info:
        APICoverageGenerator._verify_api_response(res, "GET", "https://zerodha.com/funds", 4000, 150)
    assert "[GATEWAY_HEADER_OVERFLOW_BLOCKED]" in str(exc_info.value)


def test_verify_api_response_skips_http_431():
    """
    REQ-HEADER-CACHE-HEALTH-049:
    HTTP 431 Request Header Fields Too Large must trigger pytest.skip with [GATEWAY_HEADER_OVERFLOW_BLOCKED].
    """
    res = MockResponse(
        status_code=431,
        text="431 Request Header Fields Too Large",
        headers={"Content-Type": "text/plain"}
    )
    with pytest.raises(pytest.skip.Exception) as exc_info:
        APICoverageGenerator._verify_api_response(res, "GET", "https://zerodha.com/orders", 4000, 110)
    assert "[GATEWAY_HEADER_OVERFLOW_BLOCKED]" in str(exc_info.value)


def test_modern_ui_engine_cookie_bound_under_2500():
    """
    REQ-HEADER-CACHE-HEALTH-049:
    get_sanitized_clearance_cookies must bound total accumulated cookie length to under 2500 bytes.
    """
    mock_cookies = [
        {"name": f"cf_token_{i}", "value": "a" * 300, "domain": ".example.com"}
        for i in range(20)
    ]
    with patch.object(ModernUIEngine, "get_available_clearance_cookies", return_value=mock_cookies):
        with patch.object(ModernUIEngine, "validate_and_sanitize_cookie", side_effect=lambda c, target_url=None: c):
            sanitized = ModernUIEngine.get_sanitized_clearance_cookies(target_url="https://example.com")
            total_len = sum(len(c["name"]) + len(c["value"]) + 4 for c in sanitized)
            assert total_len <= 2500, f"Total cookie length {total_len} exceeded 2500 bytes bound"


def test_modern_ui_engine_handle_400_clears_cache_and_cookies():
    """
    REQ-HEADER-CACHE-HEALTH-049:
    handle_400_bad_request_and_recover must invoke clearBrowserCookies, clearBrowserCache,
    setCacheDisabled, and delete_all_cookies.
    """
    mock_driver = MagicMock()
    mock_driver.title = "400 Bad Request"
    body_mock = MagicMock()
    body_mock.text = "Request Header Or Cookie Too Large (too big request header)"
    mock_driver.find_elements.return_value = [body_mock]

    recovered = ModernUIEngine.handle_400_bad_request_and_recover(mock_driver, target_url="https://target.com/page")
    assert recovered is True
    # Verify CDP commands invoked
    cdp_calls = [call[0][0] for call in mock_driver.execute_cdp_cmd.call_args_list]
    assert "Network.clearBrowserCookies" in cdp_calls
    assert "Network.clearBrowserCache" in cdp_calls
    assert "Network.setCacheDisabled" in cdp_calls
    mock_driver.delete_all_cookies.assert_called_once()
    # Verify cache-busting navigation was triggered
    mock_driver.get.assert_called_once()
    assert "_nocache=" in mock_driver.get.call_args[0][0]


