@allure.epic("Resilience & Stability Framework")
@allure.feature("Cross-Feature Stability & Reliability Engine")
class TestCrossFeatureStabilityCheck:

    @allure.story("Event-Driven - Multi-Iteration Run & Flakiness Index Calculation")
    def test_multi_iteration_flakiness_calculation(self, tmp_path):
        with allure.step("Arrange: Define test suite execution outcomes with simulated flakiness"):
            # Suite 1: passes run 1 & 2, fails run 3 (Flaky)
            # Suite 2: passes all 3 runs (Stable)
            # Suite 3: fails all 3 runs with anti-bot (Deterministic Failure)
            call_count = {"suite1": 0, "suite2": 0, "suite3": 0}

            def mock_run_cmd(cmd, **kwargs):
                cmd_str = " ".join(cmd)
                mock_proc = MagicMock()
                if "suite1" in cmd_str:
                    call_count["suite1"] += 1
                    mock_proc.returncode = 0 if call_count["suite1"] < 3 else 1
                    mock_proc.stdout = "PASSED" if mock_proc.returncode == 0 else "FAILED: assertion error"
                elif "suite2" in cmd_str:
                    call_count["suite2"] += 1
                    mock_proc.returncode = 0
                    mock_proc.stdout = "PASSED"
                elif "suite3" in cmd_str:
                    call_count["suite3"] += 1
                    mock_proc.returncode = 1
                    mock_proc.stdout = "[COOKIE_CLEARANCE_UNAVAILABLE] Access blocked by Cloudflare"
                else:
                    mock_proc.returncode = 0
                    mock_proc.stdout = "PASSED"
                mock_proc.stderr = ""
                return mock_proc

            discovered_tests = [
                {"id": "suite1", "path": "tests/suite1.py", "feature": "Auth", "framework": "pytest"},
                {"id": "suite2", "path": "tests/suite2.py", "feature": "Dashboard", "framework": "pytest"},
                {"id": "suite3", "path": "tests/suite3.py", "feature": "Billing", "framework": "pytest"}
            ]

        with allure.step("Act: Execute stability check across 3 iterations"):
            with patch("subprocess.run", side_effect=mock_run_cmd), \
                 patch("aspice_qa_framework.main.discover_available_test_suites", return_value=discovered_tests):
                
                report = run_stability_check(iterations=3)

        with allure.step("Assert: Validate aggregated metrics and flakiness scores"):
            assert report["iterations"] == 3
            assert report["total_suites_evaluated"] == 3
            assert report["total_executions"] == 9
            # suite1: 2 pass 1 fail. suite2: 3 pass. suite3: 3 fail. Total pass: 5/9
            assert report["total_passed"] == 5
            assert report["total_failed"] == 4
            assert report["overall_pass_rate"] == round(5 / 9 * 100, 1)
            
            # Check flaky suites: suite1 should be identified as flaky
            assert len(report["flaky_suites"]) == 1
            assert report["flaky_suites"][0]["suite_id"] == "suite1"
            assert report["flaky_suites"][0]["flakiness_rate"] == 0.33
            
            # Check feature_reliability_matrix
            auth_matrix = next(m for m in report["feature_reliability_matrix"] if m["feature"] == "Auth")
            assert auth_matrix["flaky_count"] == 1
            assert auth_matrix["passed_runs"] == 2
            assert auth_matrix["failed_runs"] == 1

            # Check failure taxonomy
            taxonomy = report["failure_taxonomy"]
            assert taxonomy.get("COOKIE_CLEARANCE_UNAVAILABLE", 0) >= 3

