"""
Integration and Unit Verification Tests for SeleniumBase UC Engine Feature:
- Enable / Disable toggles via UI, API payload (GenConfig), and environment variables
- Resilient Driver creation in ModernUIEngine with UC Mode and graceful fallback
- Spider crawling stealth driver initialization in AICoreEngine
- Worker pipeline execution flag propagation (ENABLE_SELENIUMBASE)
- Generated Robot Framework keywords library template verification
- Native seleniumbase availability and signature validation
"""

import os
import sys
import json
import pytest
from unittest.mock import patch, MagicMock

from aspice_qa_framework.engines.modern_ui_engine import ModernUIEngine
from aspice_qa_framework.engines.ai_core_engine import AICoreEngine, generate_guaranteed_keywords_lib
from aspice_qa_framework.main import GenConfig


# ---------------------------------------------------------------------------
# 1. Native SeleniumBase Availability and Environment Sanity
# ---------------------------------------------------------------------------

def test_seleniumbase_package_available():
    """Verify that seleniumbase is installed and exports the expected Driver."""
    import seleniumbase
    assert hasattr(seleniumbase, "Driver"), "seleniumbase module must export Driver"
    assert hasattr(seleniumbase, "__version__"), "seleniumbase must have a version string"


# ---------------------------------------------------------------------------
# 2. ModernUIEngine.create_resilient_driver: Enable vs Disable Verification
# ---------------------------------------------------------------------------

def test_modern_ui_engine_seleniumbase_enabled():
    """When use_seleniumbase=True, ModernUIEngine creates a driver using seleniumbase.Driver(uc=True)."""
    mock_sb_driver = MagicMock(name="SeleniumBaseDriverInstance")

    with patch("seleniumbase.Driver", return_value=mock_sb_driver) as mock_driver_cls:
        driver = ModernUIEngine.create_resilient_driver(
            use_seleniumbase=True,
            headless=True,
            proxy_url="http://proxy.internal:8080",
            target_lang="es-ES",
            user_data_dir="/tmp/test_profile"
        )
        assert driver == mock_sb_driver
        mock_driver_cls.assert_called_once_with(
            browser="chrome",
            uc=True,
            headless=True,
            proxy="http://proxy.internal:8080",
            user_data_dir="/tmp/test_profile"
        )


def test_modern_ui_engine_seleniumbase_disabled():
    """When use_seleniumbase=False, ModernUIEngine does NOT call seleniumbase.Driver."""
    mock_sb_driver = MagicMock(name="SeleniumBaseDriverInstance")
    mock_std_driver = MagicMock(name="StandardDriverInstance")

    with patch("seleniumbase.Driver", return_value=mock_sb_driver) as mock_sb_cls, \
         patch("selenium.webdriver.Chrome", return_value=mock_std_driver), \
         patch("selenium.webdriver.chrome.service.Service", return_value=MagicMock()), \
         patch.dict(sys.modules, {"undetected_chromedriver": None}):

        driver = ModernUIEngine.create_resilient_driver(
            use_seleniumbase=False,
            headless=False
        )
        # Verify seleniumbase was NOT invoked
        mock_sb_cls.assert_not_called()
        assert driver is not None


def test_modern_ui_engine_seleniumbase_fallback_on_error():
    """When use_seleniumbase=True but seleniumbase.Driver fails, it falls back gracefully."""
    mock_std_driver = MagicMock(name="FallbackStandardDriver")

    with patch("seleniumbase.Driver", side_effect=Exception("Chromedriver mismatch error")) as mock_sb_cls, \
         patch("selenium.webdriver.Chrome", return_value=mock_std_driver), \
         patch("selenium.webdriver.chrome.service.Service", return_value=MagicMock()), \
         patch.dict(sys.modules, {"undetected_chromedriver": None}):

        driver = ModernUIEngine.create_resilient_driver(
            use_seleniumbase=True,
            headless=False
        )
        mock_sb_cls.assert_called_once()
        assert driver == mock_std_driver


# ---------------------------------------------------------------------------
