import os
import json
import zipfile
import shutil
import pytest
from PIL import Image

try:
    import allure
except ImportError:
    class _AllureStub:
        def step(self, name):
            def decorator(func):
                def wrapper(*args, **kwargs):
                    return func(*args, **kwargs)
                return wrapper
            return decorator
    allure = _AllureStub()

from aspice_qa_framework.engines.ai_core_engine import (
    generate_guaranteed_mrd,
    generate_guaranteed_scenarios_md,
    generate_guaranteed_robot_suite
)
from aspice_qa_framework.engines.modern_ui_engine import ModernUIEngine
from aspice_qa_framework.engines.vector_dom_engine import DOMVectorEngine
from aspice_qa_framework.keywords_lib import SUTKeywords


@allure.step("Test: MRD entity cataloging and in/out-domain traceability generation")
def test_generate_guaranteed_mrd_entity_catalog_and_traceability(tmp_path):
    target_url = "https://app.enterprise-portal.com"
    manifest = [
        {
            "url": "https://app.enterprise-portal.com",
            "name": "Landing",
            "verified_buttons": [{"selector": "button.btn-login", "text": "Log In"}],
            "verified_links": [
                {"selector": "a.nav-home", "href": "https://app.enterprise-portal.com/home", "text": "Home"},
                {"selector": "a.ext-github", "href": "https://github.com/enterprise/repo", "text": "GitHub Repo"}
            ],
            "verified_inputs": [{"selector": "input#username", "name": "user", "type": "text"}]
        },
        {
            "url": "https://app.enterprise-portal.com/dashboard",
            "name": "Dashboard",
            "verified_buttons": [{"selector": "button#btn-create", "text": "Create"}],
            "verified_links": [
                {"selector": "a.ext-docs", "href": "https://docs.external.io", "text": "External Docs"}
            ]
        }
    ]

    mrd_md = generate_guaranteed_mrd(target_url=target_url, page_manifest=manifest)

    # 1. Assert markdown contains in-domain and outside-domain coverage
    assert "[EPIC-NAV] In-Domain Navigation" in mrd_md or "[EPIC-NAV] Header Navigation" in mrd_md
    assert "[EPIC-EXT-LINK] Outside-Domain Integration" in mrd_md
    assert "[EPIC-VISUAL] 1-to-1 Visual Baseline Verification" in mrd_md

    # 2. Assert artifacts/reports/mrd.json was generated
    mrd_json_path = "artifacts/reports/mrd.json"
    assert os.path.exists(mrd_json_path)
    with open(mrd_json_path, "r", encoding="utf-8") as f:
        mrd_data = json.load(f)

    assert "summary" in mrd_data
    assert mrd_data["summary"]["total_entities"] > 0
    assert mrd_data["summary"]["in_domain_count"] > 0
    assert mrd_data["summary"]["outside_domain_count"] >= 1

    entities = mrd_data["entities"]
    outside_links = [e for e in entities if e.get("domain_relation") == "outside_domain"]
    assert len(outside_links) >= 1
    assert any("github.com" in e.get("href", "") or "docs.external.io" in e.get("href", "") for e in outside_links)


@allure.step("Test: Scenario generation bidirectional [TRACE:MRD-...] tags")
def test_generate_guaranteed_scenarios_bidirectional_trace_tags():
    target_url = "https://app.enterprise-portal.com"
    manifest = [
        {
            "url": "https://app.enterprise-portal.com",
            "name": "Landing",
            "verified_buttons": [{"selector": "button#cta", "text": "Get Started"}],
            "verified_inputs": []
        }
    ]

