@allure.step("Test: REQ-ORCH-035: Execution SLA guards, process timeouts, and anti-hang resilience")
def test_orch_035_execution_sla_guards_and_anti_hang(monkeypatch):
    import subprocess
    from aspice_qa_framework.keywords_lib import SUTKeywords
    from aspice_qa_framework.engines.ai_core_engine import generate_guaranteed_keywords_lib, generate_guaranteed_robot_suite, AICoreEngine

    # 1. Verify SUTKeywords handles subprocess.TimeoutExpired gracefully
    sut = SUTKeywords("https://testsite.local")

    def mock_subprocess_run_timeout(*args, **kwargs):
        assert kwargs.get("timeout") == 60, f"Expected timeout=60, got {kwargs.get('timeout')}"
        raise subprocess.TimeoutExpired(cmd=args[0], timeout=kwargs.get("timeout"))

    # Ensure fake auto_ui_test.py exists for keyword execution
    os.makedirs("artifacts/scripts", exist_ok=True)
    fake_ui_test = "artifacts/scripts/auto_ui_test.py"
    had_fake = os.path.exists(fake_ui_test)
    if not had_fake:
        with open(fake_ui_test, "w", encoding="utf-8") as f:
            f.write("# dummy test file\n")

    try:
        monkeypatch.setattr(subprocess, "run", mock_subprocess_run_timeout)
        # Should catch TimeoutExpired and return True cleanly without hanging
        assert sut.run_ui_pytest_suite() is True
        assert sut.run_api_pytest_suite() is True
    finally:
        pass

    # 2. Verify Robot suite generator includes [Timeout] 90s on orchestration test cases
    robot_code = generate_guaranteed_robot_suite(
        target_url="https://testsite.local",
        username="admin",
        password="secretpassword",
        page_manifest=[{"url": "https://testsite.local/pricing", "name": "Pricing"}],
        apis=[]
    )
    assert "[Timeout]    90s" in robot_code
    assert "TC-ORCH-01: Execute Advanced UI Pytest Suite" in robot_code
    orch_block = robot_code.split("TC-ORCH-01: Execute Advanced UI Pytest Suite")[1].split("TC-ORCH-02:")[0]
    assert "[Timeout]    90s" in orch_block

    # 3. Verify Keywords Lib generator contains timeout=60 and timeout handler
    kw_code = generate_guaranteed_keywords_lib(
        target_url="https://testsite.local",
        username="admin",
        password="secretpassword",
        page_manifest=[],
        apis=[]
    )
    assert "timeout=60" in kw_code
    assert "[ORCH_TIMEOUT_EXPIRED]" in kw_code

    # 4. Verify sanitize_ui_script injects set_page_load_timeout(20)
    ai_eng = AICoreEngine(driver=None, ollama_url="http://localhost:11434")
    dummy_path = "artifacts/scripts/dummy_ui_test.py"
    with open(dummy_path, "w", encoding="utf-8") as f:
        f.write("import unittest\nclass TestUI(unittest.TestCase):\n    def setUp(self):\n        self.driver = create_stealth_driver()\n")
    ai_eng.sanitize_ui_script(dummy_path, "https://testsite.local")
    with open(dummy_path, "r", encoding="utf-8") as f:
        sanitized = f.read()
    assert "set_page_load_timeout(20)" in sanitized
    assert "set_script_timeout(20)" in sanitized



''')

    create_file("tests/test_multiplatform_bot_protection.py", r'''
import os
import json
import unittest
from unittest.mock import MagicMock, patch
from fastapi.testclient import TestClient

from aspice_qa_framework.main import app
from aspice_qa_framework.engines.modern_ui_engine import ModernUIEngine
from aspice_qa_framework.engines.ai_core_engine import generate_guaranteed_keywords_lib

client = TestClient(app)

class TestMultiPlatformBotProtection(unittest.TestCase):

    def test_cloudflare_turnstile_detection(self):
        """Verifies detection of Cloudflare Turnstile and Ray ID."""
        mock_driver = MagicMock()
        mock_driver.title = "Just a moment..."
        mock_driver.page_source = """
        <html>
            <head><title>Just a moment...</title></head>
            <body>
                <div id="challenge-stage">
                    <iframe src="https://challenges.cloudflare.com/cdn-cgi/challenge-platform/h/b/turnstile"></iframe>
                </div>
                <div class="footer">Ray ID: 7f8a9b0c1d2e3f4a</div>
            </body>
        </html>
        """
        mock_driver.get_cookies.return_value = []
        mock_driver.find_elements.return_value = []

        diag = ModernUIEngine.detect_bot_protection_type(mock_driver)
        self.assertTrue(diag["is_active"])
        self.assertEqual(diag["provider"], "CLOUDFLARE_TURNSTILE")
        self.assertEqual(diag["ray_or_request_id"], "7f8a9b0c1d2e3f4a")
        self.assertIn("cf_clearance", diag["missing_critical_cookies"])
        self.assertTrue(len(diag["mitigation_advice"]) > 0)

    def test_datadome_detection(self):
        """Verifies detection of DataDome challenge barriers."""
        mock_driver = MagicMock()
        mock_driver.title = "Access Denied"
        mock_driver.page_source = """
        <html>
            <head><title>Access Denied</title></head>
            <body>
                <iframe src="https://geo.captcha-delivery.com/captcha/?initialCid=AHrlqAAAAAMA..."></iframe>
                <script src="https://ct.captcha-delivery.com/c.js"></script>
            </body>
        </html>
        """
        mock_driver.get_cookies.return_value = []
        mock_driver.find_elements.return_value = []

        diag = ModernUIEngine.detect_bot_protection_type(mock_driver)
        self.assertTrue(diag["is_active"])
        self.assertEqual(diag["provider"], "DATADOME")
        self.assertIn("datadome", diag["missing_critical_cookies"])

    def test_perimeterx_detection(self):
        """Verifies detection of PerimeterX / HUMAN Security challenges."""
        mock_driver = MagicMock()
        mock_driver.title = "Access Denied"
        mock_driver.page_source = """
        <html>
            <body>
                <div id="px-captcha"></div>
                <div>Press and Hold to confirm you are human</div>
            </body>
        </html>
        """
        mock_driver.get_cookies.return_value = []
        mock_driver.find_elements.return_value = []

        diag = ModernUIEngine.detect_bot_protection_type(mock_driver)
        self.assertTrue(diag["is_active"])
        self.assertEqual(diag["provider"], "PERIMETERX")
        self.assertIn("_px3", diag["missing_critical_cookies"])

    def test_aws_waf_detection(self):
        """Verifies detection of AWS WAF Captcha."""
        mock_driver = MagicMock()
        mock_driver.title = "AWS WAF Verification"
        mock_driver.page_source = """
        <html>
            <body>
                <div id="aws-waf-captcha"></div>
                <script src="https://token.awswaf.com/token.js"></script>
            </body>
        </html>
        """
        mock_driver.get_cookies.return_value = []
        mock_driver.find_elements.return_value = []

        diag = ModernUIEngine.detect_bot_protection_type(mock_driver)
        self.assertTrue(diag["is_active"])
        self.assertEqual(diag["provider"], "AWS_WAF")
        self.assertIn("aws-waf-token", diag["missing_critical_cookies"])

    def test_standard_page_false_positive_guard(self):
        """Verifies standard web applications are not falsely flagged as bot challenges."""
        mock_driver = MagicMock()
        mock_driver.title = "Welcome to Enterprise Store"
        mock_driver.page_source = """
        <html>
            <body>
                <nav><a href="/home">Home</a><a href="/products">Products</a></nav>
                <header><h1>Best Products</h1></header>
                <main><div>Some content powered by cloudflare cdn</div></main>
                <form><input type="text" name="q"><button>Search</button></form>
            </body>
        </html>
        """
        mock_driver.get_cookies.return_value = []
        # Simulate 4+ interactive elements
        mock_driver.find_elements.return_value = [MagicMock(), MagicMock(), MagicMock(), MagicMock()]

        diag = ModernUIEngine.detect_bot_protection_type(mock_driver)
        self.assertFalse(diag["is_active"])
        self.assertEqual(diag["provider"], "NONE")

    def test_diagnose_failure_cause_with_missing_cookie(self):
        """Verifies failure diagnostics outputs structured remediation steps for missing clearance cookie."""
        mock_driver = MagicMock()
        mock_driver.title = "Just a moment..."
        mock_driver.page_source = "<div id='challenge-stage'><iframe src='https://challenges.cloudflare.com'></iframe></div>"
        mock_driver.get_cookies.return_value = []
        mock_driver.find_elements.return_value = []
        mock_driver.current_url = "https://protected.target.com/dashboard"

        diag = ModernUIEngine.diagnose_failure_cause(mock_driver, exception=Exception("ElementNotFound: #submit-btn"))
        self.assertEqual(diag["failure_category"], "COOKIE_MISSING_OR_EXPIRED")
        self.assertIn("cf_clearance", diag["root_cause"])
        self.assertTrue(len(diag["recommended_steps"]) >= 3)
        self.assertIn("SUT.Inject Clearance Cookies From Storage", diag["suggested_robot_snippet"])
        self.assertIn("ModernUIEngine.preload_clearance_cookies", diag["suggested_python_snippet"])

    def test_sut_keywords_anti_bot_execution(self):
        """Verifies SUTKeywords anti-bot keywords run cleanly in generated library."""
        code = generate_guaranteed_keywords_lib("https://target.com", "admin", "secret", [], [])
        self.assertIn("def verify_bot_protection_status", code)
        self.assertIn("def diagnose_and_recover_from_bot_barrier", code)
        self.assertIn("def inject_clearance_cookies_from_storage", code)
        self.assertIn("def export_current_session_cookies", code)
        self.assertIn("def safe_click_with_anti_bot_guard", code)
        self.assertIn("def wait_for_bot_challenge_resolved", code)

        local_scope = {}
        exec(code, local_scope)
        SUTKeywordsCls = local_scope["SUTKeywords"]

        mock_driver = MagicMock()
        mock_driver.title = "Normal App"
        mock_driver.page_source = "<div>Clean App</div>"
        mock_driver.get_cookies.return_value = []
        mock_driver.find_elements.return_value = [MagicMock(), MagicMock(), MagicMock(), MagicMock()]

        keywords = SUTKeywordsCls()
        keywords.driver = mock_driver

        status = keywords.verify_bot_protection_status()
        self.assertFalse(status.get("is_active"))

        resolved = keywords.wait_for_bot_challenge_resolved(timeout=1)
        self.assertTrue(resolved)

    def test_api_bot_protection_status_and_inject(self):
        """Verifies API endpoints for bot protection status and manual cookie injection."""
        # 1. Status endpoint
        res = client.get("/api/bot-protection/status")
        self.assertEqual(res.status_code, 200)
        data = res.json()
        self.assertEqual(data["status"], "success")
        self.assertIn("summary", data)
        self.assertIn("saved_cookies", data)

        # 2. Inject endpoint
        payload = {
            "cookies": [
                {"name": "cf_clearance", "value": "mock_clearance_token_xyz", "domain": ".target.com"},
                {"name": "datadome", "value": "mock_dd_token_123", "domain": ".target.com"}
            ],
            "domain": ".target.com"
        }
        res_post = client.post("/api/bot-protection/inject-cookies", json=payload)
        self.assertEqual(res_post.status_code, 200)
        post_data = res_post.json()
        self.assertEqual(post_data["status"], "success")
        self.assertTrue(post_data["total_saved"] >= 2)

if __name__ == "__main__":
    unittest.main()

''')

    create_file("tests/test_spider_crawler_multipage.py", r'''
import unittest
from unittest.mock import MagicMock, patch
import requests
import tempfile
import shutil
from aspice_qa_framework.engines.coverage_engine import CoverageMatrixEngine

class TestSpiderCrawlerMultipage(unittest.TestCase):
    def setUp(self):
        self.temp_dir = tempfile.mkdtemp()
        self.engine = CoverageMatrixEngine(self.temp_dir)

    def tearDown(self):
        shutil.rmtree(self.temp_dir, ignore_errors=True)

    def test_spider_crawls_multiple_pages_and_subroutes(self):
        """Verify that spider crawl does not stop at page 1 and traverses sub-routes."""
        # Page 1 (Home)
        html_page1 = """
        <!DOCTYPE html>
        <html>
        <head><title>Test Store Home</title></head>
        <body>
            <nav>
                <a href="/products">Products</a>
                <a href="/about">About Us</a>
                <a href="/contact">Contact</a>
            </nav>
            <form action="/search">
                <input type="text" name="q" placeholder="Search" />
                <button type="submit">Search</button>
            </form>
        </body>
        </html>
        """
        # Page 2 (Products)
        html_page2 = """
        <!DOCTYPE html>
        <html>
        <head><title>Products Catalog</title></head>
        <body>
            <h1>Products</h1>
            <div class="product">
                <a href="/products/item-1">Item 1</a>
                <button data-route="/cart">Add to Cart</button>
            </div>
        </body>
        </html>
        """
        # Page 3 (About)
        html_page3 = """
        <!DOCTYPE html>
        <html>
        <head><title>About Us</title></head>
        <body>
            <p>We build great software.</p>
            <a href="/contact">Contact Us</a>
        </body>
        </html>
        """
        # Page 4 (Contact)
        html_page4 = """
        <!DOCTYPE html>
        <html>
        <head><title>Contact</title></head>
        <body>
            <form action="/send-message">
                <input type="email" name="email" />
                <button type="submit">Send</button>
            </form>
        </body>
        </html>
        """

        mock_responses = {
            "https://teststore.local": html_page1,
            "https://teststore.local/": html_page1,
            "https://teststore.local/products": html_page2,
            "https://teststore.local/about": html_page3,
            "https://teststore.local/contact": html_page4,
            "https://teststore.local/cart": "<html><body>Cart</body></html>",
            "https://teststore.local/products/item-1": "<html><body>Item 1 details</body></html>"
        }

        def mock_get(url, *args, **kwargs):
            html = mock_responses.get(url) or mock_responses.get(url.rstrip('/')) or mock_responses.get(url + '/') or "<html><body>Default</body></html>"
            mock_res = MagicMock()
            mock_res.status_code = 200
            mock_res.text = html
            mock_res.url = url
            mock_res.headers = {"content-type": "text/html; charset=utf-8"}
            return mock_res

        with patch.object(requests.Session, 'get', side_effect=mock_get):
            crawled = self.engine.crawl_website_spider("https://teststore.local", max_depth=2, max_routes=10)

        # Must crawl MORE than just the 1st page!
        self.assertGreater(len(crawled), 1, "Spider crawler must not stop at page 1!")
        urls_crawled = [p["url"].rstrip('/') for p in crawled]
        self.assertIn("https://teststore.local", urls_crawled)
        self.assertIn("https://teststore.local/products", urls_crawled)
        self.assertIn("https://teststore.local/about", urls_crawled)
        self.assertIn("https://teststore.local/contact", urls_crawled)

    def test_spider_handles_spa_attribute_routes(self):
        """Verify data-route and button links are discovered in SPAs."""
        html_spa = """
        <!DOCTYPE html>
        <html>
        <head><title>SPA Dashboard</title></head>
        <body>
            <div data-route="/dashboard/analytics">Analytics</div>
            <button data-url="/dashboard/settings">Settings</button>
            <a href="#/profile">Profile</a>
        </body>
        </html>
        """
        mock_responses = {
            "https://spademo.local": html_spa,
            "https://spademo.local/": html_spa,
            "https://spademo.local/dashboard/analytics": "<html><body>Analytics Page</body></html>",
            "https://spademo.local/dashboard/settings": "<html><body>Settings Page</body></html>"
        }

        def mock_get(url, *args, **kwargs):
            html = mock_responses.get(url) or mock_responses.get(url.rstrip('/')) or mock_responses.get(url + '/') or "<html><body>Default</body></html>"
            mock_res = MagicMock()
            mock_res.status_code = 200
            mock_res.text = html
            mock_res.url = url
            mock_res.headers = {"content-type": "text/html; charset=utf-8"}
            return mock_res

        with patch.object(requests.Session, 'get', side_effect=mock_get):
            crawled = self.engine.crawl_website_spider("https://spademo.local", max_depth=2, max_routes=10)

        urls_crawled = [p["url"].rstrip('/') for p in crawled]
        self.assertIn("https://spademo.local/dashboard/analytics", urls_crawled)
        self.assertIn("https://spademo.local/dashboard/settings", urls_crawled)

    def test_intelligent_auth_and_spider_resilience_when_driver_preexists(self):
        """Verify that intelligent_auth_and_spider does not fail with UnboundLocalError when driver pre-exists."""
        from aspice_qa_framework.engines.ai_core_engine import AICoreEngine
        mock_driver = MagicMock()
        mock_driver.session_id = "mock_session_123"
        mock_driver.current_url = "https://spademo.local/"
        mock_driver.page_source = "<html><head><title>Home</title></head><body><a href='/dashboard'>Dashboard</a><input type='text' id='search' /></body></html>"
        mock_driver.find_elements.return_value = []
        mock_driver.execute_script.return_value = []
        mock_driver.get_cookies.return_value = []
        engine = AICoreEngine(driver=mock_driver, ollama_url="http://localhost:11434")
        engine.wait_for_page_ready = MagicMock()

        with patch("time.sleep", return_value=None), \
             patch("aspice_qa_framework.engines.modern_ui_engine.ModernUIEngine.handle_seleniumbase_challenges", return_value=True), \
             patch("aspice_qa_framework.engines.modern_ui_engine.ModernUIEngine.wait_for_page_loaders", return_value=True):
            # Should run without UnboundLocalError: local variable 'use_sb' referenced before assignment
            doms, manifest, apis = engine.intelligent_auth_and_spider("https://spademo.local/", "admin", "password", max_depth=1, max_routes=2)
            self.assertTrue(len(doms) >= 1)
            self.assertTrue(len(manifest) >= 1)

    def test_intelligent_auth_and_spider_page_manifest_resilience_on_driver_exception(self):
        """REQ-CRAWL-031: Verify intelligent_auth_and_spider never raises NameError: page_manifest on driver exception."""
        from aspice_qa_framework.engines.ai_core_engine import AICoreEngine
        engine = AICoreEngine(driver=None, ollama_url="http://localhost:11434")
        engine.get_or_create_stealth_driver = MagicMock(side_effect=RuntimeError("Chromium binary failed to start"))

        doms, manifest, is_auth = engine.intelligent_auth_and_spider(
            "https://crash.local/", "admin", "password", max_depth=1, max_routes=2
        )
        self.assertIsInstance(doms, list)
        self.assertIsInstance(manifest, list)
        self.assertFalse(is_auth)
        self.assertTrue(len(manifest) >= 1)
        self.assertEqual(manifest[0]["status"], "CRAWL_CRASH")
        self.assertIn("https://crash.local", manifest[0]["url"])
        self.assertEqual(engine.page_manifest, manifest)

    def test_intelligent_auth_and_spider_page_manifest_on_antibot_barrier(self):
        """REQ-CRAWL-031: Verify page_manifest is properly initialized when blocked by anti-bot on root URL."""
        from aspice_qa_framework.engines.ai_core_engine import AICoreEngine
        mock_driver = MagicMock()
        mock_driver.session_id = "mock_session_456"
        mock_driver.current_url = "https://protected.local/"
        mock_driver.page_source = "<html><head><title>Just a moment...</title></head><body>cf-turnstile-wrapper Security Verification</body></html>"
        mock_driver.find_elements.return_value = []
        mock_driver.execute_script.return_value = []
        mock_driver.get_cookies.return_value = []
        engine = AICoreEngine(driver=mock_driver, ollama_url="http://localhost:11434")
        engine.wait_for_page_ready = MagicMock()

        with patch("time.sleep", return_value=None), \
             patch("aspice_qa_framework.engines.modern_ui_engine.ModernUIEngine.handle_seleniumbase_challenges", return_value=False), \
             patch("aspice_qa_framework.engines.modern_ui_engine.ModernUIEngine.wait_for_page_loaders", return_value=True), \
             patch("aspice_qa_framework.engines.modern_ui_engine.ModernUIEngine.is_bot_challenge_active", return_value=True), \
             patch("aspice_qa_framework.engines.modern_ui_engine.ModernUIEngine.handle_challenge_and_recover", return_value=False):
            doms, manifest, is_auth = engine.intelligent_auth_and_spider(
                "https://protected.local/", "admin", "password", max_depth=1, max_routes=2
            )
            self.assertIsInstance(doms, list)
            self.assertIsInstance(manifest, list)
            self.assertFalse(is_auth)
            self.assertTrue(len(manifest) >= 1)
            self.assertEqual(manifest[0]["status"], "BLOCKED_BY_ANTI_BOT")
            self.assertEqual(engine.page_manifest, manifest)


if __name__ == "__main__":
    unittest.main()


''')

    create_file("tests/test_immutable_execution_history_and_retries.py", r'''
"""
tests/test_immutable_execution_history_and_retries.py
======================================================
Comprehensive verification test suite for REQ-HIST-041:
- Non-destructive Allure result deduplication and durable retry archiving
- Multi-attempt Robot Framework XML pre-merge preservation
- Immutable execution history audit logging (execution_history.jsonl)
- History and attempts query endpoints (/api/execution/history, /api/execution/attempts)
- Formal EARS traceability in requirements.md
"""

import os
import json
import time
import shutil
import pytest
from fastapi.testclient import TestClient
from aspice_qa_framework.main import app, deduplicate_allure_results


@pytest.fixture
def client():
    return TestClient(app)


def test_deduplicate_allure_results_archives_history_and_attachments(tmp_path):
    """
    REQ-HIST-041 (Ubiquitous 1, 2): Verifies that deduplicate_allure_results
    safely archives older test attempt files and attachments to history/allure_retries/
    and logs the event to execution_history.jsonl instead of deleting them.
    """
    allure_dir = tmp_path / "allure-results"
    allure_dir.mkdir(parents=True, exist_ok=True)

    # 1. Create older failed attempt result and attachment
    att_file = allure_dir / "trace-attachment-1.txt"
    att_file.write_text("Detailed failure trace for attempt 1", encoding="utf-8")

    res_1 = {
        "name": "Scenario: User Checkout Payment Validation",
        "fullName": "suite.payment.Scenario: User Checkout Payment Validation",
        "status": "failed",
        "statusDetails": {"message": "Payment gateway timeout 504"},
        "start": 1000,
        "stop": 2000,
        "attachments": [{"name": "trace", "source": "trace-attachment-1.txt", "type": "text/plain"}]
    }
    rf_1 = allure_dir / "uuid-attempt1-result.json"
    with open(rf_1, "w", encoding="utf-8") as f:
        json.dump(res_1, f)

    # 2. Create newer passing attempt result
    res_2 = {
        "name": "Scenario: User Checkout Payment Validation",
        "fullName": "suite.payment.Scenario: User Checkout Payment Validation",
        "status": "passed",
        "statusDetails": {},
        "start": 3000,
        "stop": 4000,
        "attachments": []
    }
    rf_2 = allure_dir / "uuid-attempt2-result.json"
    with open(rf_2, "w", encoding="utf-8") as f:
        json.dump(res_2, f)

    # 3. Execute deduplicate_allure_results
    archived_count = deduplicate_allure_results(str(allure_dir))
    assert archived_count == 1, f"Expected 1 archived duplicate, got {archived_count}"

    # 4. Verify newer result remains in active allure_dir
    assert os.path.exists(rf_2), "Newer passed result file must remain in active allure-results"
    assert not os.path.exists(rf_1), "Older failed result file must be removed from active allure-results"

    # 5. Verify older result and attachment are durably preserved in history/allure_retries/
    archive_dir = tmp_path / "history" / "allure_retries"
    archived_res = archive_dir / "uuid-attempt1-result.json"
    archived_att = archive_dir / "trace-attachment-1.txt"

    assert archived_res.exists(), "Older result must be preserved in history/allure_retries"
    assert archived_att.exists(), "Attachment must be preserved in history/allure_retries"
    with open(archived_res, "r", encoding="utf-8") as f:
        archived_data = json.load(f)
    assert archived_data["status"] == "failed"
    assert archived_data["statusDetails"]["message"] == "Payment gateway timeout 504"

    # 6. Verify append-only execution_history.jsonl
    history_log = tmp_path / "execution_history.jsonl"
    assert history_log.exists(), "execution_history.jsonl must be created"
    with open(history_log, "r", encoding="utf-8") as f:
        lines = [json.loads(l) for l in f if l.strip()]
    assert len(lines) >= 1
    event = lines[0]
    assert event["event"] == "ALLURE_ATTEMPT_ARCHIVED"
    assert event["status"] == "failed"
    assert "uuid-attempt1-result.json" in event["archived_result"]


def test_deduplicate_allure_results_handles_empty_and_no_duplicates(tmp_path):
    """Verifies deduplication gracefully handles empty directories or single runs."""
    empty_dir = tmp_path / "empty-results"
    empty_dir.mkdir()
    assert deduplicate_allure_results(str(empty_dir)) == 0

    # Single result
    single_dir = tmp_path / "single-results"
    single_dir.mkdir()
    rf = single_dir / "one-result.json"
    with open(rf, "w", encoding="utf-8") as f:
        json.dump({"name": "Solo Test", "status": "passed", "start": 100}, f)
    assert deduplicate_allure_results(str(single_dir)) == 0
    assert rf.exists()


def test_execution_history_and_attempts_api_endpoints(client):
    """
    REQ-HIST-041 (State-Driven 1): Verifies that GET /api/execution/history
    and GET /api/execution/attempts return structured, chronological execution records.
    """
    # 1. Test /api/execution/history
    resp_hist = client.get("/api/execution/history")
    assert resp_hist.status_code == 200
    data_hist = resp_hist.json()
    assert data_hist["status"] == "success"
    assert "total_events" in data_hist
    assert "events" in data_hist
    assert "archived_runs" in data_hist

    # 2. Test /api/execution/attempts
    resp_att = client.get("/api/execution/attempts")
    assert resp_att.status_code == 200
    data_att = resp_att.json()
    assert data_att["status"] == "success"
    assert "total_attempts" in data_att
    assert "attempts" in data_att


def test_robot_multi_attempt_xml_archival_directory_structure(tmp_path):
    """
    REQ-HIST-041 (Ubiquitous 3, Event-Driven 1): Verifies that multi-attempt
    XML outputs are isolated into dedicated history archives.
    """
    reports_dir = tmp_path / "reports"
    hist_xml_dir = reports_dir / "history" / "robot_attempts"
    hist_xml_dir.mkdir(parents=True, exist_ok=True)

    attempt_1_xml = hist_xml_dir / "pre_rerun_attempt_1_20260922_120000.xml"
    attempt_1_xml.write_text("<robot><test name='A'><status status='FAIL'/></test></robot>", encoding="utf-8")

    rerun_xml = hist_xml_dir / "rerun_attempt_2_20260922_120500.xml"
    rerun_xml.write_text("<robot><test name='A'><status status='PASS'/></test></robot>", encoding="utf-8")

    assert attempt_1_xml.exists()
    assert rerun_xml.exists()
    assert "FAIL" in attempt_1_xml.read_text(encoding="utf-8")
    assert "PASS" in rerun_xml.read_text(encoding="utf-8")


