class ModularTestFrameworkGenerator:
    """
    Modular SDET Test Framework Synthesizer & Generator.
    Produces clean, human-readable test suites, sensible step definitions,
    and modular libraries/utilities across Robot Framework, Python POM, API, and k6,
    fully grounded in crawled pages, forms, shadow elements, and discovered APIs.
    """

    def __init__(self, base_dir: str = "."):
        self.base_dir = os.path.abspath(base_dir)

    def load_crawl_context(self, target_url: str) -> Dict[str, Any]:
        """Loads crawled pages, component inventories, shadow elements, and APIs from artifacts."""
        page_manifest = []
        apis = []

        manifest_path = os.path.join(self.base_dir, "artifacts", "reports", "page_manifest.json")
        if os.path.exists(manifest_path):
            try:
                with open(manifest_path, "r", encoding="utf-8") as f:
                    page_manifest = json.load(f)
            except Exception:
                page_manifest = []

        api_cat_path = os.path.join(self.base_dir, "artifacts", "reports", "api_catalog.json")
        disc_api_path = os.path.join(self.base_dir, "artifacts", "reports", "discovered_apis.json")
        for p in [api_cat_path, disc_api_path]:
            if os.path.exists(p):
                try:
                    with open(p, "r", encoding="utf-8") as f:
                        data = json.load(f)
                        if isinstance(data, list):
                            apis.extend(data)
                        elif isinstance(data, dict):
                            apis.extend(data.get("endpoints", []))
                except Exception:
                    pass

        # Deduplicate APIs
        seen_apis = set()
        clean_apis = []
        for a in apis:
            u = a.get("url", "") if isinstance(a, dict) else str(a)
            if u and u not in seen_apis:
                seen_apis.add(u)
                clean_apis.append(a)

        # Fallback if page manifest is empty
        clean_url = str(target_url or "").rstrip("/")
        if not page_manifest and clean_url:
            page_manifest = [{
                "url": clean_url,
                "name": "LandingPage",
                "title": "Application Landing View",
                "component_inventory": {
                    "standalone_inputs": [{"id": "search_input", "name": "q", "type": "text"}],
                    "button_variants": [{"id": "btn_submit", "name": "submit", "text": "Submit"}]
                }
            }]

        return {
            "target_url": clean_url,
            "page_manifest": page_manifest,
            "apis": clean_apis
        }

    def generate_framework(
        self,
        target_url: str,
        language: str = "python",
        framework: str = "all",
        sdet_philosophy: str = "keyword_driven",
        output_dir: str = "artifacts/scripts"
    ) -> Dict[str, Any]:
        """
        Generates the complete multi-tier test framework grounded in the crawled context.
        """
        context = self.load_crawl_context(target_url)
        clean_url = context["target_url"]
        pages = context["page_manifest"]
        apis = context["apis"]

        target_root = os.path.join(self.base_dir, output_dir)
        os.makedirs(target_root, exist_ok=True)

        generated_files = []
        summary = {}

        do_all = framework.lower() in ["all", "full", "*"]
        do_robot = do_all or "robot" in framework.lower()
        do_pom = do_all or "pom" in framework.lower() or "pytest" in framework.lower()
        do_api = do_all or "api" in framework.lower()
        do_k6 = do_all or "k6" in framework.lower() or "perf" in framework.lower()

        # =====================================================================
        # 1. ROBOT FRAMEWORK: Low-Code Keyword Library + Master BDD Suite
        # =====================================================================
        if do_robot:
            robot_dir = os.path.join(target_root, "robot")
            os.makedirs(robot_dir, exist_ok=True)

            kw_code = generate_guaranteed_keywords_lib(clean_url, "admin@corp.internal", "Secure2026!", pages, apis)
            kw_path = os.path.join(robot_dir, "keywords_lib.py")
            with open(kw_path, "w", encoding="utf-8") as f:
                f.write(kw_code)
            generated_files.append(os.path.relpath(kw_path, self.base_dir))

            suite_code = generate_guaranteed_robot_suite(clean_url, "admin@corp.internal", "Secure2026!", pages, apis)
            suite_path = os.path.join(robot_dir, "test_orchestration_suite.robot")
            with open(suite_path, "w", encoding="utf-8") as f:
                f.write(suite_code)
            generated_files.append(os.path.relpath(suite_path, self.base_dir))

            # Synchronize into active framework paths for instant execution
            for sync_dest in [
                os.path.join(self.base_dir, "aspice_qa_framework", "keywords_lib.py"),
                os.path.join(self.base_dir, "keywords_lib.py")
            ]:
                try:
                    with open(sync_dest, "w", encoding="utf-8") as f:
                        f.write(kw_code)
                except Exception:
                    pass

            for sync_dest in [
                os.path.join(self.base_dir, "aspice_qa_framework", "execution_suite.robot"),
                os.path.join(self.base_dir, "execution_suite.robot")
            ]:
                try:
                    with open(sync_dest, "w", encoding="utf-8") as f:
                        f.write(suite_code)
                except Exception:
                    pass

            summary["robot_framework"] = {
                "keywords_library": os.path.relpath(kw_path, self.base_dir),
                "suite_path": os.path.relpath(suite_path, self.base_dir),
                "test_cases": len(re.findall(r'^(TC-[A-Z0-9_\-]+:[^\n]+)', suite_code, re.M))
            }

        # =====================================================================
        # 2. PYTHON PAGE OBJECT MODEL (POM) + PYTEST SUITE (DOM + Shadow DOM)
        # =====================================================================
        if do_pom:
            pom_dir = os.path.join(target_root, "python_pom")
            pages_dir = os.path.join(pom_dir, "pages")
            tests_dir = os.path.join(pom_dir, "tests")
