import os
import re
import json
import urllib.parse
from typing import Dict, Any, List, Optional


class APICoverageGenerator:
    """
    REQ-API-029: RAG-Driven Exhaustive API Test Suite Generator.
    Synthesizes deep, multi-discipline API test coverage covering:
    1. HTTP Contract & Schema Validation (JSON Schema, Headers, Status Codes) for all crawled routes
    2. Intercepted XHR Endpoints (POST, PUT, PATCH, DELETE) with payload handling
    3. GraphQL Introspection & Sample Query Probes
    4. Path-Parameterized Endpoints with Deep Boundary Value Analysis (BVA)
    5. Authentication Barrier Detection with @pytest.mark.skip
    6. Conftest Base URL Fixture Elimination of Hardcoded URLs
    """

    @staticmethod
    def _verify_api_response(res, method: str, url: str, sla_ms: float, dur_ms: float):
        """
        REQ-ASSERT-COOKIE-037, REQ-CF-CHALLENGE-042 & REQ-HTTP-400-RESILIENCE-048:
        Strict Status Code Enforcement, WAF/Anti-Bot Challenge Recognition,
        and Structured JSON Schema Validation Contract Acceptance.
        """
        import pytest
        headers_lower = {str(k).lower(): str(v).lower() for k, v in getattr(res, "headers", {}).items()}
        body_lower = getattr(res, "text", "").lower()

        waf_header_indicators = [
            "cf-mitigated", "cf-ray", "x-amzn-waf-action", "x-akamai-transformed",
            "x-datadome", "x-px-", "x-shield-", "x-firewall", "x-waf"
        ]
        has_waf_header = any(any(wh in k for wh in waf_header_indicators) for k in headers_lower.keys()) or any(
            srv in headers_lower.get("server", "") for srv in ["cloudflare", "akamai", "imperva", "awselb", "datadome"]
        )

        waf_signatures = [
            "<title>just a moment...",
            "just a moment",
            "cf-mitigated",
            "cloudflare turnstile",
            "challenges.cloudflare.com",
            "attention required! | cloudflare",
            "cf-browser-verification",
            "data-translate=\"challenge_headline\"",
            "why do i have to complete a captcha",
            "turnstile",
            "akamai", "perimeterx", "datadome", "access denied",
            "too big request header",
            "request header or cookie too large",
            "size of a request header field exceeds server limit",
            "431 request header fields too large",
            "request header fields too large",
            "400 bad request: request header or cookie too large",
            "bad request - header",
            "cookie too large",
            "header too large",
            "http error 431",
            "blocked by",
            "security verification",
            "verify you are human",
            "bot detection",
            "captcha",
            "distil",
            "incapsula"
        ]

        is_header_overflow = (
            res.status_code == 431
            or (res.status_code in [400, 431] and any(sig in body_lower for sig in [
                "too big request header",
                "request header or cookie too large",
                "size of a request header field exceeds server limit",
                "431 request header fields too large",
                "request header fields too large",
                "cookie too large",
                "header too large",
                "bad request - header too large",
                "bad request: header too large"
            ]))
        )
        if is_header_overflow:
            pytest.skip(f"[GATEWAY_HEADER_OVERFLOW_BLOCKED] Access to '{url}' was rejected due to reverse-proxy request header overflow (HTTP {res.status_code}).")

        is_anti_bot = (
            (res.status_code in [400, 403, 429] and any(sig in body_lower for sig in waf_signatures))
            or (res.status_code in [400, 403] and has_waf_header and any(
                sig in body_lower for sig in [
                    "challenge", "turnstile", "just a moment", "verify you are human",
                    "attention required", "security verification", "400 bad request",
                    "access denied", "blocked", "forbidden"
                ]
            ))
            or (res.status_code == 400 and ("400 bad request" in body_lower and ("nginx" in headers_lower.get("server", "") or has_waf_header)))
        )
        if is_anti_bot:
            pytest.skip(f"[BLOCKED_BY_ANTI_BOT] Access to '{url}' was challenged by anti-bot/WAF barrier (HTTP {res.status_code}).")

        # REQ-API-COOKIE-CHALLENGE-RESILIENCE-058: Clearance Cookie and Auth Barrier Diagnostics
        if res.status_code in [401, 403]:
            cookie_indicators = ["unauthorized", "forbidden", "token", "session", "cookie", "login", "authenticated", "credentials"]
            if any(ci in body_lower for ci in cookie_indicators) or "www-authenticate" in headers_lower:
                pytest.skip(f"[AUTH_OR_COOKIE_REQUIRED] Access to '{url}' requires valid authentication or clearance session (HTTP {res.status_code}). Provide AUTH_TOKEN or capture valid session in artifacts/cookies/cf_session.json.")

        # REQ-ASSERT-COOKIE-037 & REQ-HTTP-400-RESILIENCE-048:
        # Check if 400 Bad Request is a legitimate defensive schema rejection (valid structured JSON)
        is_structured_json_400 = False
        if res.status_code == 400:
            ct = headers_lower.get("content-type", "")
            if "application/json" in ct or ct.startswith("application/problem+json"):
                try:
                    import json
                    parsed_json = getattr(res, "json", lambda: None)()
                    if parsed_json is None and hasattr(res, "text"):
                        parsed_json = json.loads(res.text)
                    if isinstance(parsed_json, (dict, list)):
                        is_structured_json_400 = True
                except Exception:
                    is_structured_json_400 = False

        # REQ-ASSERT-COOKIE-037: Strict Status Code Enforcement (Zero False-Green Passes on 404/400)
        assert res.status_code != 404, (
            f"[UNEXPECTED_404_NOT_FOUND] {method} {url} does not exist on target host (HTTP 404 Not Found)."
        )
        if not is_structured_json_400:
            assert res.status_code != 400, (
                f"[UNEXPECTED_400_BAD_REQUEST] {method} {url} was rejected with HTTP 400 Bad Request. Body: {res.text[:200]}"
            )
        assert res.status_code != 500, (
            f"[SERVER_CRASH_500] {method} {url} returned unhandled HTTP 500 Internal Server Error. Body: {res.text[:200]}"
        )

        valid_statuses = [200, 201, 202, 204, 301, 302, 304, 401, 403, 405, 422]
        if is_structured_json_400:
            valid_statuses.append(400)
        assert res.status_code in valid_statuses, (
            f"[UNEXPECTED STATUS] {method} {url} returned {res.status_code}. Expected 2xx/3xx. Body: {res.text[:200]}"
        )

        if res.status_code != 429:
            assert dur_ms < sla_ms, (
                f"[SLA VIOLATION] {method} {url} took {dur_ms}ms (exceeded SLA limit of {sla_ms}ms)"
            )

    @classmethod
    def discover_api_routes(
        cls,
        target_url: str,
        discovered_apis: Optional[List[Any]] = None,
        artifacts_dir: str = "artifacts"
    ) -> List[Dict[str, Any]]:
        """
        Normalizes and enriches discovered API routes from:
        (a) artifacts/crawl/xhr_requests.json (CDP Network interception)
        (b) spider crawl crawled pages & manifest
        (c) caller-supplied discovered_apis
        (d) fallback standard contracts
        """
        base_u = str(target_url or "http://localhost:8000").rstrip("/")
        routes: List[Dict[str, Any]] = []
        seen_keys = set()

        def _add_route(u: str, p: str, m: str, cat: str, desc: str, headers=None, post_data=None, status=200, resp_ct="application/json"):
            key = (m.upper(), u.split("?")[0].rstrip("/"))
            if key in seen_keys or not u:
                return
            seen_keys.add(key)
            
            p_lower = p.lower()
            is_gql = cat == "GRAPHQL" or any(k in p_lower for k in ["/graphql", "/gql", "graphql"])
            if is_gql:
                cat = "GRAPHQL"
                m = "POST"

            is_path_param = bool(re.search(r'\{[a-zA-Z0-9_]+\}|/:[a-zA-Z0-9_]+|/\d+(?:/|$)', p))
            if is_path_param and cat not in ["GRAPHQL", "XHR_INTERCEPTED"]:
                cat = "PATH_PARAMETERIZED"

            headers = headers or {}
            has_auth_header = any(k.lower() in ["authorization", "cookie", "x-api-key"] for k in headers.keys())
            requires_auth = has_auth_header or status in [401, 403] or any(k in p_lower for k in ["/auth/", "/admin/", "/secure/", "/account/"])

            routes.append({
                "url": u,
                "path": p,
                "method": m.upper(),
                "category": cat,
                "description": desc,
                "headers": headers,
                "post_data": post_data,
                "response_status": status,
                "response_content_type": resp_ct,
                "is_graphql": is_gql,
                "is_path_parameterized": is_path_param,
                "requires_auth": requires_auth
            })

        # 1. Ingest artifacts/crawl/xhr_requests.json (REQ-API-029 Event-Driven)
        xhr_path = os.path.join(artifacts_dir, "crawl", "xhr_requests.json")
        if os.path.exists(xhr_path):
            try:
                with open(xhr_path, "r", encoding="utf-8") as f:
                    xhr_data = json.load(f)
                    if isinstance(xhr_data, list):
                        for item in xhr_data:
                            if isinstance(item, dict) and item.get("url"):
                                u = item["url"]
                                p = urllib.parse.urlparse(u).path or "/api"
                                m = item.get("method") or "GET"
                                _add_route(
                                    u=u,
                                    p=p,
                                    m=m,
                                    cat="XHR_INTERCEPTED",
                                    desc=f"Intercepted XHR {m.upper()} {p}",
                                    headers=item.get("headers"),
                                    post_data=item.get("post_data"),
                                    status=item.get("response_status", 200),
                                    resp_ct=item.get("response_content_type", "application/json")
                                )
            except Exception:
                pass

        # 2. Ingest caller-supplied discovered_apis
        if discovered_apis and isinstance(discovered_apis, list):
            for item in discovered_apis:
                if isinstance(item, dict) and item.get("url"):
                    u = item["url"]
                    p = item.get("path") or urllib.parse.urlparse(u).path or "/api"
                    m = item.get("method") or ("POST" if any(k in p.lower() for k in ["create", "submit", "login", "order", "update", "graphql"]) else "GET")
                    _add_route(
                        u=u,
                        p=p,
                        m=m,
                        cat=item.get("category", "DISCOVERED_ROUTE"),
                        desc=item.get("description", f"{m.upper()} {p}")
                    )
                elif isinstance(item, str) and item.strip():
                    u = item.strip()
                    p = urllib.parse.urlparse(u).path or "/api"
                    m = "POST" if any(k in p.lower() for k in ["create", "submit", "login", "order", "update", "graphql"]) else "GET"
                    _add_route(
                        u=u,
                        p=p,
                        m=m,
                        cat="DISCOVERED_ROUTE",
                        desc=f"{m} {p}"
                    )

        # 3. Ingest crawled pages manifest if available (GET for every crawled URL)
        for manifest_file in [
            os.path.join(artifacts_dir, "crawl", "crawl_manifest.json"),
            os.path.join(artifacts_dir, "crawl", "crawl_context.json")
        ]:
            if os.path.exists(manifest_file):
                try:
                    with open(manifest_file, "r", encoding="utf-8") as mf:
                        content = mf.read()
                        pages = []
                        if content.strip().startswith("["):
                            pages = json.loads(content)
                        else:
                            for line in content.splitlines():
                                if line.strip():
                                    try:
                                        pages.append(json.loads(line))
                                    except Exception:
                                        pass
                        for pg in pages:
                            if isinstance(pg, dict) and pg.get("url"):
                                pu = pg["url"]
                                pp = urllib.parse.urlparse(pu).path or "/"
                                _add_route(
                                    u=pu,
                                    p=pp,
                                    m="GET",
                                    cat="CRAWLED_PAGE",
                                    desc=f"Crawled Route HTTP Reachability: {pp}"
                                )
                except Exception:
                    pass

        # 4. Fallback baseline standard contracts
        if not routes:
            standard_paths = [
                ("/", "GET", "Root HTTP Landing Reachability", "BASELINE_CONTRACT"),
                ("/health", "GET", "Service Health Check & Vitality Contract", "BASELINE_CONTRACT"),
                ("/api/telemetry", "GET", "Telemetry Ingestion & System Metrics", "BASELINE_CONTRACT"),
                ("/api/discovery/report", "GET", "Automated Discovery Report Contract", "BASELINE_CONTRACT"),
                ("/api/cookies/status", "GET", "Cookie & Session Clearance Status", "BASELINE_CONTRACT"),
                ("/api/reports/history", "GET", "Test Execution History Contract", "BASELINE_CONTRACT"),
                ("/api/pipeline/config/cache", "GET", "Pipeline Config & Cache Parameters", "BASELINE_CONTRACT")
            ]
            for p, m, desc, cat in standard_paths:
                _add_route(f"{base_u}{p}", p, m, cat, desc)

        return routes

