    def wait_for_page_load(self, timeout=30, allow_quarantine=False):
        if not allow_quarantine:
            self._ensure_valid_session()
        if not self.driver: return
        try:
            WebDriverWait(self.driver, min(10, int(timeout))).until(
                lambda d: d.execute_script("return document.readyState") in ("interactive", "complete")
            )
        except Exception:
            pass

        start_t = time.time()
        challenge_indicators = [
            "just a moment", "checking your browser", "cloudflare", "turnstile",
            "cf-chl-widget", "cf-turnstile", "hcaptcha", "g-recaptcha",
            "verify you are human", "access denied", "security check", "ddos-guard",
            "bot verification", "ray id:"
        ]
        while (time.time() - start_t) < min(15, int(timeout)):
            try:
                page_title = (self.driver.title or "").lower()
                page_text = ""
                try:
                    body = self.driver.find_element(By.TAG_NAME, "body")
                    page_text = (body.text or "")[:3000].lower()
                except Exception:
                    pass
                
                has_challenge = any(ind in page_title or ind in page_text for ind in challenge_indicators)
                cf_frames = self.driver.find_elements(By.CSS_SELECTOR, "iframe[src*='challenges.cloudflare'], iframe[src*='turnstile'], iframe[title*='Cloudflare'], iframe[title*='challenge'], #turnstile-wrapper iframe, div[id*='cf-chl'] iframe")
                if cf_frames and any(f.is_displayed() for f in cf_frames):
                    has_challenge = True
                
                if not has_challenge:
                    break
                
                # REQ-BOT-CHALLENGE-RERUN-RESILIENCE-061: Unified multi-stage challenge bypass
                try:
                    from aspice_qa_framework.engines.ui_engine import ModernUIEngine
                    if ModernUIEngine and hasattr(ModernUIEngine, "handle_challenge_and_recover"):
                        if ModernUIEngine.handle_challenge_and_recover(self.driver, target_url=getattr(self.driver, "current_url", self.base_url), timeout=min(8.0, float(timeout))):
                            break
                except Exception:
                    pass

                # Active challenge fallback: dispatch native ActionChains events into Turnstile iframe
                for frame in cf_frames:
                    try:
                        self.driver.switch_to.frame(frame)
                        candidates = self.driver.find_elements(By.CSS_SELECTOR, "#challenge-stage, .ctp-checkbox-label, label, input[type='checkbox'], body")
                        for target in candidates:
                            try:
                                from selenium.webdriver.common.action_chains import ActionChains
                                ac = ActionChains(self.driver)
                                ac.move_to_element(target).pause(0.5).click().perform()
                                break
                            except Exception:
                                pass
                        self.driver.switch_to.default_content()
                    except Exception:
                        try: self.driver.switch_to.default_content()
                        except Exception: pass

                if cf_frames:
                    try:
                        from selenium.webdriver.common.action_chains import ActionChains
                        ac = ActionChains(self.driver)
                        ac.move_to_element_with_offset(cf_frames[0], 25, 25).pause(0.4).click().perform()
                    except Exception:
                        pass

                time.sleep(1.5)
            except Exception:
                break

        # Save clearance cookies upon successful verification
        try:
            if ModernUIEngine:
                ModernUIEngine.save_clearance_cookies(self.driver, self.base_url)
            else:
                curr_cookies = self.driver.get_cookies()
                if any("cf" in c.get("name", "").lower() for c in curr_cookies):
                    os.makedirs("artifacts/cookies", exist_ok=True)
                    with open("artifacts/cookies/cf_session.json", "w", encoding="utf-8") as f:
                        json.dump(curr_cookies, f)
        except Exception:
            pass

        # Anti-Bot Strict Truthful Guard: If challenge remains active, FAIL FAST instead of false-positive pass
        if self._is_antibot_challenge_present():
            if ModernUIEngine and hasattr(ModernUIEngine, "preload_clearance_cookies"):
                try:
                    ModernUIEngine.preload_clearance_cookies(self.driver, getattr(self.driver, "current_url", self.base_url), context="test_run_challenge")
                except Exception:
                    pass
            if ModernUIEngine and hasattr(ModernUIEngine, "handle_challenge_and_recover"):
                try:
                    ModernUIEngine.handle_challenge_and_recover(self.driver, target_url=self.base_url, timeout=5.0)
                except Exception:
                    pass
            if self._is_antibot_challenge_present():
                self.take_screenshot("antibot_challenge_blocked.png")
                target_url = getattr(self.driver, "current_url", self.base_url)
                cookie_info = self._check_clearance_cookies_availability()
                has_clearance = cookie_info["has_clearance_cookies"]

                if not has_clearance:
                    err_reason = "[COOKIE_CLEARANCE_UNAVAILABLE]"
                    err_msg = f"[COOKIE_CLEARANCE_UNAVAILABLE] Access to '{target_url}' is blocked by Cloudflare/Turnstile anti-bot barrier and no valid clearance cookies were found in artifacts/cookies or Cookie Manager. Please import or capture a valid cf_clearance session via Cookie Manager or headed browser rerun."
                else:
                    err_reason = "[BLOCKED_BY_ANTI_BOT]"
                    err_msg = f"[BLOCKED_BY_ANTI_BOT] Access to '{target_url}' is protected by an active Cloudflare/Turnstile challenge barrier that could not be bypassed. Test halted to prevent false-positive pass."

                if allow_quarantine:
                    self.antibot_quarantined = True
                    self.antibot_quarantined_url = target_url
                    self.antibot_quarantined_message = err_msg
                    q_payload = {{
                        "quarantined": True,
                        "url": self.antibot_quarantined_url,
                        "time": time.time(),
                        "reason": "COOKIE_CLEARANCE_UNAVAILABLE" if not has_clearance else "BLOCKED_BY_ANTI_BOT",
                        "cookie_clearance_available": has_clearance,
                        "message": err_msg
                    }}
                    for q_path in ["artifacts/diagnostics/antibot_quarantine.json", "artifacts/logs/antibot_quarantine.json", "artifacts/antibot_quarantine.json"]:
                        try:
                            os.makedirs(os.path.dirname(q_path), exist_ok=True)
                            with open(q_path, "w", encoding="utf-8") as f:
                                json.dump(q_payload, f, indent=2)
                        except Exception:
                            pass
                    print(f"[WARN] {{err_reason}} {{err_msg}}")
                    return
                raise AssertionError(err_msg)

        try:
            WebDriverWait(self.driver, 10).until(lambda d: d.execute_script("return document.readyState") == "complete")
        except Exception:
            pass

        try:
            ModernUIEngine.wait_for_framework_stabilization(self.driver, timeout=min(8, int(timeout)))
        except Exception:
            pass
        
        try:
            self.driver.execute_script("const loaders = document.querySelectorAll('.spinner, .loading, #loader, [aria-busy=true], .skeleton, .overlay, .modal-backdrop'); for (var i = 0; i < loaders.length; i++) if (loaders[i] && loaders[i].parentNode) loaders[i].parentNode.removeChild(loaders[i]); if (document.body) document.body.style.overflow = 'auto';")
        except Exception:
            pass
        time.sleep(0.5)

