def generate_guaranteed_playwright_suite(target_url, page_manifest):
    import re
    from urllib.parse import urlparse
    target_url = resolve_global_target_url(target_url)
    base_u = str(target_url).rstrip('/')
    domain = urlparse(base_u).netloc or "enterprise"
    clean_domain = re.sub(r'[^a-zA-Z0-9]', '', domain) or "Enterprise"

    pages = []
    seen = set()
    if page_manifest and isinstance(page_manifest, list):
        for p in page_manifest[:15]:
            u = p.get("url", "").strip()
            if u and u not in seen:
                seen.add(u)
                clean_name = re.sub(r'https?://[^/]+/?', '', u).strip('/')
                clean_name = re.sub(r'[^a-zA-Z0-9_]', '_', clean_name)
                name = f"Page_{clean_name[:20]}" if clean_name else "LandingPage"
                pages.append({"url": u, "name": name, "inputs": p.get("inputs", 0), "buttons": p.get("unique_buttons", 0)})
    if not pages:
        pages.append({"url": base_u, "name": "LandingPage", "inputs": 0, "buttons": 1})

    p0 = pages[0]
    p_url = p0["url"]
    p_name = p0["name"]

    ts_code = f"""import {{ test, expect, Page }} from '@playwright/test';

/**
 * Enterprise Production-Grade Playwright POM Suite
 * SUT: {base_u}
 * Architecture: Automated Page Object Model with Strict Functional Assertions
 */

export class {p_name}POM {{
    readonly page: Page;
    readonly url: string = '{p_url}';

    constructor(page: Page) {{
        this.page = page;
    }}

    async navigate() {{
        await this.page.goto(this.url, {{ waitUntil: 'domcontentloaded', timeout: 30000 }});
        await this.page.waitForLoadState('networkidle').catch(() => {{}});
    }}

    async getTitle(): Promise<string> {{
        return await this.page.title();
    }}

    async getHeadings(): Promise<string[]> {{
        return await this.page.locator('h1, h2, h3').allInnerTexts();
    }}

    async getVisibleButtons() {{
        return this.page.locator('button:visible, a.btn:visible, [role="button"]:visible');
    }}

    async getFormInputs() {{
        return this.page.locator('input[type="text"]:visible, input[type="email"]:visible, textarea:visible');
    }}
}}

test.describe('Production Playwright E2E Suite: {clean_domain}', () => {{
    let pom: {p_name}POM;

    test.beforeEach(async ({{ page }}) => {{
        pom = new {p_name}POM(page);
        await pom.navigate();
    }});

    test('PW-01: Verify URL Reachability and Legitimate Document Title', async ({{ page }}) => {{
        const title = await pom.getTitle();
        expect(title.trim().length).toBeGreaterThan(0);
        const antiBotMarkers = ['just a moment', 'security verification', 'attention required', 'verify you are human', 'cloudflare', 'turnstile'];
        for (const marker of antiBotMarkers) {{
            expect(title.toLowerCase()).not.toContain(marker);
        }}
    }});

    test('PW-02: Verify Layout Structure & Primary Section Containers', async ({{ page }}) => {{
        const sections = page.locator('header, nav, main, footer, section, article, div[class*="container"]');
        const count = await sections.count();
        expect(count).toBeGreaterThan(0);
        await expect(sections.first()).toBeVisible();
    }});

    test('PW-03: Verify Semantic Headings Copy and Content Presence', async ({{ page }}) => {{
        const headings = await pom.getHeadings();
        expect(headings.length).toBeGreaterThan(0);
        expect(headings[0].trim().length).toBeGreaterThan(0);
    }});

    test('PW-04: Verify Interactive Buttons & Action CTA Resilience', async ({{ page }}) => {{
        const buttons = await pom.getVisibleButtons();
        const count = await buttons.count();
        if (count > 0) {{
            const firstBtn = buttons.first();
            await expect(firstBtn).toBeEnabled();
            await firstBtn.hover();
        }} else {{
            const links = page.locator('a[href]:visible');
            expect(await links.count()).toBeGreaterThan(0);
        }}
    }});

    test('PW-05: Verify Data Input Handling & Nominal Persistence', async ({{ page }}) => {{
        const inputs = await pom.getFormInputs();
        if (await inputs.count() > 0) {{
            const inp = inputs.first();
            await inp.fill('SDET-Enterprise-Test');
            await expect(inp).toHaveValue('SDET-Enterprise-Test');
        }} else {{
            const body = page.locator('body');
            await expect(body).toBeVisible();
        }}
    }});

    test('PW-06: Verify Boundary Resilience against Whitespace Input', async ({{ page }}) => {{
        const inputs = await pom.getFormInputs();
        if (await inputs.count() > 0) {{
            const inp = inputs.first();
            await inp.fill('   ');
            const pageText = await page.innerText('body');
            expect(pageText.toLowerCase()).not.toContain('500 internal server error');
        }} else {{
            expect(await page.title()).not.toBe('');
        }}
    }});

    test('PW-07: Verify Defensive Injection Resistance (OWASP XSS & SQLi)', async ({{ page }}) => {{
        const inputs = await pom.getFormInputs();
        if (await inputs.count() > 0) {{
            const inp = inputs.first();
            await inp.fill("' OR '1'='1' -- <script>alert(1)</script>");
            const source = (await page.content()).toLowerCase();
            expect(source).not.toContain('sql syntax');
            expect(source).not.toContain('uncaught exception');
        }}
    }});

    test('PW-08: Verify Client-Side Render Performance SLA (< 5.0s)', async ({{ page }}) => {{
        const timing = await page.evaluate(() => {{
            const perf = window.performance.timing;
            return (perf.loadEventEnd - perf.navigationStart) / 1000;
        }});
        if (timing > 0) {{
            expect(timing).toBeLessThanOrEqual(5.0);
        }}
    }});

    test('PW-09: Verify Viewport Responsiveness across Mobile & Tablet', async ({{ page }}) => {{
        await page.setViewportSize({{ width: 375, height: 667 }});
        await page.waitForTimeout(300);
        await expect(page.locator('body')).toBeVisible();

        await page.setViewportSize({{ width: 768, height: 1024 }});
        await page.waitForTimeout(300);
        await expect(page.locator('body')).toBeVisible();

        await page.setViewportSize({{ width: 1920, height: 1080 }});
        await page.waitForTimeout(300);
        await expect(page.locator('body')).toBeVisible();
    }});

    test('PW-10: Verify Navigation & Absence of Unhandled Console Errors', async ({{ page }}) => {{
        const errors: string[] = [];
        page.on('pageerror', err => errors.push(err.message));
        await page.reload({{ waitUntil: 'domcontentloaded' }});
        expect(errors.filter(e => e.includes('Fatal') || e.includes('Crash'))).toHaveLength(0);
    }});
}});
"""
    return ts_code

def generate_guaranteed_java_suite(target_url, page_manifest):
    import re
    from urllib.parse import urlparse
    target_url = resolve_global_target_url(target_url)
    base_u = str(target_url).rstrip('/')

    java_code = f"""package com.enterprise.qa.automation;

import org.junit.jupiter.api.*;
import org.openqa.selenium.*;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;
import org.openqa.selenium.support.ui.WebDriverWait;
import org.openqa.selenium.support.ui.ExpectedConditions;

import java.time.Duration;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Enterprise Production-Grade Selenium + JUnit 5 Test Suite
 * Target SUT: {base_u}
 * Generated for full regression and ASPICE Level 3 compliance
 */
public class AutoUITest {{

    private static WebDriver driver;
    private static final String TARGET_URL = "{base_u}";
    private static WebDriverWait wait;

    @BeforeAll
    public static void setUpClass() {{
        ChromeOptions options = new ChromeOptions();
        options.addArguments("--headless=new");
        options.addArguments("--no-sandbox");
        options.addArguments("--disable-dev-shm-usage");
        options.addArguments("--disable-blink-features=AutomationControlled");
        options.addArguments("--window-size=1920,1080");
        options.addArguments("user-agent=Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36");

        driver = new ChromeDriver(options);
        driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(10));
        wait = new WebDriverWait(driver, Duration.ofSeconds(15));
    }}

    @AfterAll
    public static void tearDownClass() {{
        if (driver != null) {{
            driver.quit();
        }}
    }}

    @BeforeEach
    public void navigateToTarget() {{
        driver.get(TARGET_URL);
        wait.until(d -> ((JavascriptExecutor) d).executeScript("return document.readyState").equals("complete"));
    }}

    @Test
    @DisplayName("TC-JAVA-01: Verify Reachability, Valid HTTP URL and Legitimate Page Title")
    public void testReachabilityAndTitle() {{
        String currentUrl = driver.getCurrentUrl();
        assertNotNull(currentUrl, "Current URL must not be null");
        assertTrue(currentUrl.startsWith("http"), "URL must use valid HTTP/HTTPS protocol");

        String title = driver.getTitle();
        assertNotNull(title, "Title must not be null");
        assertFalse(title.trim().isEmpty(), "Page title must not be empty");

        String[] antiBotMarkers = {{"just a moment", "security verification", "attention required", "verify you are human", "cloudflare", "turnstile"}};
        for (String marker : antiBotMarkers) {{
            assertFalse(title.toLowerCase().contains(marker), 
                "Page title indicates an active anti-bot barrier: " + title);
        }}
    }}

    @Test
    @DisplayName("TC-JAVA-02: Verify Layout Architecture & Structural Section Containers")
    public void testStructuralSections() {{
        List<WebElement> sections = driver.findElements(By.cssSelector("header, nav, main, footer, section, article, div[class*='container']"));
        assertFalse(sections.isEmpty(), "Document must render at least one structural container");
        assertTrue(sections.get(0).isDisplayed(), "Primary layout container must be visible");
    }}

    @Test
    @DisplayName("TC-JAVA-03: Verify Semantic Headings Hierarchy Presence")
    public void testHeadingsHierarchy() {{
        List<WebElement> headings = driver.findElements(By.cssSelector("h1, h2, h3"));
        assertFalse(headings.isEmpty(), "Page must contain semantic headings");
        String topText = headings.get(0).getText().trim();
        assertFalse(topText.isEmpty(), "Primary heading text must not be empty");
    }}

    @Test
    @DisplayName("TC-JAVA-04: Verify Interactive Action Elements State")
    public void testInteractiveActions() {{
        List<WebElement> buttons = driver.findElements(By.cssSelector("button, a.btn, [role='button'], input[type='submit']"));
        if (!buttons.isEmpty()) {{
            WebElement first = buttons.get(0);
            assertNotNull(first, "Button element exists");
            assertTrue(first.isEnabled(), "Action button should be enabled for interaction");
        }} else {{
            List<WebElement> links = driver.findElements(By.tagName("a"));
            assertFalse(links.isEmpty(), "Page must render navigation links if no buttons present");
        }}
    }}

    @Test
    @DisplayName("TC-JAVA-05: Verify Client-Side Navigation Stability")
    public void testClientNavigationStability() {{
        String source = driver.getPageSource();
        assertNotNull(source, "DOM source must be non-null");
        assertTrue(source.length() > 200, "DOM source length must be substantial");
        assertFalse(source.toLowerCase().contains("500 internal server error"), "Page must not throw 500 error");
    }}
}}
"""
    return java_code

