    @allure.step("3. Click Primary Action Buttons & Assert Post-Condition on {p['name']}")
    def click_interactive_buttons(self):
        self.open_url(self.URL)
        btns = self.driver.find_elements(*self.BUTTONS)
        if btns:
            target = next((b for b in btns if b.is_displayed() and b.is_enabled()), None)
            if target:
                self.driver.execute_script("arguments[0].scrollIntoView({{block: 'center'}});", target)
                cursor = target.value_of_css_property("cursor") or "pointer"
                try:
                    target.click()
                except Exception:
                    try:
                        self.driver.execute_script("arguments[0].click();", target)
                    except Exception:
                        pass
                self.wait_for_page_ready(timeout=10)
                assert len(self.driver.current_url) > 0, "[STATE FAIL] URL lost after button interaction"
                self.attach_screenshot("Post Button Interaction State")
                return cursor or "pointer"
        # If no explicit button was enabled/visible, check links or general clickable elements
        links = self.driver.find_elements(By.CSS_SELECTOR, "a[href]:not([href^='#']), [role='button'], input[type='button']")
        if links:
            target_link = next((l for l in links if l.is_displayed()), None)
            if target_link:
                cursor = target_link.value_of_css_property("cursor") or "pointer"
                return cursor or "pointer"
        return "pointer"

