def generate_guaranteed_api_suite(target_url, apis):
    try:
        from .api_coverage_generator import APICoverageGenerator
        return APICoverageGenerator.generate_full_rag_api_suite(target_url, apis)
    except Exception:
        try:
            from aspice_qa_framework.engines.api_coverage_generator import APICoverageGenerator
            return APICoverageGenerator.generate_full_rag_api_suite(target_url, apis)
        except Exception:
            pass
    import urllib, urllib.parse, re, time
    target_url = resolve_global_target_url(target_url)
    base_u = str(target_url).rstrip('/')
    endpoints = []
    if apis and isinstance(apis, list):
        for item in apis:
            if isinstance(item, dict):
                # Classify GraphQL endpoints
                ep_copy = dict(item)
                raw_path_cl = ep_copy.get('path', ep_copy.get('url', ''))
                if any(k in str(raw_path_cl).lower() for k in ['/graphql', '/gql', 'graphql']):
                    ep_copy['category'] = 'GRAPHQL'
                    ep_copy['method'] = 'POST'
                elif any(k in str(raw_path_cl).lower() for k in ['xhr', '/api/', '/v1/', '/v2/', '/v3/', '/rest/']):
                    ep_copy.setdefault('category', 'XHR_REST')
                endpoints.append(ep_copy)
            elif isinstance(item, str) and item.strip():
                u = item.strip()
                p = urllib.parse.urlparse(u).path or '/api'
                is_graphql = any(k in p.lower() for k in ['graphql', '/gql'])
                m = 'POST' if (is_graphql or any(k in p.lower() for k in ['search', 'create', 'update', 'login', 'token', 'order', 'submit', 'mutation'])) else 'GET'
                cat = 'GRAPHQL' if is_graphql else ('XHR_REST' if '/api/' in p.lower() else 'REST_ENDPOINT')
                endpoints.append({'url': u, 'path': p, 'method': m, 'category': cat, 'description': f'Discovered API Route: {p}'})
    if not endpoints:
        endpoints = [
            {'url': f'{base_u}/', 'path': '/', 'method': 'GET', 'category': 'HTTP_CONTRACT', 'description': 'Root Application HTTP Reachability & Security Header Contract'},
            {'url': f'{base_u}/robots.txt', 'path': '/robots.txt', 'method': 'GET', 'category': 'POLICY', 'description': 'Standard Crawler Policy Document Check'},
            {'url': f'{base_u}/sitemap.xml', 'path': '/sitemap.xml', 'method': 'GET', 'category': 'SEO_CONTRACT', 'description': 'Application Sitemap XML Resource Contract'}
        ]

    def _semantic_param_probe(segment):
        """Return a meaningful probe value for a path parameter segment."""
        seg_l = segment.lower()
        if any(k in seg_l for k in ['uuid', 'guid']): return '00000000-0000-0000-0000-000000000001'
        if any(k in seg_l for k in ['id', 'pk', 'key']): return '1'
        if any(k in seg_l for k in ['slug', 'name']): return 'test-probe-slug'
        if any(k in seg_l for k in ['type', 'kind', 'mode']): return 'default'
        if any(k in seg_l for k in ['date', 'from', 'to']): return '2025-01-01'
        if any(k in seg_l for k in ['page', 'offset']): return '0'
        if any(k in seg_l for k in ['limit', 'size', 'count']): return '10'
        return 'test_probe'

    def _build_ep_url(raw_url, raw_path):
        """Replace path param placeholders with semantic probe values."""
        def _replacer(m):
            return _semantic_param_probe(m.group(1))
        url_out = re.sub(r'\{([a-zA-Z0-9_]+)\}', _replacer, raw_url)
        path_out = re.sub(r'\{([a-zA-Z0-9_]+)\}', _replacer, raw_path)
        # Also replace :param style
        url_out = re.sub(r'/:([a-zA-Z0-9_]+)', lambda m: '/' + _semantic_param_probe(m.group(1)), url_out)
        path_out = re.sub(r'/:([a-zA-Z0-9_]+)', lambda m: '/' + _semantic_param_probe(m.group(1)), path_out)
        return url_out, path_out

    test_methods = []
    for idx, ep in enumerate(endpoints[:15]):  # REQ-API-029: expanded from 8 to 15
        raw_url = ep.get('url', f'{base_u}/api')
        raw_path = ep.get('path', '/api')
        # Replace path variables with semantic probe values (REQ-API-029)
        ep_url, ep_path = _build_ep_url(raw_url, raw_path)
        method = ep.get('method', 'GET').upper()
        cat = ep.get('category', 'GENERAL')
        is_graphql = cat == 'GRAPHQL'
        desc = ep.get('description', f'{method} {ep_path}')
        slug = re.sub(r'[^a-zA-Z0-9_]', '_', ep_path.strip('/')).strip('_') or 'root'
        sla_limit = 8000 if any(k in ep_path.lower() for k in ['download', 'report', 'export', 'generate', 'chat', 'ask', 'nist']) else 4000

        test_methods.append(f"""
    @allure.epic("API Reliability & Performance")
    @allure.feature("Contract & SLA Compliance")
    @allure.story(f"Validate {method} {ep_path}")
    def test_{idx+1:02d}_contract_and_latency_{slug}(self):
        \"\"\"
        [ASPICE Trace: REQ-API-CONTRACT-{idx+1:03d} | Category: {cat}]
        Business Objective: Verify contract reachability, HTTP status code compliance,
        and latency SLA for {method} {ep_path}.
        Description: {desc}
        \"\"\"
        t0 = time.time()
        try:
            with allure.step(f"1. Dispatch {method} request to {ep_path}"):
                if "{method}" == "POST":
                    res = self.session.post("{ep_url}", json={{"test_probe": "sdet_validation"}}, timeout=10)
                else:
                    res = self.session.get("{ep_url}", timeout=10)
                elapsed_ms = round((time.time() - t0) * 1000, 2)

                # REQ-CF-CHALLENGE-042: 400 Bad Request Cookie Purge & Self-Healing Retry
                if res.status_code == 400 and len(self.session.cookies) > 0:
                    self.session.cookies.clear()
                    if "{method}" == "POST":
                        res_clean = self.session.post("{ep_url}", json={{"test_probe": "sdet_validation"}}, timeout=10)
                    else:
                        res_clean = self.session.get("{ep_url}", timeout=10)
                    if res_clean.status_code != 400:
                        res = res_clean
                        elapsed_ms = round((time.time() - t0) * 1000, 2)
            
            with allure.step(f"2. Validate HTTP status code compliance and SLA latency (<{sla_limit}ms)"):
                headers_l = {{str(k).lower(): str(v).lower() for k, v in getattr(res, "headers", {{}}).items()}}
                cf_barrier = any(k in headers_l for k in ["cf-mitigated", "cf-ray"]) or "cloudflare" in headers_l.get("server", "")
                b_lower = getattr(res, "text", "").lower()
                is_anti_bot = (
                    (res.status_code in [400, 403, 429] and any(
                        sig in b_lower for sig in [
                            "<title>just a moment...",
                            "just a moment",
                            "cf-mitigated",
                            "cloudflare turnstile",
                            "challenges.cloudflare.com",
                            "attention required! | cloudflare",
                            "cf-browser-verification",
                            "data-translate=\\"challenge_headline\\"",
                            "why do i have to complete a captcha",
                            "turnstile",
                            "akamai", "perimeterx", "datadome", "access denied"
                        ]
                    )) or (res.status_code in [400, 403] and cf_barrier and any(sig in b_lower for sig in ["challenge", "turnstile", "just a moment", "verify you are human", "attention required", "security verification", "400 bad request"]))
                )
                if is_anti_bot:
                    if not getattr(self, "clearance_cookies_available", False):
                        self.skipTest(
                            f"[COOKIE_CLEARANCE_UNAVAILABLE] Access to '{ep_url}' is blocked by Cloudflare/Turnstile anti-bot barrier "
                            f"(HTTP {res.status_code}) and no valid clearance cookies were found in storage. "
                            f"Please import or capture a valid cf_clearance session via Cookie Manager or headed rerun."
                        )
                    else:
                        self.skipTest(
                            f"[BLOCKED_BY_ANTI_BOT] Access to '{ep_url}' is blocked by Cloudflare/Turnstile anti-bot barrier "
                            f"(HTTP {res.status_code}) despite clearance cookies being attached."
                        )

                self.assertNotIn(
                    res.status_code,
                    [404, 500],
                    f"[API CONTRACT FAIL] Endpoint {ep_url} returned invalid status HTTP {res.status_code}. Body: {res.text[:200]}"
                )
                self.assertNotEqual(
                    res.status_code,
                    400,
                    f"[UNEXPECTED_400_BAD_REQUEST] Endpoint {ep_url} failed with 400 Bad Request. Possible malformed request or corrupted cookie. Body: {res.text[:200]}"
                )
                self.assertIn(
                    res.status_code, 
                    [200, 201, 202, 204, 301, 302, 304, 401, 403, 405, 422, 429], 
                    f"[API CONTRACT FAIL] Endpoint {ep_url} returned unexpected status HTTP {{res.status_code}}. Body: {{res.text[:200]}}"
                )
                if res.status_code != 429:
                    self.assertLess(
                        elapsed_ms, 
                        {sla_limit}, 
                        f"[SLA VIOLATION] Endpoint {ep_url} took {{elapsed_ms}}ms (exceeded {sla_limit}ms SLA threshold)"
                    )
            
            with allure.step("3. Validate response headers and non-empty content"):
                self.assertIsNotNone(res.headers.get("Content-Type"), "Response missing Content-Type header")
        except requests.exceptions.RequestException as e:
            self.skipTest(f"Endpoint {ep_url} not reachable: {{e}}")

    @allure.epic("API Boundary & Resilience")
    @allure.feature("Boundary Value Analysis (BVA)")
    @allure.story(f"BVA Edge Cases on {ep_path}")
    def test_{idx+1:02d}_bva_boundary_validation_{slug}(self):
        \"\"\"
        [ASPICE Trace: REQ-API-BVA-{idx+1:03d} | Boundary Value Analysis]
        Business Objective: Validate server resilience against edge-case inputs (empty body, whitespace).
        Asserts that the backend handles boundary inputs gracefully without throwing HTTP 500 crashes.
        \"\"\"
        try:
            with allure.step(f"1. Dispatch boundary whitespace and zero-limit payload to {ep_path}"):
                res = self.session.post("{ep_url}", json={{"query": "   ", "limit": 0}}, timeout=8)
            with allure.step("2. Assert server resilience: response status is not HTTP 500"):
                self.assertNotEqual(
                    res.status_code, 
                    500, 
                    f"[CRITICAL BVA FAILURE] Submitting boundary payload to {ep_url} caused an unhandled HTTP 500 error."
                )
        except requests.exceptions.RequestException:
            pass

    @allure.epic("Defensive Security")
    @allure.feature("OWASP API Security")
    @allure.story(f"SQLi and XSS Probes on {ep_path}")
    def test_{idx+1:02d}_security_injection_probe_{slug}(self):
        \"\"\"
        [ASPICE Trace: REQ-API-SEC-{idx+1:03d} | Compliance: OWASP API Security]
        Business Objective: Probe {ep_path} with SQL injection fragments and XSS payloads.
        Asserts that backend sanitizes inputs and does not leak raw database syntax errors or stack traces.
        \"\"\"
        probes = ["' OR '1'='1' --", "<script>alert(1)</script>"]
        for p in probes:
            try:
                with allure.step(f"1. Dispatch security probe vector: {{p[:15]}} to {ep_path}"):
                    res = self.session.get(f"{ep_url}?q={{urllib.parse.quote(p)}}", timeout=8)
                    body = res.text.lower()
                with allure.step("2. Verify zero SQL syntax error or unhandled stack trace leaks"):
                    self.assertNotIn("you have an error in your sql syntax", body, f"[SECURITY VULNERABILITY] SQL syntax error leaked by {ep_url}")
                    self.assertNotIn("fatal error: uncaught", body, f"[SECURITY VULNERABILITY] Uncaught runtime stack trace leaked by {ep_url}")
            except requests.exceptions.RequestException:
                pass
""")

    # REQ-API-029: GraphQL Introspection test — added when any GraphQL endpoint detected
    graphql_endpoints = [ep for ep in endpoints if ep.get('category') == 'GRAPHQL']
    if graphql_endpoints:
        gql_url = graphql_endpoints[0].get('url', f'{base_u}/graphql')
        test_methods.append(f"""
    @allure.epic("GraphQL Contract Verification")
    @allure.feature("Schema Introspection & Mutation BVA")
    @allure.story("GraphQL Introspection Query")
    def test_99_graphql_introspection(self):
        \"\"\"
        [ASPICE Trace: REQ-API-GRAPHQL-001 | Category: GRAPHQL]
        Verify GraphQL endpoint accepts introspection queries and returns a valid schema.
        Boundary: Empty operation dict should return 400, not 500.
        \"\"\"
        gql_ep = "{gql_url}"
        headers = {{**self.session.headers, "Content-Type": "application/json"}}
        # 1. Happy path: schema introspection
        try:
            with allure.step("1. Dispatch GraphQL introspection query"):
                res = self.session.post(
                    gql_ep,
                    json={{"query": "{{ __schema {{ queryType {{ name }} }} }}"}},
                    headers=headers, timeout=10
                )
            with allure.step("2. Validate introspection response is JSON with data key"):
                self.assertIn(res.status_code, [200, 400, 401, 403, 405],
                    f"[GRAPHQL_CONTRACT_FAIL] Unexpected status {res.status_code} on introspection")
                if res.status_code == 200:
                    try:
                        payload = res.json()
                        self.assertIn("data", payload,
                            "[GRAPHQL_SCHEMA_FAIL] Introspection response missing 'data' key")
                    except Exception:
                        pass
        except requests.exceptions.RequestException as e:
            self.skipTest(f"GraphQL endpoint not reachable: {{e}}")

        # 2. BVA: empty body should not cause 500
        try:
            with allure.step("3. BVA: empty GraphQL body — assert no HTTP 500"):
                r2 = self.session.post(gql_ep, json={{}}, headers=headers, timeout=8)
            with allure.step("4. Assert empty-body returns 400/422, not 500"):
                self.assertNotEqual(r2.status_code, 500,
                    f"[CRITICAL BVA FAILURE] Empty GraphQL body caused HTTP 500 at {gql_url}")
        except requests.exceptions.RequestException:
            pass
""")

    # REQ-POPUP-028 & REQ-POPUP-038: Overlay consent URL reachability tests — verify pages with overlays are still accessible
    try:
        combined_ov_entries = []
        for ctx_f in [
            os.path.join("artifacts", "crawl", "consent_manifest.json"),
            os.path.join("artifacts", "crawl", "overlay_context.json")
        ]:
            if os.path.exists(ctx_f):
                try:
                    with open(ctx_f, "r", encoding="utf-8") as _api_ov_f:
                        raw_data = json.load(_api_ov_f)
                        if isinstance(raw_data, list):
                            combined_ov_entries.extend(raw_data)
                except Exception:
                    pass

        if combined_ov_entries:
            seen_urls = set()
            for ov_idx, ov_entry in enumerate(combined_ov_entries[:5]):
                ov_url_str = str(ov_entry.get("url", base_u)).replace("'", "")
                if ov_url_str in seen_urls:
                    continue
                seen_urls.add(ov_url_str)
                ov_blocking = ov_entry.get("has_blocking_overlay") or ov_entry.get("has_blocking", False)
                ov_fw = ov_entry.get("framework_detected") or ov_entry.get("framework", "generic")
                test_methods.append(f"""
    @allure.epic("Consent & Overlay Compliance (REQ-POPUP-028)")
    @allure.feature("Overlay Page Reachability")
    @allure.story("Verify page with overlay returns HTTP 200")
    def test_popup_{ov_idx+1:02d}_overlay_page_reachability(self):
        \"\"\"
        [ASPICE Trace: REQ-POPUP-{ov_idx+1:03d} | Framework: {ov_fw}]
        Overlay detected on {ov_url_str} (blocking={ov_blocking}).
        Verify the page is HTTP-reachable despite the consent overlay.
        \"\"\"
        try:
            with allure.step("1. Dispatch GET request to overlay-flagged URL"):
                res = self.session.get("{ov_url_str}", timeout=12)
            with allure.step("2. Assert page returns valid HTTP status (2xx/3xx), not blocked"):
                is_bot_wall = (
                    res.status_code in [403, 429] and
                    any(sig in res.text.lower() for sig in [
                        "just a moment", "cf-mitigated", "cloudflare turnstile",
                        "challenge-platform", "please enable cookies"
                    ])
                )
                if is_bot_wall:
                    self.skipTest(
                        "[COOKIE_CLEARANCE_UNAVAILABLE] Overlay page {{res.status_code}} blocked by "
                        "anti-bot wall. Import cf_clearance cookies and rerun."
                    )
                self.assertIn(
                    res.status_code, [200, 201, 202, 301, 302, 304],
                    f"[OVERLAY_PAGE_UNREACHABLE] Expected 2xx/3xx, got HTTP {{res.status_code}} at {ov_url_str}"
                )
            with allure.step("3. Assert page body is non-empty (overlay did not swallow all content)"):
                self.assertGreater(
                    len(res.content), 100,
                    f"[OVERLAY_CONTENT_HIDDEN] Page body suspiciously short ({{len(res.content)}} bytes) — overlay may be blocking content"
                )
        except requests.exceptions.RequestException as e:
            self.skipTest(f"Overlay page {ov_url_str} not reachable: {{e}}")
""")
    except Exception:
        pass

    body = '\n'.join(test_methods)

    return f"""import os
import json
import unittest
import requests
import time
import urllib.parse

try:
    import allure
except ImportError:
    class _AllureFallback:
        @staticmethod
        def step(name):
            from contextlib import nullcontext
            return nullcontext()
        @staticmethod
        def epic(name): return lambda fn: fn
        @staticmethod
        def feature(name): return lambda fn: fn
        @staticmethod
        def story(name): return lambda fn: fn
    allure = _AllureFallback()

class TestEnterpriseAPISuite(unittest.TestCase):
    \"\"\"
    Enterprise REST API & Boundary Value Analysis (BVA) Test Suite.
    Exhaustively tests discovered exposed backend API routes.
    Includes Cloudflare / Turnstile anti-bot challenge diagnostics and HTTP 429 rate-limiting resilience.
    \"\"\"
    @classmethod
    def setUpClass(cls):
        cls.base_url = "{base_u}"
        cls.session = requests.Session()
        # REQ-CF-CHALLENGE-042: Strict User-Agent Synchronization from session_metadata.json
        saved_ua = None
        for meta_p in ["artifacts/cookies/session_metadata.json", "config/session_metadata.json"]:
            if os.path.exists(meta_p):
                try:
                    with open(meta_p, "r", encoding="utf-8") as mf:
                        saved_ua = json.load(mf).get("session_user_agent")
                        if saved_ua: break
                except Exception:
                    pass
        chosen_ua = saved_ua or "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/133.0.0.0 Safari/537.36"
        cls.session.headers.update({{
            "User-Agent": chosen_ua,
            "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,application/json,*/*;q=0.8",
            "Accept-Language": "en-US,en;q=0.9",
            "sec-ch-ua": '"Not(A:Brand";v="99", "Google Chrome";v="133", "Chromium";v="133"',
            "sec-ch-ua-mobile": "?0",
            "sec-ch-ua-platform": '"Windows"',
            "Sec-Fetch-Dest": "empty",
            "Sec-Fetch-Mode": "cors",
            "Sec-Fetch-Site": "same-origin"
        }})

        # Preload clearance cookies matching target domain
        cls.clearance_cookies_available = False
        cookies = []
        try:
            from aspice_qa_framework.engines.modern_ui_engine import ModernUIEngine
            cookies = ModernUIEngine.get_available_clearance_cookies()
        except Exception:
            pass
        if not cookies:
            for p in ["artifacts/cookies/cf_session.json", "config/cf_session.json", "storageState.json"]:
                if os.path.exists(p):
                    try:
                        with open(p, "r", encoding="utf-8") as f:
                            d = json.load(f)
                            if isinstance(d, list):
                                cookies.extend(d)
                            elif isinstance(d, dict) and "cookies" in d and isinstance(d["cookies"], list):
                                cookies.extend(d["cookies"])
                            elif isinstance(d, dict):
                                for k, v in d.items():
                                    cookies.append({{"name": k, "value": str(v)}})
                    except Exception:
                        pass
        parsed = urllib.parse.urlparse(cls.base_url)
        host = parsed.hostname or "localhost"
        parts = host.split(".")
        root_dom = ("." + ".".join(parts[-2:])) if len(parts) >= 2 else host
        for c in cookies:
            c_name = c.get("name") or c.get("key")
            c_val = c.get("value")
            if c_name and c_val:
                val_str = str(c_val).strip()
                # REQ-CF-CHALLENGE-042: Filter corrupt or mock tokens
                if val_str.lower().startswith("mock_") or len(val_str) < 20 or len(val_str) > 4096:
                    continue
                # Single-domain binding avoids duplicate Cookie header rejections on Cloudflare
                cls.session.cookies.set(c_name, val_str, domain=root_dom, path="/")
                cls.clearance_cookies_available = True
{body}

if __name__ == '__main__':
    unittest.main(verbosity=2)
"""

def generate_guaranteed_k6_script(target_url, apis, profile="load", pages=None, graphql_target=None, overlay_urls_k6=None):
    if profile not in ("load", None, "") or (pages and len(pages) > 1) or profile in ("full_coverage", "multi_level"):
        try:
            from .performance_engine import PerformanceEngine
            return PerformanceEngine.generate_k6_script_for_profile(target_url, profile=profile, apis=apis, pages=pages)
        except Exception:
            try:
                from aspice_qa_framework.engines.performance_engine import PerformanceEngine
                return PerformanceEngine.generate_k6_script_for_profile(target_url, profile=profile, apis=apis, pages=pages)
            except Exception:
                pass
    target_url = resolve_global_target_url(target_url)
    target = str(target_url or '').rstrip('/')
    api_target = ''
    if graphql_target is None:
        graphql_target = ''
    api_targets_list = []  # Up to 3 distinct API endpoints for multi-URL soak
    if apis and isinstance(apis, list) and len(apis) > 0:
        for ep_item in apis[:10]:
            raw_ep = ep_item.get('url', '') if isinstance(ep_item, dict) else str(ep_item)
            raw_path = ep_item.get('path', raw_ep) if isinstance(ep_item, dict) else raw_ep
            cat = ep_item.get('category', '') if isinstance(ep_item, dict) else ''
            if not raw_ep:
                continue
            # Classify and assign
            if not graphql_target and any(k in str(raw_path).lower() for k in ['graphql', '/gql']):
                graphql_target = raw_ep
                ep_item_method = 'POST'
            elif not api_target:
                api_target = raw_ep
            if len(api_targets_list) < 3 and raw_ep not in api_targets_list:
                api_targets_list.append(raw_ep)
        if not api_target and api_targets_list:
            api_target = api_targets_list[0]

    # Overlay-flagged URLs for consent page soak (REQ-POPUP-028)
    # Honour caller-supplied list; fall back to auto-loading from crawl artefact
    if not overlay_urls_k6:
        overlay_urls_k6 = []
        try:
            import os as _os, json as _json
            _overlay_ctx_path = _os.path.join("artifacts", "crawl", "overlay_context.json")
            if _os.path.exists(_overlay_ctx_path):
                with open(_overlay_ctx_path, "r", encoding="utf-8") as _k6_ov_f:
                    _k6_ov_entries = _json.load(_k6_ov_f)
                overlay_urls_k6 = [
                    str(e.get("url", target)).replace("'", "").replace('"', '')
                    for e in _k6_ov_entries if e.get("url")
                ][:3]
        except Exception:
            pass
    else:
        overlay_urls_k6 = [str(u) for u in overlay_urls_k6 if u][:3]

    api_scenario_def = ''
    api_exec_def = ''
    graphql_scenario_def = ''
    graphql_exec_def = ''
    overlay_scenario_def = ''
    overlay_exec_def = ''

    if api_target:

        api_scenario_def = (
            "    // 3. Underlying Discovered API Throughput & Latency Conformance\n"
            "    api_throughput_check: {\n"
            "      executor: 'constant-vus',\n"
            "      vus: 5,\n"
            "      duration: '10s',\n"
            "      exec: 'apiThroughputFlow',\n"
            "      startTime: '10s',\n"
            "    },"
        )
        api_exec_def = f"""
export function apiThroughputFlow() {{
  group('Underlying API Endpoint Conformance', function () {{
    const res = http.get('{api_target}', {{
      headers: {{
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
        'Accept': 'application/json, text/plain, */*',
      }},
    }});
    apiThroughputLatency.add(res.timings.duration);
    const passed = check(res, {{
      'api response is successful (2xx/3xx/401)': (r) => r.status >= 200 && r.status < 405,
      'api latency within SLA (<1500ms)': (r) => r.timings.duration < 1500,
      'api ttfb within SLA (<800ms)': (r) => r.timings.waiting < 800,
    }});
    httpFailureRate.add(!passed);
    sleep(0.5);
  }});
}}"""
    
    header_k6 = "\n".join([
        "import http from 'k6/http';",
        "import { check, group, sleep } from 'k6';",
        "import { Rate, Trend, Counter } from 'k6/metrics';",
        "",
        "// REQ-API-029: Dynamic BASE_URL fallback constant",
        f"const BASE_URL = __ENV.BASE_URL || '{target}' || 'http://localhost';",
        "",
        "// Telemetry & Multi-Discipline Performance SLA Metrics",
        "const thousandIterationLatency = new Trend('thousand_iteration_duration');",
        "const concurrentSpikeLatency = new Trend('concurrent_spike_duration');",
        "const stressRampLatency = new Trend('stress_ramp_duration');",
        "const repeatedLaunchLatency = new Trend('repeated_launch_duration');",
        "const apiThroughputLatency = new Trend('api_throughput_duration');",
        "const graphqlLatency = new Trend('graphql_throughput_duration');",
        "const overlayPageLatency = new Trend('overlay_page_duration');",
        "const httpFailureRate = new Rate('http_failure_rate');",
        "const successfulLaunches = new Counter('successful_page_launches');",
        "",
        "export const options = {",
        "  scenarios: {",
        "    // 1. High-Volume 1,000-Iteration Soak & Latency Drift Audit (10 VUs x 100 Iterations = 1,000 Launches)",
        "    thousand_iteration_soak: {",
        "      executor: 'per-vu-iterations',",
        "      vus: 10,",
        "      iterations: 100,",
        "      maxDuration: '60s',",
        "      exec: 'thousandIterationFlow',",
        "      startTime: '0s',",
        "    },",
        "    // 2. Simultaneous Peak Spike Burst (50 VUs hitting page at EXACT SAME sub-second instant)",
        "    concurrent_spike_burst: {",
        "      executor: 'constant-vus',",
        "      vus: 20,",
        "      duration: '10s',",
        "      exec: 'concurrentSpikeFlow',",
        "      startTime: '0s',",
        "    },",
        "    // 3. Multi-Stage Stress Test Ramp-Up (Ramping 0 -> 25 -> 50 -> 0 VUs)",
        "    stress_test_ramp: {",
        "      executor: 'ramping-vus',",
        "      startVUs: 0,",
        "      stages: [",
        "        { duration: '10s', target: 25 },",
        "        { duration: '15s', target: 50 },",
        "        { duration: '10s', target: 0 },",
        "      ],",
        "      exec: 'stressRampFlow',",
        "      startTime: '10s',",
        "    },",
        "    // 4. Repeated Sequential Launches (5 VUs x 10 cycles)",
        "    repeated_page_iterations: {",
        "      executor: 'per-vu-iterations',",
        "      vus: 5,",
        "      iterations: 10,",
        "      maxDuration: '30s',",
        "      exec: 'repeatedLaunchFlow',",
        "      startTime: '10s',",
        "    },",
    ])
    if api_scenario_def:
        header_k6 += "\n" + api_scenario_def
    # REQ-API-029: GraphQL throughput scenario
    if graphql_target:
        graphql_scenario_def = (
            "    // 5. GraphQL Endpoint Throughput & Contract (REQ-API-029)\n"
            "    graphql_throughput_check: {\n"
            "      executor: 'constant-vus',\n"
            "      vus: 3,\n"
            "      duration: '10s',\n"
            "      exec: 'graphqlThroughputFlow',\n"
            "      startTime: '5s',\n"
            "    },"
        )
        header_k6 += "\n" + graphql_scenario_def
    # REQ-POPUP-028: Consent page soak scenario
    if overlay_urls_k6:
        overlay_scenario_def = (
            "    // 6. Consent/Overlay Page Reachability Soak (REQ-POPUP-028)\n"
            "    consent_page_soak: {\n"
            "      executor: 'per-vu-iterations',\n"
            "      vus: 2,\n"
            "      iterations: 5,\n"
            "      maxDuration: '30s',\n"
            "      exec: 'overlayPageFlow',\n"
            "      startTime: '5s',\n"
            "    },"
        )
        header_k6 += "\n" + overlay_scenario_def
    header_k6 += "\n" + "\n".join([
        "  },",
        "  thresholds: {",
        "    'http_failure_rate': ['rate<0.05'],",
        "    'http_req_duration': ['p(95)<3000', 'p(99)<5000'],",
        "    'thousand_iteration_duration': ['p(95)<2500'],",
        "    'concurrent_spike_duration': ['p(95)<4000'],",
        "    'stress_ramp_duration': ['p(95)<3500'],",
        "    'repeated_launch_duration': ['p(95)<2000'],",
        "    'api_throughput_duration': ['p(95)<1500'],",
        "    'graphql_throughput_duration': ['p(95)<2000'],",
        "    'overlay_page_duration': ['p(95)<4000'],",
        "  },",
        "};",
        "",
        "export default function () {",
        "  thousandIterationFlow();",
        "}",
        "",
        "export function thousandIterationFlow() {",
        "  group('1,000-Iteration High-Volume Soak Flow', function () {",
        f"    const res = http.get('{target}', {{",
        "      headers: {",
        "        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',",
        "        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',",
        "        'Cache-Control': 'no-cache',",
        "      },",
        "    });",
        "    thousandIterationLatency.add(res.timings.duration);",
        "    const passed = check(res, {",
        "      'soak status is valid': (r) => r.status >= 200 && r.status < 500,",
        "      'soak latency within SLA (<2500ms)': (r) => r.timings.duration < 2500,",
        "      'soak ttfb consistent (<1200ms)': (r) => r.timings.waiting < 1200,",
        "      'soak body non-empty': (r) => r.body && r.body.length > 50,",
        "    });",
        "    httpFailureRate.add(!passed);",
        "    if (passed) successfulLaunches.add(1);",
        "    sleep(0.05);",
        "  });",
        "}",
        "",
        "export function concurrentSpikeFlow() {",
        "  group('Simultaneous Peak Spike Burst Flow (50 VUs Same Instant)', function () {",
        f"    const res = http.get('{target}', {{",
        "      headers: {",
        "        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',",
        "        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',",
        "      },",
        "    });",
        "    concurrentSpikeLatency.add(res.timings.duration);",
        "    const passed = check(res, {",
        "      'spike status is 2xx/3xx': (r) => r.status >= 200 && r.status < 400,",
        "      'spike duration within SLA (<4000ms)': (r) => r.timings.duration < 4000,",
        "      'spike ttfb within SLA (<1800ms)': (r) => r.timings.waiting < 1800,",
        "      'spike body non-empty': (r) => r.body && r.body.length > 50,",
        "    });",
        "    httpFailureRate.add(!passed);",
        "    if (passed) successfulLaunches.add(1);",
        "  });",
        "}",
        "",
        "export function stressRampFlow() {",
        "  group('Multi-Stage Stress Test Ramp Flow', function () {",
        f"    const res = http.get('{target}', {{",
        "      headers: {",
        "        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',",
        "        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',",
        "        'Accept-Language': 'en-US,en;q=0.9',",
        "      },",
        "    });",
        "    stressRampLatency.add(res.timings.duration);",
        "    const passed = check(res, {",
        "      'stress status valid': (r) => r.status >= 200 && r.status < 500,",
        "      'stress latency within SLA (<3500ms)': (r) => r.timings.duration < 3500,",
        "    });",
        "    httpFailureRate.add(!passed);",
        "    if (passed) successfulLaunches.add(1);",
        "    sleep(0.2);",
        "  });",
        "}",
        "",
        "export function repeatedLaunchFlow() {",
        "  group('Repeated Page Launch Flow (Multiple Times)', function () {",
        f"    const res = http.get('{target}', {{",
        "      headers: {",
        "        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',",
        "        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',",
        "        'Cache-Control': 'no-cache',",
        "      },",
        "    });",
        "    repeatedLaunchLatency.add(res.timings.duration);",
        "    const passed = check(res, {",
        "      'repeat status is 2xx/3xx': (r) => r.status >= 200 && r.status < 400,",
        "      'repeat duration within SLA (<2500ms)': (r) => r.timings.duration < 2500,",
        "      'repeat ttfb consistent (<1200ms)': (r) => r.timings.waiting < 1200,",
        "      'repeat body preserved': (r) => r.body && r.body.length > 50,",
        "      'repeat no bot challenge': (r) => !r.body || (!r.body.includes('Just a moment...') && !r.body.includes('Turnstile')),",
        "    });",
        "    httpFailureRate.add(!passed);",
        "    if (passed) successfulLaunches.add(1);",
        "    sleep(0.2);",
        "  });",
        "}",
    ])
    if api_exec_def:
        header_k6 += "\n" + api_exec_def
    # REQ-API-029: GraphQL throughput exec function
    if graphql_target:
        graphql_exec_def = f"""
export function graphqlThroughputFlow() {{
  group('GraphQL Throughput & Schema Contract', function () {{
    const payload = JSON.stringify({{ query: '{{ __schema {{ queryType {{ name }} }} }}' }});
    const res = http.post('{graphql_target}', payload, {{
      headers: {{
        'Content-Type': 'application/json',
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
        'Accept': 'application/json',
      }},
    }});
    graphqlLatency.add(res.timings.duration);
    const passed = check(res, {{
      'graphql status 2xx/4xx (not 5xx)': (r) => r.status >= 200 && r.status < 500,
      'graphql latency within SLA (<2000ms)': (r) => r.timings.duration < 2000,
      'graphql response has data or errors key': (r) => {{
        try {{ const b = JSON.parse(r.body); return 'data' in b || 'errors' in b; }} catch(e) {{ return true; }}
      }},
    }});
    httpFailureRate.add(!passed);
    sleep(0.5);
  }});
}}"""
        header_k6 += "\n" + graphql_exec_def
    # REQ-POPUP-028: Overlay page soak exec function
    if overlay_urls_k6:
        overlay_urls_js = '[\n' + ',\n'.join(f"  '{u}'" for u in overlay_urls_k6) + '\n]'
        overlay_exec_def = f"""
export function overlayPageFlow() {{
  // REQ-POPUP-028: Verify pages with detected consent/overlay banners remain HTTP-reachable
  const overlayUrls = {overlay_urls_js};
  group('Consent & Overlay Page Reachability Soak', function () {{
    const url = overlayUrls[__ITER % overlayUrls.length];
    const res = http.get(url, {{
      headers: {{
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
      }},
    }});
    overlayPageLatency.add(res.timings.duration);
    const passed = check(res, {{
      'overlay page status 2xx/3xx': (r) => r.status >= 200 && r.status < 400,
      'overlay page latency (<4000ms)': (r) => r.timings.duration < 4000,
      'overlay page body non-empty': (r) => r.body && r.body.length > 100,
      'overlay page not bot wall': (r) => !r.body || !r.body.includes('Just a moment...'),
    }});
    httpFailureRate.add(!passed);
    sleep(0.3);
  }});
}}"""
        header_k6 += "\n" + overlay_exec_def
    return header_k6 + "\n"

