                fw_mrd = ov_entry.get("framework_detected") or ov_entry.get("framework") or "generic"
                for ov in (ov_entry.get("overlays") or ov_entry.get("popups") or [])[:3]:
                    sel = ov.get("selector", "[role='dialog']")
                    key = f"{ov_url_mrd}:{sel}"
                    if key in seen_ov_keys:
                        continue
                    seen_ov_keys.add(key)
                    req_id = f"REQ-POPUP-{req_counter:03d}"
                    tc_id = f"TC-POPUP-{popup_req_counter:02d}"
                    ov_type = ov.get("category") or ov.get("type", "OVERLAY")
                    accept_btns = [b.get("text","") for b in ov.get("buttons",[]) if b.get("is_accept")]
                    btn_label = accept_btns[0] if accept_btns else "Close/Accept"
                    popup_matrix_rows.append(
                        f"| **{req_id}** | [EPIC-POPUP] {ov_type} ({fw_mrd}) | `{sel}` | Overlay/Banner | Route `{ov_url_mrd}` loaded | "
                        f"Assert overlay visible, click '{btn_label}', assert overlay hidden | "
                        f"Overlay dismissed, main content accessible without click interception | Non-dismissable screenshot captured | `{tc_id}` |"
                    )
                    trace_rows.append(f"- `{req_id}` -> `{tc_id}`, `TC-POPUP-00`")
                    req_counter += 1
