    feature_table = "\n".join(feature_matrix_rows) if feature_matrix_rows else "| **REQ-FEAT-001** | Core Offering Block | `.card, section` | Information Section | Route loaded | Page render | Feature headline and text visible | Structural section present | `TC-P01-02-FEAT` |"
    trace_list = "\n".join(trace_rows)
