    def robust_write_script(self, filepath, content, script_type=""):
        import os
        os.makedirs(os.path.dirname(filepath), exist_ok=True)
        
        target_url = self.resolve_target_url()
        username, password = "admin", "password123"
        page_manifest, apis = [], []
        try:
            if os.path.exists("artifacts/logs/pipeline_session.json"):
                with open("artifacts/logs/pipeline_session.json", "r", encoding="utf-8") as f:
                    sess = json.load(f)
                    u = sess.get("url")
                    if u and u not in ("https://example.com", "http://example.com"):
                        target_url = u
                    username = sess.get("user", username)
                    password = sess.get("password", password)
                    page_manifest = sess.get("page_manifest", [])
                    apis = sess.get("apis", [])
        except Exception:
            pass

        # Validate & repair before writing to disk
        validated_code = self.validate_and_repair_artifact(
            content=content,
            file_type=script_type,
            url=target_url,
            username=username,
            password=password,
            page_manifest=page_manifest,
            apis=apis
        )

        with open(filepath, "w", encoding="utf-8") as f:
            f.write(validated_code.strip() + "\n")
            f.flush()
            try:
                os.fsync(f.fileno())
            except OSError:
                pass

        if script_type == "ui":
            self.sanitize_ui_script(filepath)
        elif script_type == "robot":
            self.sanitize_robot_script(filepath)

        try:
            with open(filepath, "r", encoding="utf-8") as f:
                return f.read()
        except Exception:
            return validated_code

    def status(self, msg):
        with open("artifacts/logs/orchestrator.log", "a", encoding="utf-8") as f: 
            f.write(msg + "\n")
            f.flush()

    def log_selenium_action(self, action_type, details, cmd=""):
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f")[:-3]
        log_line = f"[{timestamp}] [{action_type.upper()}] {details}\n"
        os.makedirs("artifacts/logs", exist_ok=True)
        try:
            with open("artifacts/logs/selenium_journal.log", "a", encoding="utf-8") as f:
                f.write(log_line)
                f.flush()
                try: os.fsync(f.fileno())
                except: pass
        except: pass
        self.emit_trace("SELENIUM", f"{action_type.upper()}: {details}")

    def log_network_event(self, url, method="GET", status_code="CAPTURED"):
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f")[:-3]
        record = {"timestamp": timestamp, "method": method, "url": url, "status": status_code}
        os.makedirs("artifacts/logs", exist_ok=True)
        try:
            with open("artifacts/logs/network_traffic.jsonl", "a", encoding="utf-8") as f:
                f.write(json.dumps(record) + "\n")
                f.flush()
                try: os.fsync(f.fileno())
                except: pass
        except: pass

    def emit_trace(self, category, message, elapsed=0, inference=0, tokens=0, speed=0):
        timestamp = datetime.now().strftime("%H:%M:%S.%f")[:-3]
        trace_entry = {
            "time": timestamp,
            "cat": category,
            "msg": str(message),
            "elapsed": elapsed,
            "inference": round(inference, 2),
            "tokens": tokens,
            "speed": speed
        }
        os.makedirs("artifacts/logs", exist_ok=True)
        try:
            with open("artifacts/logs/engine_trace.jsonl", "a", encoding="utf-8") as f:
                f.write(json.dumps(trace_entry) + "\n")
                # [UNICODE:26A1] Removed f.flush() and os.fsync() to prevent WSL2 I/O freezing [UNICODE:26A1]
        except: pass

    def capture_frame(self, label=""):
        try:
            os.makedirs("artifacts/screencast", exist_ok=True)
            self.driver.save_screenshot("artifacts/screencast/live_frame.png")
            with open("artifacts/screencast/latest_frame.json", "w") as f:
                json.dump({"frame": f"data:image/png;base64,{base64.b64encode(open('artifacts/screencast/live_frame.png', 'rb').read()).decode('utf-8')}", "label": label, "time": datetime.now().strftime("%H:%M:%S")}, f)
        except Exception: pass

    def init_reattempt_gist(self, target_url: str = ""):
        """Initializes an empty Reattempt Injected Fixes Gist."""
        from datetime import datetime
        self.reattempt_fixes_gist = {
            "version": "1.0",
            "target_url": target_url or getattr(self, "target_url", "Active SUT"),
            "generated_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "total_attempts": 1,
            "total_fixes": 0,
            "attempts": [],
            "fixes": []
        }
        self._save_reattempt_gist()

    def record_reattempt_fix(self, attempt: int, category: str, title: str, details: str, metadata: dict = None):
        """Records an injected fix during a reattempt cycle and persists the gist to JSON and Markdown."""
        from datetime import datetime
        if not hasattr(self, "reattempt_fixes_gist") or not self.reattempt_fixes_gist:
            self.init_reattempt_gist()

        fix_entry = {
            "id": f"FIX-{attempt}-{len(self.reattempt_fixes_gist['fixes']) + 1:02d}",
            "attempt": attempt,
            "category": category,
            "title": title,
            "details": details,
            "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "metadata": metadata or {}
        }
        self.reattempt_fixes_gist["fixes"].append(fix_entry)
        self.reattempt_fixes_gist["total_fixes"] = len(self.reattempt_fixes_gist["fixes"])
        self.reattempt_fixes_gist["total_attempts"] = max(self.reattempt_fixes_gist.get("total_attempts", 1), attempt)
        self._save_reattempt_gist()

    def _save_reattempt_gist(self):
        """Persists the live gist to artifacts/reports/reattempt_fixes_gist.json and .md."""
        try:
            import json, os
            os.makedirs("artifacts/reports", exist_ok=True)
            json_path = "artifacts/reports/reattempt_fixes_gist.json"
            md_path = "artifacts/reports/reattempt_fixes_gist.md"

            with open(json_path, "w", encoding="utf-8") as jf:
                json.dump(self.reattempt_fixes_gist, jf, indent=2)

            md_lines = [
                "# ⚡ Reattempt Self-Healing Injected Fixes Gist",
                f"> **Target System:** `{self.reattempt_fixes_gist.get('target_url', 'Active SUT')}`  ",
                f"> **Generated At:** `{self.reattempt_fixes_gist.get('generated_at', '')}`  ",
                f"> **Total Attempts:** `{self.reattempt_fixes_gist.get('total_attempts', 1)}` | **Total Fixes Injected:** `{self.reattempt_fixes_gist.get('total_fixes', 0)}`\n",
                "## Injected Fixes Summary\n"
            ]
            if not self.reattempt_fixes_gist.get("fixes"):
                md_lines.append("*No self-healing fixes required during execution (clean first attempt).*")
            else:
                for fix in self.reattempt_fixes_gist["fixes"]:
                    badge = {
                        "DOM_VECTOR_HEAL": "🎯 `[DOM_VECTOR_HEAL]`",
                        "SUB_ARTIFACT_REPAIR": "🛠️ `[SUB_ARTIFACT_REPAIR]`",
                        "LLM_SELF_HEAL": "🧠 `[LLM_SELF_HEAL]`",
                        "SELECTIVE_RERUN_MERGE": "🔄 `[SELECTIVE_RERUN_MERGE]`"
                    }.get(fix.get("category"), f"🔧 `[{fix.get('category')}]`")

                    md_lines.append(f"### Attempt {fix['attempt']} — {fix['title']}")
                    md_lines.append(f"- **Category:** {badge}")
                    md_lines.append(f"- **Details:** {fix['details']}")
                    if fix.get("metadata"):
                        md_lines.append(f"- **Context:** `{json.dumps(fix['metadata'])}`")
                    md_lines.append("")

            with open(md_path, "w", encoding="utf-8") as mf:
                mf.write("\n".join(md_lines))
        except Exception:
            pass

    def update_pipeline_state(self, status="running", progress=0, steps=None, current_task="", current_command="", result=None, error=None, gate_data=None, chunking=False, warnings=None, attempt_info=None, current_prompt=None, llm_active=None, current_response=None, test_progress=None, reattempt_gist=None):
        curr_time = time.time()
        old_data = {}
        status_file = "artifacts/logs/task_status.json"
        
        # 1. [UNICODE:26A1] Read and merge existing state to prevent field dropping [UNICODE:26A1]
        if os.path.exists(status_file):
            try:
                with open(status_file, "r", encoding="utf-8") as f:
                    old_data = json.load(f)
            except Exception:
                old_data = {}

        # [UNICODE:26A1] Safe attribute lookup with fallback to disk and curr_time [UNICODE:26A1]
        start_ts = getattr(self, 'pipeline_start_time', None)
        if not start_ts:
            start_ts = old_data.get("start_time") or curr_time
            self.pipeline_start_time = start_ts

        # Preserve steps if not passed in current update
        merged_steps = steps if steps is not None else old_data.get("steps", {})
        
        # Preserve result data if not passed in current update
        merged_result = result if result is not None else old_data.get("result", None)
        
        # Preserve warnings and attempt info
        merged_warnings = warnings if warnings is not None else old_data.get("warnings", None)
        merged_attempt = attempt_info if attempt_info is not None else old_data.get("attempt_info", None)
        if status in ["completed", "failed", "error"] and isinstance(merged_attempt, dict):
            merged_attempt = dict(merged_attempt)
            merged_attempt["active"] = False
        merged_gate = gate_data if gate_data is not None else old_data.get("gate_data", None)

        payload = {
            "status": status,
            "progress": progress if progress > 0 else old_data.get("progress", 0),
            "current_task": current_task or old_data.get("current_task", "Ready"),
            "current_command": current_command or old_data.get("current_command", "Idle."),
            "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "start_time": start_ts,
            "chunking": chunking,
            "current_prompt": current_prompt if current_prompt is not None else old_data.get("current_prompt", ""),
            "current_response": current_response if current_response is not None else old_data.get("current_response", ""),
            "llm_active": llm_active if llm_active is not None else old_data.get("llm_active", False)
        }

        if merged_steps:
            payload["steps"] = merged_steps
        if merged_result:
            payload["result"] = merged_result
        if error:
            payload["error"] = error
        elif "error" in old_data and status in ["error", "failed"]:
            payload["error"] = old_data["error"]
        if merged_gate:
            payload["gate_data"] = merged_gate
        if merged_warnings:
            payload["warnings"] = merged_warnings
        if merged_attempt:
            payload["attempt_info"] = merged_attempt
        if test_progress is not None:
            payload["test_progress"] = test_progress
        elif "test_progress" in old_data and status == "running":
            # If step_6 is starting, reset test_progress rather than displaying stale counts from previous run
            if merged_steps.get("step_6", {}).get("status") == "RUNNING" and old_data.get("steps", {}).get("step_6", {}).get("status") != "RUNNING":
                payload["test_progress"] = {"total": 0, "completed": 0, "remaining": 0, "passed": 0, "failed": 0}
            else:
                payload["test_progress"] = old_data["test_progress"]
        elif status in ["completed", "failed", "error"] and "test_progress" in old_data:
            tp = dict(old_data["test_progress"])
            tp["remaining"] = 0
            payload["test_progress"] = tp

        # Preserve or attach Reattempt Injected Fixes Gist
        effective_gist = reattempt_gist if reattempt_gist is not None else getattr(self, "reattempt_fixes_gist", None)
        if effective_gist:
            payload["reattempt_gist"] = effective_gist
        elif "reattempt_gist" in old_data:
            payload["reattempt_gist"] = old_data["reattempt_gist"]

        # Preserve page_manifest and target_url to guarantee reload retention
        pm = getattr(self, "page_manifest", None)
        if not pm and result and isinstance(result, dict) and "page_manifest" in result:
            pm = result["page_manifest"]
        if not pm and "page_manifest" in old_data:
            pm = old_data["page_manifest"]
        if not pm and os.path.exists("artifacts/reports/page_manifest.json"):
            try:
                with open("artifacts/reports/page_manifest.json", "r", encoding="utf-8") as f:
                    pm = json.load(f)
            except Exception:
                pass
        if pm:
            payload["page_manifest"] = pm

        target_u = getattr(self, "target_url", None) or old_data.get("target_url")
        if target_u:
            payload["target_url"] = target_u


        # 2. [UNICODE:26A1] Precise Execution Duration Locking Logic [UNICODE:26A1]
        if status in ["completed", "failed", "error"]:
            # If already locked in old_data, preserve exact timestamp without drift
            if "total_elapsed_seconds" in old_data and old_data["total_elapsed_seconds"]:
                payload["total_elapsed_seconds"] = old_data["total_elapsed_seconds"]
                payload["end_time"] = old_data.get("end_time", curr_time)
            else:
                payload["total_elapsed_seconds"] = round(curr_time - start_ts, 1)
                payload["end_time"] = curr_time
        elif status == "paused_gate":
            # Record time elapsed up to gate pause
            payload["current_elapsed_seconds"] = round(curr_time - start_ts, 1)
            payload["gate_paused_at"] = curr_time
        else:
            # Active running state
            payload["current_elapsed_seconds"] = round(curr_time - start_ts, 1)

        # 3. [UNICODE:26A1] Atomic Write Routine to Prevent Polling Read Collisions [UNICODE:26A1]
        try:
            os.makedirs(os.path.dirname(status_file), exist_ok=True)
            temp_file = f"{status_file}.tmp"
            with open(temp_file, "w", encoding="utf-8") as f:
                json.dump(payload, f, indent=4)
                f.flush()
                os.fsync(f.fileno())
            os.replace(temp_file, status_file)
        except Exception:
            with open(status_file, "w", encoding="utf-8") as f:
                json.dump(payload, f, indent=4)

    def extract_apis(self, target_url=None, crawled_doms=None):
        """
        Industrial-grade active & passive API crawler.
        Probes OpenAPI/Swagger/GraphQL specs, scrapes JS bundles, intercepts network traffic, and parses HTML forms.
        """
        perf_logs = []
        if self.driver:
            try:
                perf_logs = self.driver.get_log("performance")
            except Exception:
                pass

        base_u = target_url or (self.driver.current_url if self.driver else "http://localhost:8000")
        try:
            try:
                from .api_crawler import EnterpriseAPICrawler
            except ImportError:
                from aspice_qa_framework.engines.api_crawler import EnterpriseAPICrawler

            crawler = EnterpriseAPICrawler(
                base_url=base_u,
                session=requests.Session(),
                trace_callback=self.emit_trace,
                timeout=5.0
            )
            catalog = crawler.crawl_and_analyze(crawled_doms=crawled_doms, performance_logs=perf_logs)
            self.api_catalog = catalog
            return [ep["url"] for ep in catalog]
        except Exception as e:
            self.emit_trace("WARNING", f"Advanced API crawler notice: {e}; falling back to passive network logs.")
            apis = []
            for entry in perf_logs:
                try:
                    msg = json.loads(entry['message'])['message']
                    if msg.get('method') == 'Network.requestWillBeSent':
                        req = msg.get('params', {}).get('request', {})
                        url = req.get('url', '')
                        method = req.get('method', 'GET')
                        if any(k in url.lower() for k in ["api", "graphql", "v1", "v2", "json", ".php", "endpoint"]):
                            apis.append(url)
                except Exception:
                    continue
            return list(set(apis)) if apis else [f"{base_u.rstrip('/')}/api/v1/health"]

    def wait_for_page_ready(self, timeout=25, poll_frequency=0.35):
        """
        Industrial-grade full page load and dynamic hydration waiting routine.
        Guarantees:
        1. document.readyState === 'complete'
        2. Anti-bot / Cloudflare Challenge clearance (if present)
        3. Network Idle: jQuery, Angular, Fetch & active XHR requests are zero
        4. DOM Mutation & Virtual DOM Hydration stabilization (React, Vue, Angular)
        5. Loader, spinner, and skeleton dismissal via bypass_loaders_and_scroll()
        """
        if not self.driver:
            return True
            
        start_t = time.time()
        self.log_selenium_action("WAIT_PAGE_READY", f"Waiting for full page load and hydration (timeout: {timeout}s)...")
        
        # 1. Wait for document.readyState == 'complete'
        try:
            WebDriverWait(self.driver, timeout, poll_frequency=poll_frequency).until(
                lambda d: d.execute_script("return document.readyState") == "complete"
            )
        except Exception:
            self.log_selenium_action("PAGE_LOAD_TIMEOUT", f"document.readyState did not reach 'complete' within {timeout}s; proceeding with best-effort stabilization.")

        # 2. Check and wait for Cloudflare / Anti-bot challenge clearance if detected
        try:
            challenge_start = time.time()
            while (time.time() - challenge_start) < min(timeout, 15):
                has_challenge = False
                try:
                    if ModernUIEngine:
                        has_challenge = ModernUIEngine.is_bot_challenge_active(self.driver)
                except Exception:
                    pass

                if not has_challenge:
                    break

                self.log_selenium_action("BOT_CHALLENGE", f"Anti-bot challenge detected. Waiting for clearance ({round(time.time() - challenge_start, 1)}s)...")
                try:
                    frames = self.driver.find_elements(By.CSS_SELECTOR, "iframe[src*='challenges.cloudflare'], iframe[src*='turnstile'], iframe[title*='Cloudflare']")
                    for frame in frames:
                        if frame.is_displayed():
                            self.driver.switch_to.frame(frame)
                            box = self.driver.find_elements(By.CSS_SELECTOR, "input[type='checkbox'], #challenge-stage, .ctp-checkbox-label")
                            for b in box:
                                if b.is_displayed():
                                    b.click()
                            self.driver.switch_to.default_content()
                except Exception:
                    try: self.driver.switch_to.default_content()
                    except Exception: pass

                time.sleep(1.0)
        except Exception:
            pass

        # 3. Modern UI Frameworks Stabilization (React Suspense, Angular Zone.js, Vue Reactivity, Web Animations)
        try:
            ModernUIEngine.wait_for_framework_stabilization(self.driver, timeout=min(timeout, 8), poll_frequency=poll_frequency)
        except Exception:
            pass

        # 4. DOM Mutation & Virtual DOM Hydration Stabilization Check (React/Vue/Angular)
        try:
            prev_len = self.driver.execute_script("return (document.body ? document.body.innerHTML.length : 0);")
            for _ in range(4):
                time.sleep(0.2)
                curr_len = self.driver.execute_script("return (document.body ? document.body.innerHTML.length : 0);")
                if abs(curr_len - prev_len) < 50:
                    break
                prev_len = curr_len
        except Exception:
            pass

        # 5. Loader, spinner, and skeleton dismissal + smart scroll
        try:
            self.bypass_loaders_and_scroll()
        except Exception:
            pass

        elapsed = round(time.time() - start_t, 2)
        self.log_selenium_action("PAGE_READY", f"Page fully loaded, hydrated, and stabilized in {elapsed}s.")
        return True

    def bypass_loaders_and_scroll(self):
        try:
            removed_count = self.driver.execute_script("""
                const loaders = document.querySelectorAll('.spinner, .loading, #loader, [aria-busy=true], .skeleton, .overlay, .modal-backdrop');
                let count = loaders.length;
                for (var i = 0; i < loaders.length; i++) if (loaders[i] && loaders[i].parentNode) loaders[i].parentNode.removeChild(loaders[i]);
                if (document.body) document.body.style.overflow = 'auto';
                return count;
            """)
            if removed_count and removed_count > 0:
                self.log_selenium_action("LOADER_BYPASS", f"Removed {removed_count} active overlay spinner(s) from DOM.")
            
            last_height = self.driver.execute_script("return document.body.scrollHeight")
            for i in range(3):
                self.driver.execute_script("window.scrollTo(0, document.body.scrollHeight);")
                time.sleep(0.8)
                new_height = self.driver.execute_script("return document.body.scrollHeight")
                self.log_selenium_action("SMART_SCROLL", f"Pass {i+1}/3 scrolled to {new_height}px (triggering lazy loaders).", f"driver.execute_script('window.scrollTo(0, {new_height})')")
                if new_height == last_height: break
                last_height = new_height
            self.driver.execute_script("window.scrollTo(0, 0);")
        except Exception as e:
            self.log_selenium_action("ERROR", f"Loader bypass / scroll warning: {str(e)}")

    def clean_page_text_for_extraction(self, html_source, max_chars=12000):
        """
        Aggressively strips noise and boilerplate (nav, footer, aside, form, header, cookie notices, scripts)
        to prevent boilerplate contamination ('Privacy Policy', 'Login', etc.) from polluting substantive content.
        """
        if not html_source:
            return ""
        try:
            clean_soup = BeautifulSoup(html_source, "html.parser")
            for tag in clean_soup(["script", "style", "nav", "footer", "aside", "form", "header", "noscript", "svg", "iframe"]):
                tag.decompose()
            for noise in clean_soup.find_all(attrs={"class": re.compile(r"cookie|banner|modal|popup|sidebar|footer|compliance|disclaimer|policy", re.I)}):
                noise.decompose()
            text = clean_soup.get_text(separator="\n", strip=True)
            lines = [line.strip() for line in text.splitlines() if len(line.strip()) > 3]
            cleaned = "\n".join(lines)
            return cleaned[:max_chars]
        except Exception:
            return ""

    def parse_llm_json_response(self, raw_text, default_factory=dict):
        """Resilient JSON extractor that parses markdown fences or raw JSON objects."""
        if not raw_text:
            return default_factory()
        clean_text = re.sub(r'<think>.*?</think>', '', str(raw_text), flags=re.DOTALL).strip()
        if "```" in clean_text:
            match = re.search(r'```(?:json)?\s*\n?(.*?)```', clean_text, re.DOTALL | re.IGNORECASE)
            if match:
                clean_text = match.group(1).strip()
        try:
            return json.loads(clean_text)
        except Exception:
            brace_match = re.search(r'\{.*\}', clean_text, re.DOTALL)
            if brace_match:
                try:
                    return json.loads(brace_match.group(0))
                except Exception:
                    pass
        return default_factory()

    def run_map_reduce_synthesis(self, crawl_records, base_domain, model_name=None):
        """
        Executes Phase 1 (Concurrent Map) and Phase 2 (Hierarchical Reduce)
        with strict JSON schemas, grounding rules, concurrency limits (max 10 workers),
        exponential backoff retry for 429 / socket errors, and fallback logic.
        """
        target_model = model_name or getattr(self, 'active_model', 'deepseek-coder:6.7b')
        map_results = []
        if not crawl_records:
            return map_results, {
                "domain_name": base_domain,
                "organization_name": base_domain,
                "primary_purpose": "Web Application",
                "target_audience": ["General Users"],
                "core_offerings": [],
                "domain_structure": "Standard web application structure"
            }

        # [UNICODE:26A1] Active VRAM Shredder & Auto-Scaling for Context Mapping [UNICODE:26A1]
        vram_res = probe_and_scale_vram_resources(target_model)
        map_ctx = vram_res.get("scaled_ctx", 8192)
        map_workers = min(vram_res.get("map_reduce_workers", 2), max(1, len(crawl_records)))
        text_chunk_limit = vram_res.get("text_chunk_len", 4500)
        gpu_base_options = {
            "num_gpu": -1,
            "num_ctx": map_ctx,
            "num_batch": vram_res.get("num_batch", 2048),
            "use_mmap": True,
            "f16_kv": True,
            "num_thread": vram_res.get("num_thread", 4)
        }
        if hasattr(self, 'emit_trace'):
            self.emit_trace(
                "DAEMON_STATUS",
                f"[BRAIN] [CONTEXT MAPPING SCALER] GPU: {vram_res.get('gpu_name')} | "
                f"Free VRAM: {vram_res.get('vram_free_mb')}MB | Context: {map_ctx} tokens | Workers: {map_workers} | Strategy: {vram_res.get('strategy_desc')}"
            )

        # --- Phase 1: The "Map" Prompt (Page-Level Extraction) ---
        map_system_prompt = (
            "You are an expert web data extractor. Your task is to analyze the cleaned text from a single web page and extract its core contextual value.\n\n"
            "RULES:\n"
            "1. Ignore generic UI boilerplate (e.g., 'Log In', 'Privacy Policy', 'Shopping Cart', 'All rights reserved').\n"
            "2. Focus only on substantive content that explains what this page is about.\n"
            "3. Do not hallucinate. If the page lacks substantive content (e.g., an empty login portal), output null values.\n"
            "4. You must only extract entities explicitly mentioned in the text. Cite the URL where the entity was found.\n"
            "5. Extract exactly to the provided JSON schema."
        )

        def extract_single_page_map(record):
            curr_url = record.get("url", "")
            page_title = record.get("title", "")
            page_text = record.get("text", "")
            if not page_text.strip():
                return {
                    "source_url": curr_url,
                    "page_intent": "Empty / No substantive content",
                    "core_entities": [],
                    "page_summary": "Page lacks substantive readable content.",
                    "is_high_value": False
                }

            user_prompt = (
                f"INPUT DATA:\n"
                f"URL: {curr_url}\n"
                f"Page Title: {page_title}\n"
                f"Cleaned Text:\n{page_text[:text_chunk_limit]}\n\n"
                f"JSON Output Schema:\n"
                f"{{\n"
                f'  "page_intent": "string (e.g., \'Product Listing\', \'About Us\', \'Documentation\')",\n'
                f'  "core_entities": ["list of specific products, services, or people mentioned"],\n'
                f'  "page_summary": "string (1-2 sentences summarizing the unique value of this page)",\n'
                f'  "is_high_value": true/false\n'
                f"}}"
            )

            for attempt in range(3):
                try:
                    map_opts = {"temperature": 0.1, "num_predict": 512, **gpu_base_options}
                    res = requests.post(
                        self.ollama_url,
                        json={
                            "model": target_model,
                            "system": map_system_prompt,
                            "prompt": user_prompt,
                            "format": "json",
                            "stream": False,
                            "keep_alive": "60m",
                            "options": map_opts
                        },
                        timeout=45
                    )
                    if res.status_code == 200:
                        raw_resp = res.json().get("response", "")
                        parsed = self.parse_llm_json_response(raw_resp)
                        if isinstance(parsed, dict) and "page_intent" in parsed:
                            parsed["source_url"] = curr_url
                            if "is_high_value" not in parsed:
                                parsed["is_high_value"] = True if len(parsed.get("core_entities", [])) > 0 else False
                            return parsed
                    elif res.status_code == 429:
                        time.sleep(2.0 * (2 ** attempt))
                except Exception:
                    time.sleep(1.0 * (attempt + 1))

            return {
                "source_url": curr_url,
                "page_intent": "General Content",
                "core_entities": record.get("headings", [])[:3],
                "page_summary": page_title,
                "is_high_value": len(page_text) > 300
            }

        max_workers = map_workers
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            future_to_rec = {executor.submit(extract_single_page_map, rec): rec for rec in crawl_records}
            for future in as_completed(future_to_rec):
                try:
                    res_map = future.result()
                    if res_map:
                        map_results.append(res_map)
                except Exception:
                    pass

        # --- Phase 2: The "Reduce" Prompt (Domain Synthesis) ---
        high_value_pages = [p for p in map_results if p.get("is_high_value")]
        if not high_value_pages:
            high_value_pages = map_results[:3]

        reduce_system_prompt = (
            f"You are a domain context synthesizer. You are provided with an array of JSON summaries representing the most valuable pages from the domain: {base_domain}.\n\n"
            "Your goal is to aggregate these fragmented page summaries into a single, comprehensive master profile of the entire website and its underlying business or purpose.\n\n"
            "RULES:\n"
            "1. Identify the overarching theme that connects these pages.\n"
            "2. Resolve conflicts. If page summaries contradict each other (e.g., outdated pricing vs. new pricing), note the discrepancy or choose the most frequently cited data.\n"
            "3. Abstract the target audience based on the tone and products offered.\n"
            "4. Output strictly according to the master JSON schema."
        )

        # Hierarchical Reduction Guardrail if page count exceeds single context window limit (> 15 pages)
        summaries_to_reduce = high_value_pages
        if len(high_value_pages) > 15:
            if hasattr(self, 'emit_trace'):
                self.emit_trace("SYSTEM", f"Hierarchical Reduction triggered for {len(high_value_pages)} high-value pages.")
            chunk_size = 8
            intermediate_summaries = []
            chunks = [high_value_pages[i:i + chunk_size] for i in range(0, len(high_value_pages), chunk_size)]
            for c_idx, chunk in enumerate(chunks):
                chunk_prompt = f"Summarize section {c_idx+1} of domain {base_domain}:\n" + json.dumps(chunk, indent=2)
                try:
                    reduce_inter_opts = {"temperature": 0.2, "num_predict": 768, **gpu_base_options}
                    res_c = requests.post(
                        self.ollama_url,
                        json={
                            "model": target_model,
                            "prompt": chunk_prompt,
                            "format": "json",
                            "stream": False,
                            "keep_alive": "60m",
                            "options": reduce_inter_opts
                        },
                        timeout=60
                    )
                    if res_c.status_code == 200:
                        p_chunk = self.parse_llm_json_response(res_c.json().get("response", ""))
                        intermediate_summaries.append(p_chunk)
                except Exception:
                    pass
            if intermediate_summaries:
                summaries_to_reduce = intermediate_summaries

        reduce_input_json = json.dumps(summaries_to_reduce, indent=2)
        reduce_user_prompt = (
            f"INPUT DATA:\n"
            f"{reduce_input_json}\n\n"
            f"JSON Output Schema:\n"
            f"{{\n"
            f'  "domain_name": "{base_domain}",\n'
            f'  "organization_name": "string",\n'
            f'  "primary_purpose": "string (What does this website actually do/sell/provide?)",\n'
            f'  "target_audience": ["list of inferred target demographics or industries"],\n'
            f'  "core_offerings": [\n'
            f'    {{\n'
            f'      "name": "string",\n'
            f'      "description": "string"\n'
            f'    }}\n'
            f'  ],\n'
            f'  "domain_structure": "string (Brief description of how the site is organized)"\n'
            f"}}"
        )

        domain_master_profile = {}
        for attempt in range(3):
            try:
                reduce_final_opts = {"temperature": 0.2, "num_predict": 1024, **gpu_base_options}
                res_red = requests.post(
                    self.ollama_url,
                    json={
                        "model": target_model,
                        "system": reduce_system_prompt,
                        "prompt": reduce_user_prompt,
                        "format": "json",
                        "stream": False,
                        "keep_alive": "60m",
                        "options": reduce_final_opts
                    },
                    timeout=90
                )
                if res_red.status_code == 200:
                    domain_master_profile = self.parse_llm_json_response(res_red.json().get("response", ""))
                    if isinstance(domain_master_profile, dict) and "primary_purpose" in domain_master_profile:
                        break
            except Exception:
                time.sleep(1.5 * (attempt + 1))

        if not domain_master_profile:
            domain_master_profile = {
                "domain_name": base_domain,
                "organization_name": base_domain,
                "primary_purpose": f"Application platform hosted at {base_domain}",
                "target_audience": ["General Users", "Platform Clients"],
                "core_offerings": [{"name": p.get("page_intent", "Service"), "description": p.get("page_summary", "")} for p in high_value_pages[:4]],
                "domain_structure": f"Web portal comprising {len(map_results)} discovered endpoints."
            }

        return map_results, domain_master_profile

    def intelligent_auth_and_spider(self, start_url, username, password, max_depth=2, max_routes=50, coverage_mode="targeted", use_crawl4ai=False, use_visual_scraping=False, use_pyppeteer=False, target_language="en-US", target_region="US", use_seleniumbase=False, **kwargs):
        start_t = time.time()
        crawl_limit = kwargs.get("crawl_limit")
        if crawl_limit is not None:
            if str(crawl_limit).strip().lower() in ("0", "unlimited", "none", "all"):
                max_routes = 999999
            else:
                try:
                    max_routes = max(1, int(crawl_limit))
                except Exception:
                    pass
        elif str(max_routes).strip().lower() in ("0", "unlimited", "none", "all"):
            max_routes = 999999

        crawl_depth_arg = kwargs.get("crawl_depth")
        if crawl_depth_arg is not None:
            try:
                max_depth = max(1, int(crawl_depth_arg))
            except Exception:
                pass

        self.log_selenium_action(
            "SESSION_START",
            f"Starting deep DOM spider on {start_url} (Max Depth: {max_depth}, Max Routes: {max_routes}, Locale: {target_language}/{target_region})"
        )

        use_sb = bool(use_seleniumbase) or (os.environ.get("ENABLE_SELENIUMBASE", "false").lower() in ("true", "1", "yes"))
        norm_start = start_url.rstrip('/') or start_url

        # REQ-CF-VERIFY-VECTOR-CLEANUP-044: Pre-run Vector DB storage cleanup for new project isolation
        try:
            try:
                from .vector_dom_engine import DOMVectorEngine
            except Exception:
                from aspice_qa_framework.engines.vector_dom_engine import DOMVectorEngine
            if DOMVectorEngine:
                DOMVectorEngine().cleanup_project_storage(preserve_backup=True)
                self.log_selenium_action("VECTOR_DB_CLEANUP", "Flushed Vector DB storage pre-crawl for clean project isolation.")
        except Exception:
            pass

        visited = set([start_url, norm_start])
        queue = []
        discovered_doms = []
        discovered_apis = []
        discovered_api_urls = set()
        page_manifest = []
        live_context_path = "artifacts/logs/crawl_context_live.jsonl"
        live_manifest_path = "artifacts/reports/page_manifest_live.json"
        try:
            os.makedirs("artifacts/logs", exist_ok=True)
            os.makedirs("artifacts/reports", exist_ok=True)
            with open(live_context_path, "w", encoding="utf-8") as context_file:
                context_file.write(json.dumps({
                    "event": "crawl_started",
                    "target_url": start_url.split("?", 1)[0],
                    "started_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                    "max_depth": max_depth,
                    "max_routes": max_routes,
                    "coverage_mode": coverage_mode
                }) + "\n")
        except Exception:
            pass

        def persist_live_page_context(page_record):
            """Makes each completed page collection reviewable before the crawl finishes."""
            try:
                review_record = {
                    "event": "page_collected",
                    "recorded_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                    "page_index": len(page_manifest),
                    "url": str(page_record.get("url", "")).split("?", 1)[0],
                    "status": page_record.get("status", "OK"),
                    "counts": {
                        "inputs": page_record.get("inputs", 0),
                        "buttons": page_record.get("unique_buttons", 0),
                        "links": page_record.get("total_links", 0),
                        "tables": page_record.get("tables", 0),
                        "api_resources": len(page_record.get("observed_api_resources", []))
                    },
                    "component_inventory": page_record.get("component_inventory", {}),
                    "runtime_interaction_evidence": page_record.get("runtime_interaction_evidence", {}),
                    "observed_api_resources": page_record.get("observed_api_resources", []),
                    "dom_context": page_record.get("dom_snippet", "")
                }
                with open(live_context_path, "a", encoding="utf-8") as context_file:
                    context_file.write(json.dumps(review_record, ensure_ascii=True) + "\n")
                snapshot_path = f"{live_manifest_path}.tmp"
                with open(snapshot_path, "w", encoding="utf-8") as snapshot_file:
                    json.dump(page_manifest, snapshot_file, indent=2, ensure_ascii=True)
                os.replace(snapshot_path, live_manifest_path)
            except Exception as persist_error:
                self.log_selenium_action("CRAWL_CONTEXT_LOG_WARN", f"Could not persist live crawl context: {persist_error}")

        def harvest_performance_apis(driver_inst, source_url):
            page_resources = []
            if not driver_inst: return page_resources
            try:
                js_fetch = (
                    "try { "
                    "return window.performance.getEntriesByType('resource')"
                    ".filter(function(r) { return r.initiatorType === 'xmlhttprequest' || r.initiatorType === 'fetch' || (r.name && (r.name.indexOf('/api/') !== -1 || r.name.indexOf('graphql') !== -1 || r.name.indexOf('.json') !== -1)); })"
                    ".map(function(r) { return { url: r.name, type: r.initiatorType, duration: Math.round(r.duration) }; }); "
                    "} catch(e) { return []; }"
                )
                perf_resources = driver_inst.execute_script(js_fetch)
                if perf_resources:
                    for pr in perf_resources:
                        u = pr.get("url", "")
                        if u and not any(ext in u.lower() for ext in [".png", ".jpg", ".svg", ".css", ".js", ".ico", ".woff", ".woff2"]):
                            resource = {
                                "url": u.split("?", 1)[0],
                                "type": pr.get("type", "xhr"),
                                "duration": pr.get("duration", 0),
                                "discovered_on": source_url
                            }
                            if len(page_resources) < 25 and not any(item["url"] == resource["url"] for item in page_resources):
                                page_resources.append(resource)
                            if u not in discovered_api_urls:
                                discovered_api_urls.add(u)
                                discovered_apis.append(resource)
            except Exception:
                pass
            if page_resources and ModernUIEngine:
                try:
                    ModernUIEngine.log_xhr_requests_to_file(driver_inst, source_url, page_resources)
                except Exception as xhr_err:
                    self.log_selenium_action("XHR_LOG_WARN", f"Could not log XHR requests: {xhr_err}")
            return page_resources

        def collect_rendered_links(driver_inst):
            """Reads links from the hydrated DOM after scrolling, including client-rendered navigation."""
            if not driver_inst:
                return []
            try:
                links = driver_inst.execute_script("return Array.from(document.querySelectorAll('a[href]')).map(a => a.href).filter(Boolean).slice(0, 500);") or []
                return [str(link) for link in links if isinstance(link, str)]
            except Exception as link_error:
                self.log_selenium_action("RENDERED_LINKS_WARN", f"Hydrated link collection unavailable: {link_error}")
                return []

        # REQ-POPUP-028: overlay_registry tracks detected overlays per URL for this crawl session
        overlay_registry: Dict[str, Any] = {}

        def detect_and_dismiss_page_overlays(driver_inst, current_url):
            """REQ-POPUP-028, REQ-DYNAMIC-OBSTRUCTIONS-039 & REQ-SPIDER-PERF-CHAT-040: Detect and auto-dismiss consent/popup overlays & dynamic obstructions."""
            if not driver_inst or not ModernUIEngine:
                return
            try:
                # REQ-SPIDER-PERF-CHAT-040: Proactively neutralize live-chat widgets before DOM extraction
                if hasattr(ModernUIEngine, "dismiss_chat_widgets"):
                    ModernUIEngine.dismiss_chat_widgets(driver_inst)

                # REQ-INTRUSIVE-POPUP-DOM-PURGE-046: Multi-selector collapse, universal cookie acceptance, page stabilization & interstitial suppression
                if hasattr(ModernUIEngine, "stabilize_and_hydrate_page"):
                    ModernUIEngine.stabilize_and_hydrate_page(driver_inst)

                if hasattr(ModernUIEngine, "ensure_cookies_accepted"):
                    c_res = ModernUIEngine.ensure_cookies_accepted(driver_inst, current_url)
                    if c_res and c_res.get("accepted"):
                        self.log_selenium_action("COOKIE_AUTO_ACCEPTED", f"URL: {current_url} | Selector: {c_res.get('selector')}")

                # REQ-SPIDER-SELECTOR-COLLAPSE-LOCALE-PICKER-064: Auto-resolve and close language/locale pickers & multi-selectors
                if hasattr(ModernUIEngine, "resolve_and_close_language_selectors"):
                    lang_res = ModernUIEngine.resolve_and_close_language_selectors(driver_inst, preferred_lang=target_language or "English")
                    if lang_res and (lang_res.get("resolved") or lang_res.get("collapsed")):
                        self.log_selenium_action("LANGUAGE_SELECTOR_RESOLVED", f"URL: {current_url} | Lang: {lang_res.get('selected_language')} | Collapsed: {lang_res.get('collapsed')}")

                if hasattr(ModernUIEngine, "collapse_open_selectors_and_menus"):
                    col_res = ModernUIEngine.collapse_open_selectors_and_menus(driver_inst)
                    if col_res and col_res.get("collapsed", 0) > 0:
                        self.log_selenium_action("SELECTORS_COLLAPSED", f"URL: {current_url} | Items: {col_res.get('items', [])}")

                if hasattr(ModernUIEngine, "dismiss_intrusive_interstitials"):
                    int_res = ModernUIEngine.dismiss_intrusive_interstitials(driver_inst, current_url)
                    if int_res and int_res.get("dismissed", 0) > 0:
                        self.log_selenium_action("INTERSTITIALS_DISMISSED", f"URL: {current_url} | Items: {int_res.get('items', [])}")

                detected = ModernUIEngine.detect_and_capture_page_overlays(driver_inst, current_url)
                if detected:
                    dismiss_result = ModernUIEngine.auto_dismiss_consent_overlays(driver_inst, current_url, detected)
                    overlay_registry[current_url] = {
                        "overlays": detected,
                        "dismissed": dismiss_result.get("dismissed", 0),
                        "failed": dismiss_result.get("failed", 0)
                    }
                    self.log_selenium_action(
                        "OVERLAY_HANDLED",
                        f"URL: {current_url} | Detected: {len(detected)} overlay(s) | "
                        f"Dismissed: {dismiss_result.get('dismissed', 0)} | Failed: {dismiss_result.get('failed', 0)}"
                    )
                if hasattr(ModernUIEngine, "handle_dynamic_obstructions"):
                    dyn_result = ModernUIEngine.handle_dynamic_obstructions(driver_inst, target_url=current_url, action="all")
                    if dyn_result and dyn_result.get("total_obstructions", 0) > 0:
                        self.log_selenium_action(
                            "DYNAMIC_OBSTRUCTIONS_HANDLED",
                            f"URL: {current_url} | Total: {dyn_result.get('total_obstructions')} | "
                            f"Actions: {len(dyn_result.get('actions_taken', []))}"
                        )
            except Exception as ov_err:
                self.log_selenium_action("OVERLAY_DETECT_FAILED", f"url='{current_url}' reason='{ov_err}'")


        crawl_records = []
        authenticated = False
        
        # Enforce domain boundaries so we don't crawl the whole internet
        base_domain = urlparse(start_url).netloc.replace("www.", "")
        url_signature_counts = {}
        baseline_nav_hashes = set()
        baseline_footer_hashes = set()
        baseline_action_hashes = set()

