COOKIE_CACHE_KEY = "atp:clearance_cookies:cache"
COOKIE_FILE_PATH = "artifacts/cookies/cf_session.json"
COOKIE_BACKUP_PATH = "config/cf_session.json"

def get_cached_clearance_cookies() -> List[Dict[str, Any]]:
    """Retrieves clearance cookies from disk or Redis cache with automatic bidirectional sync."""
    if os.path.exists(COOKIE_FILE_PATH):
        try:
            with open(COOKIE_FILE_PATH, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, list) and data:
                return data
        except Exception:
            pass

    if os.path.exists(COOKIE_BACKUP_PATH):
        try:
            with open(COOKIE_BACKUP_PATH, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, list) and data:
                os.makedirs("artifacts/cookies", exist_ok=True)
                with open(COOKIE_FILE_PATH, "w", encoding="utf-8") as f:
                    json.dump(data, f, indent=2)
                return data
        except Exception:
            pass

    try:
        r = get_redis()
        if r:
            cached = r.get(COOKIE_CACHE_KEY)
            if cached:
                data = json.loads(cached)
                if isinstance(data, list) and data:
                    os.makedirs("artifacts/cookies", exist_ok=True)
                    os.makedirs("config", exist_ok=True)
                    with open(COOKIE_FILE_PATH, "w", encoding="utf-8") as f:
                        json.dump(data, f, indent=2)
                    with open(COOKIE_BACKUP_PATH, "w", encoding="utf-8") as f:
                        json.dump(data, f, indent=2)
                    return data
    except Exception:
        pass

    return []

def save_clearance_cookies_to_cache(cookies: List[Dict[str, Any]], target_url: Optional[str] = None, user_agent: Optional[str] = None):
    """Persists clearance cookies across JSON, Playwright storageState, Netscape cookies.txt, and Redis cache without expiry."""
    os.makedirs("artifacts/cookies", exist_ok=True)
    os.makedirs("config", exist_ok=True)

    # 1. Standard cf_session.json
    with open(COOKIE_FILE_PATH, "w", encoding="utf-8") as f:
        json.dump(cookies, f, indent=2)
    with open(COOKIE_BACKUP_PATH, "w", encoding="utf-8") as f:
        json.dump(cookies, f, indent=2)

    # REQ-CF-VERIFY-VECTOR-CLEANUP-044: Capture and persist session User-Agent
    session_ua = str(user_agent).strip() if user_agent else None
    if not session_ua and ModernUIEngine and hasattr(ModernUIEngine, "_load_session_user_agent"):
        session_ua = ModernUIEngine._load_session_user_agent()
    if session_ua:
        try:
            meta = {
                "session_user_agent": session_ua,
                "saved_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                "target_url": target_url or ""
            }
            with open("artifacts/cookies/session_metadata.json", "w", encoding="utf-8") as f:
                json.dump(meta, f, indent=2)
            with open("config/session_metadata.json", "w", encoding="utf-8") as cf:
                json.dump(meta, cf, indent=2)
        except Exception:
            pass

    # 2. Playwright storageState.json
    try:
        pw_state = ModernUIEngine.format_as_playwright(cookies, target_url)
        with open("artifacts/cookies/storageState.json", "w", encoding="utf-8") as f:
            json.dump(pw_state, f, indent=2)
        with open("config/storageState.json", "w", encoding="utf-8") as f:
            json.dump(pw_state, f, indent=2)
    except Exception:
        pass

    # 3. Netscape cookies.txt
    try:
        ns_text = ModernUIEngine.format_as_netscape(cookies)
        with open("artifacts/cookies/cookies.txt", "w", encoding="utf-8") as f:
            f.write(ns_text)
        with open("config/cookies.txt", "w", encoding="utf-8") as f:
            f.write(ns_text)
    except Exception:
        pass

    # 4. Redis cache
    try:
        r = get_redis()
        if r:
            r.set(COOKIE_CACHE_KEY, json.dumps(cookies))
    except Exception:
        pass

def clear_clearance_cookies_cache():
    """Removes clearance cookies from disk across all formats and Redis."""
    paths_to_clean = [
        COOKIE_FILE_PATH, COOKIE_BACKUP_PATH,
        "artifacts/cookies/storageState.json", "config/storageState.json",
        "artifacts/cookies/cookies.txt", "config/cookies.txt"
    ]
    for p in paths_to_clean:
        if os.path.exists(p):
            try: os.remove(p)
            except Exception: pass
    try:
        r = get_redis()
        if r:
            r.delete(COOKIE_CACHE_KEY)
    except Exception:
        pass

class CookieInjectPayload(BaseModel):
    cookie_type: Optional[str] = None       # e.g. "cf_clearance", "__cf_bm", "datadome", "AWSALB"
    cookie_value: Optional[str] = None      # direct token value e.g. "0.Vw42vN_71xyz.987..."
    cookie_string: Optional[str] = None     # raw Cookie header or paste
    cookies_json: Optional[Any] = None      # JSON list or dict (Cookie-Editor format)
    curl_command: Optional[str] = None      # Full cURL command string (e.g. curl 'https://...' -H 'Cookie: ...')
    netscape_text: Optional[str] = None     # Netscape cookies.txt specification format
    playwright_json: Optional[Any] = None   # Playwright storageState.json ({ "cookies": [...] })
    target_url: Optional[str] = None
    domain: Optional[str] = None
    user_agent: Optional[str] = None        # Solving browser User-Agent for Cloudflare HMAC binding
    merge: bool = True                      # Preserve and merge with previously injected cookies

@app.post("/api/cookies/inject")
async def inject_clearance_cookies(payload: CookieInjectPayload):
    """
    Parses, normalizes, and saves Cloudflare/WAF clearance and session cookies to persistent cache and disk.
    Supports:
    1. Direct Cookie Type Selector (cf_clearance, __cf_bm, custom) with raw token value.
    2. Raw Cookie header string (cf_clearance=...; __cf_bm=...).
    3. Full cURL command line (curl 'url' -H 'Cookie: ...' or --cookie "...").
    4. Playwright storageState.json format ({ "cookies": [...], "origins": [...] }).
    5. Netscape cookies.txt specification (tab-delimited, #HttpOnly_ support).
    6. Exported JSON array from Cookie-Editor / EditThisCookie extension.
    Cookies remain permanently cached across runs and restarts until explicitly cleared by user.
    """
    target = payload.target_url

    # Check if target_url can be auto-extracted from curl_command if not explicitly supplied
    if payload.curl_command:
        _, extracted_target = ModernUIEngine.parse_curl_command(payload.curl_command)
        if not target and extracted_target:
            target = extracted_target

    if not target:
        try:
            cfg = get_cached_pipeline_config() or {}
            target = cfg.get("url")
        except Exception:
            pass

    domain = payload.domain
    if not domain and target:
        base_domain = target.split("//")[-1].split("/")[0].split(":")[0]
        root_domain = "." + ".".join(base_domain.split(".")[-2:]) if len(base_domain.split(".")) >= 2 else base_domain
        domain = root_domain
    elif not domain:
        domain = ".localhost"

    if domain and not domain.startswith(".") and not domain.startswith("localhost"):
        domain = "." + domain

    if not target:
        target = f"https://{domain.lstrip('.')}" if domain and domain != ".localhost" else "https://zerodha.com"

    cookie_map = {}
    if payload.merge:
        existing = get_cached_clearance_cookies()
        for c in existing:
            if isinstance(c, dict) and c.get("name"):
                cookie_map[c["name"]] = c

    format_detected = "custom"

    # 1. cURL Command
    if payload.curl_command:
        curl_cookies, _ = ModernUIEngine.parse_curl_command(payload.curl_command, domain)
        if curl_cookies:
            format_detected = "curl"
            for c in curl_cookies:
                cookie_map[c["name"]] = c

    # 2. Netscape cookies.txt format
    if payload.netscape_text:
        ns_cookies = ModernUIEngine.parse_netscape_cookies(payload.netscape_text, domain)
        if ns_cookies:
            format_detected = "netscape"
            for c in ns_cookies:
                cookie_map[c["name"]] = c

    # 3. Playwright storageState JSON
    if payload.playwright_json:
        pw_cookies = ModernUIEngine.parse_playwright_storage_state(payload.playwright_json, domain)
        if pw_cookies:
            format_detected = "playwright"
            for c in pw_cookies:
                cookie_map[c["name"]] = c

    # 4. Direct Cookie Type Selector & Value
    if payload.cookie_type and payload.cookie_value:
        name = str(payload.cookie_type).strip()
        val = str(payload.cookie_value).strip()
        if "=" in val and val.split("=", 1)[0].strip() == name:
            val = val.split("=", 1)[1].strip()
        if name and val:
            format_detected = "direct"
            cookie_map[name] = {
                "name": name,
                "value": val,
                "domain": domain,
                "path": "/",
                "secure": True,
                "httpOnly": True if any(k in name.lower() for k in ["clearance", "token", "session"]) else False
            }

    # 5. Raw Cookie string (with smart fallback if cURL or Netscape was pasted here)
    if payload.cookie_string and isinstance(payload.cookie_string, str):
        c_str = payload.cookie_string.strip()
        if c_str.startswith("curl ") or " -H " in c_str or " --cookie " in c_str:
            parsed_c, _ = ModernUIEngine.parse_curl_command(c_str, domain)
            for c in parsed_c:
                cookie_map[c["name"]] = c
            format_detected = "curl"
        elif "# Netscape" in c_str or "\t" in c_str:
            parsed_ns = ModernUIEngine.parse_netscape_cookies(c_str, domain)
            for c in parsed_ns:
                cookie_map[c["name"]] = c
            format_detected = "netscape"
        else:
            clean = re.sub(r'^cookie:\s*', '', c_str, flags=re.I)
            pairs = [p.strip() for p in clean.split(";") if p.strip()]
            for p in pairs:
                if "=" in p:
                    k, v = p.split("=", 1)
                    k = k.strip()
                    v = v.strip().strip("'\"")
                    if k:
                        format_detected = "raw_header"
                        cookie_map[k] = {
                            "name": k,
                            "value": v,
                            "domain": domain,
                            "path": "/",
                            "secure": True,
                            "httpOnly": True if "clearance" in k.lower() else False
                        }

    # 6. JSON list or Playwright dict
    if payload.cookies_json:
        raw_json = payload.cookies_json
        if isinstance(raw_json, str):
            try:
                raw_json = json.loads(raw_json)
            except Exception:
                raw_json = []
        if isinstance(raw_json, dict):
            parsed_dict = ModernUIEngine.parse_playwright_storage_state(raw_json, domain)
            if parsed_dict:
                format_detected = "playwright"
                for c in parsed_dict:
                    cookie_map[c["name"]] = c
        elif isinstance(raw_json, list):
            format_detected = "json_list"
            for c in raw_json:
                if isinstance(c, dict) and c.get("name"):
                    k = str(c["name"]).strip()
                    cookie_map[k] = {
                        "name": k,
                        "value": str(c.get("value") or ""),
                        "domain": c.get("domain") or domain,
                        "path": c.get("path") or "/",
                        "secure": bool(c.get("secure", True)),
                        "httpOnly": bool(c.get("httpOnly", False))
                    }

    cookies_list = list(cookie_map.values())
    if not cookies_list:
        return JSONResponse(status_code=400, content={"status": "error", "message": "No valid cookie token could be extracted from payload."})

    save_clearance_cookies_to_cache(cookies_list, target, user_agent=payload.user_agent)

    return {
        "status": "success",
        "message": f"Successfully cached {len(cookies_list)} clearance cookie(s) for {domain} (Format: {format_detected})",
        "count": len(cookies_list),
        "injected_count": len(cookies_list),
        "cookies": [c["name"] for c in cookies_list],
        "domain": domain,
        "format": format_detected,
        "target_url": target,
        "detected_target_url": target
    }

@app.get("/api/cookies/status")
async def get_cookie_status():
    """Returns status of stored anti-bot clearance cookies and recently used cookies log."""
    cookies = get_cached_clearance_cookies()
    used_log = ModernUIEngine.get_used_cookies_log(limit=50) if ModernUIEngine else []

    if not cookies:
        return {
            "injected": False,
            "count": 0,
            "cookies": [],
            "domain": None,
            "details": [],
            "saved_cookies": [],
            "used_cookies": used_log,
            "used_count": len(used_log),
            "auto_preload_active": True
        }

    details = []
    for c in cookies:
        val = str(c.get("value") or "")
        preview = (val[:10] + "..." + val[-6:]) if len(val) > 20 else val
        details.append({
            "name": c.get("name"),
            "domain": c.get("domain"),
            "preview": preview,
            "secure": c.get("secure", True),
            "httpOnly": c.get("httpOnly", False),
            "sameSite": c.get("sameSite", "Lax")
        })

    return {
        "injected": True,
        "count": len(cookies),
        "cookies": [c.get("name") for c in cookies if c.get("name")],
        "domain": cookies[0].get("domain") if cookies else None,
        "details": details,
        "saved_cookies": details,
        "used_cookies": used_log,
        "used_count": len(used_log),
        "auto_preload_active": True
    }

@app.get("/api/cookies/list")
async def list_cookies_library():
    """Returns comprehensive saved cookie library and used cookies tracking log."""
    return await get_cookie_status()

@app.delete("/api/cookies/item")
async def delete_cookie_item(name: str = Query(...), domain: Optional[str] = Query(None)):
    """Deletes a specific cookie by name and optional domain from persistent storage and cache."""
    deleted = ModernUIEngine.delete_saved_cookie(name, domain) if ModernUIEngine else False
    if deleted:
        return {"status": "success", "message": f"Deleted cookie '{name}'", "deleted": True}
    return JSONResponse(status_code=404, content={"status": "not_found", "message": f"Cookie '{name}' not found in library", "deleted": False})

@app.get("/api/cookies/export")
def export_clearance_cookies(format: str = "json", target_url: Optional[str] = None):
    """
    Exports stored clearance cookies in requested format:
    - 'json': JSON array format (Cookie-Editor compatible)
    - 'playwright': Playwright storageState.json object ({ "cookies": [...], "origins": [...] })
    - 'netscape': Netscape cookies.txt specification format
    - 'curl': cURL command flag and Cookie header strings
    """
    cookies = get_cached_clearance_cookies()
    if format == "playwright":
        pw_state = ModernUIEngine.format_as_playwright(cookies, target_url)
        return JSONResponse(status_code=200, content={
            "status": "success",
            "format": "playwright",
            "cookies": pw_state.get("cookies", []),
            "origins": pw_state.get("origins", []),
            "data": pw_state
        })
    elif format == "netscape":
        ns_text = ModernUIEngine.format_as_netscape(cookies)
        return JSONResponse(status_code=200, content={
            "status": "success",
            "format": "netscape",
            "data": ns_text,
            "raw_text": ns_text
        })
    elif format == "curl":
        c_header = ModernUIEngine.format_as_curl_header(cookies, include_flag=False)
        curl_flag = ModernUIEngine.format_as_curl_header(cookies, include_flag=True)
        return JSONResponse(status_code=200, content={
            "status": "success",
            "format": "curl",
            "data": curl_flag,
            "cookie_header": f"Cookie: {c_header}",
            "curl_header_flag": curl_flag,
            "curl_cookie_flag": f'--cookie "{c_header}"',
            "cookies_count": len(cookies)
        })
    else:
        return JSONResponse(status_code=200, content={
            "status": "success",
            "format": "json",
            "data": cookies,
            "cookies": cookies
        })

@app.delete("/api/cookies/clear")
async def clear_stored_cookies():
    """Explicitly deletes stored clearance cookies from disk (all formats) and Redis persistent cache."""
    clear_clearance_cookies_cache()
    return {"status": "success", "message": "Clearance cookies permanently cleared from cache and disk across all formats."}

