@app.post("/api/scripts/wdio/suggest-locators")
def suggest_wdio_locators(req: WDIOLocatorFixRequest):
    """Diagnoses a failed WebdriverIO locator and returns resilient semantic alternatives."""
    suggestor = WDIOLocatorAutoFixSuggestor(
        ollama_url=os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate"),
        model_name=req.model_name
    )
    suggestions = suggestor.suggest_healed_locators(
        failed_locator=req.failed_locator,
        error_trace=req.error_trace,
        dom_snippet=req.dom_snippet
    )
    return {"status": "success", "suggestions": suggestions}

@app.post("/api/scripts/wdio/patch-locator")
def patch_wdio_locator(req: WDIOPatchRequest):
    """Applies a healed locator patch directly to the WebdriverIO script on disk."""
    if not os.path.exists(req.script_path):
        return JSONResponse(status_code=404, content={"error": f"Script not found at {req.script_path}"})
        
    try:
        with open(req.script_path, "r", encoding="utf-8") as f:
            code = f.read()
            
        if req.old_locator not in code:
            return JSONResponse(status_code=400, content={"error": f"Target locator '{req.old_locator}' not found in script."})
            
        patched_code = code.replace(req.old_locator, req.new_locator)
        with open(req.script_path, "w", encoding="utf-8") as f:
            f.write(patched_code)
            
        return {"status": "success", "message": f"Successfully patched locator to '{req.new_locator}'"}
    except Exception as e:
        return JSONResponse(status_code=500, content={"error": str(e)})

# [UNICODE:26A1] Dedicated Endpoint to Re-Execute Isolated Steps [UNICODE:26A1]
@app.post("/api/pipeline/retrigger-step")
def retrigger_pipeline_step(payload: RetriggerStepPayload):
    """Allows isolated re-execution of individual pipeline steps with live prompt inspection."""
    session_file = "artifacts/logs/pipeline_session.json"
    if not os.path.exists(session_file):
        return JSONResponse(status_code=400, content={"error": "No previous pipeline session found to retrigger."})

    def retrigger_worker():
        try:
            with open(session_file, "r", encoding="utf-8") as f:
                sess = json.load(f)
            with open("artifacts/logs/task_status.json", "r", encoding="utf-8") as f:
                curr_state = json.load(f)

            steps = curr_state.get("steps", {
                "step_1": {"name": "1. Recon & CVE", "status": "PENDING", "required": True},
                "step_2": {"name": "2. Auth & Spider", "status": "COMPLETED", "required": True},
                "step_2_5": {"name": "2.5 Intelligent Contextual Analysis", "status": "PENDING", "required": True},
                "step_3": {"name": "3. MCP Synthesis", "status": "PENDING", "required": True},
                "step_4": {"name": "4. SDET Validation", "status": "PENDING", "required": True},
                "step_5": {"name": "5. Assembly", "status": "PENDING", "required": True},
                "step_6": {"name": "6. Pabot Parallel", "status": "PENDING", "required": False}
            })
            
            engine = AICoreEngine(None, os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate"))

            url = _resolve_active_project_url(sess.get("url")) or sess.get("url") or "https://example.com"
            engine.target_url = url
            user = sess.get("user", "")
            pwd = sess.get("password", "")
            detected_stack = sess.get("detected_stack", "Web App")
            if not detected_stack or str(detected_stack).strip() in ["Generic", "Generic Web App", "Web App", "Auto-Detect"]:
                from .engines.ai_core_engine import detect_application_stack
                detected_stack = detect_application_stack(url=str(url), dom_content=(combined_dom or sess.get("combined_dom") or ""))
            apis = sess.get("apis", [])
            page_manifest = sess.get("page_manifest", [])
            combined_dom = sess.get("combined_dom", "")
            selected_lang = sess.get("selected_language", "Python")
            selected_frame = sess.get("selected_framework", "Robot Framework + Pytest")
            sdet_phil = sess.get("sdet_philosophy", "Behavior-Driven Development (BDD)")

            # --- STEP 1: Re-Run Security Recon ---
            if payload.step_id == "step_1":
                steps["step_1"]["status"] = "RUNNING"
                engine.update_pipeline_state(status="running", progress=15, steps=steps, current_task="Re-triggering Step 1: NVD CVE Scan", current_command="Re-scanning target vulnerabilities...")
                scanner = NISTScanner()
                sec_report = scanner.scan_target(url)
                sess["security_report"] = sec_report
                steps["step_1"]["status"] = "COMPLETED"
                engine.update_pipeline_state(status="completed", progress=100, steps=steps, current_task="Step 1 Completed", current_command="Security scan updated.")

            # --- STEP 2.5: Re-Run Contextual BRD Analysis ---
            elif payload.step_id == "step_2_5":
                steps["step_2_5"]["status"] = "RUNNING"
                engine.update_pipeline_state(status="running", progress=45, steps=steps, current_task="Re-triggering Step 2.5: Contextual BRD Analysis", current_command="Re-analyzing product blueprint...")
                brd = engine.run_contextual_analysis(
                    url=url,
                    detected_stack=detected_stack,
                    combined_dom=combined_dom,
                    apis=apis,
                    model_name=payload.model_name,
                    ctx_size=8192,
                    strategy="Smart Auto-Offload",
                    temperature=0.0,
                    max_tokens=4096,
                    pipeline_steps=steps,
                    selected_language=selected_lang,
                    selected_framework=selected_frame,
                    sdet_philosophy=sdet_phil
                )
                sess["brd"] = brd
                steps["step_2_5"]["status"] = "COMPLETED"
                engine.update_pipeline_state(status="completed", progress=100, steps=steps, current_task="Step 2.5 Completed", current_command="BRD Analysis updated.")

            # --- STEP 3: Re-Run MCP Code Synthesis ---
            elif payload.step_id == "step_3":
                steps["step_3"]["status"] = "RUNNING"
                engine.update_pipeline_state(status="running", progress=60, steps=steps, current_task="Re-triggering Step 3: MCP Code Synthesis", current_command="Synthesizing test scripts...")
                custom_prompts = {"ui_script": payload.custom_prompt} if payload.custom_prompt else None
                engine.run_synthesis_and_assembly(
                    url=url,
                    detected_stack=detected_stack,
                    is_auth=sess.get("is_auth", False),
                    combined_dom=combined_dom,
                    apis=apis,
                    vectors=["Web UI Automation", "Master BDD Orchestration", "API Integration", "Performance / Load"],
                    model_name=payload.model_name,
                    parallel=True,
                    ctx_size=8192,
                    strategy="Smart Auto-Offload",
                    mcp_concurrency=2,
                    temperature=0.0,
                    max_tokens=4096,
                    pipeline_steps=steps,
                    custom_prompts=custom_prompts,
                    page_manifest=page_manifest,
                    username=user,
                    password=pwd,
                    sdet_philosophy=sdet_phil,
                    selected_language=selected_lang,
                    selected_framework=selected_frame,
                    llm_contextual_analysis=sess.get("brd", ""),
                    matrix_depth=payload.matrix_depth
                )

            # --- STEP 4: Re-Run SDET Code Review & Quality Gate ---
            elif payload.step_id == "step_4":
                steps["step_4"]["status"] = "RUNNING"
                engine.update_pipeline_state(status="running", progress=80, steps=steps, current_task="Re-triggering Step 4: SDET Code Review", current_command="Auditing generated scripts against standards...")
                evaluator = LLMEvaluatorEngine(os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate"), payload.model_name)
                
                ui_script = ""
                if os.path.exists("artifacts/scripts/auto_ui_test.py"):
                    with open("artifacts/scripts/auto_ui_test.py", "r", encoding="utf-8") as sf: ui_script = sf.read()
                
                review_res = evaluator.review_script(ui_script, "UI Selenium", payload.custom_prompt or "")
                with open("artifacts/logs/evaluation_results.json", "w", encoding="utf-8") as f:
                    json.dump(review_res, f, indent=4)
                
                steps["step_4"]["status"] = "COMPLETED"
                engine.update_pipeline_state(status="completed", progress=100, steps=steps, current_task="Step 4 Completed", current_command="SDET Code Review complete.")

            # --- STEP 6: Re-Run Test Execution ---
            elif payload.step_id == "step_6":
                steps["step_6"]["status"] = "RUNNING"
                init_tp = {"total": 0, "completed": 0, "remaining": 0, "passed": 0, "failed": 0, "reruns": 0, "rerun_count": 0}
                engine.update_pipeline_state(
                    status="running", 
                    progress=85, 
                    steps=steps, 
                    current_task="Re-triggering Step 6: Test Execution", 
                    current_command="Launching Pabot Parallel Cluster...",
                    test_progress=init_tp
                )
                result_data = curr_state.get("result", {})
                engine.run_execution_and_healing(
                    final_res=result_data,
                    pipeline_steps=steps,
                    model_name=payload.model_name,
                    url=url,
                    page_manifest=page_manifest,
                    apis=apis,
                    max_retries=3,
                    vectors=["Web UI Automation", "Master BDD Orchestration"]
                )

            with open(session_file, "w", encoding="utf-8") as f:
                json.dump(sess, f, indent=4)

        except Exception as e:
            trace = traceback.format_exc()
            with open("artifacts/logs/system_crash.log", "w", encoding="utf-8") as f: f.write(trace)
            with open("artifacts/logs/task_status.json", "w", encoding="utf-8") as f: json.dump({"status": "error", "error": str(e), "traceback": trace}, f)

    in_process_pool.submit(retrigger_worker)
    return {"status": "retriggering", "step": payload.step_id}

def nuke_all_resources(preserve_tokens: bool = True):
    # 0. Halt active background harness if executing
    global active_harness
    if active_harness:
        try:
            active_harness.stop()
        except Exception:
            pass

    # 1. Snapshot and retain latest run prompt and output token usage before cleanup
    try:
        snapshot_latest_run_tokens(status="purged")
    except Exception:
        pass

    # 2. Comprehensive process and resource cleanup
    try:
        execute_post_run_cleanup(preserve_tokens=preserve_tokens, run_status="purged")
    except Exception:
        pass

    # 2b. Direct OS signal termination of orphaned runners and display buffers
    try:
        subprocess.run(["pkill", "-9", "-f", "pabot|robot|pytest|chromium|chrome|chromedriver|k6|xvfb"], capture_output=True, timeout=3)
    except Exception:
        pass

    try:
        r = redis.Redis.from_url(os.environ.get("REDIS_URL", "redis://redis:6379/0"))
        for key in ["worker_speeds", "worker_heartbeats", "mcp_active_threads", "pipeline_paused"]:
            r.delete(key)
        if not preserve_tokens:
            r.delete("run_tokens")
            r.delete("run_input_tokens")
        celery_app.control.purge()
    except Exception:
        pass

    try:
        ollama_url = os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate")
        base_ps = ollama_url.replace("/api/generate", "/api/tags")
        res = requests.get(base_ps, timeout=2).json()
        for m in res.get("models", []):
            requests.post(ollama_url, json={"model": m["name"], "prompt": "", "keep_alive": 0}, timeout=2)
    except Exception:
        pass

    try:
        subprocess.run(["docker", "restart", "atp_celery"], capture_output=True, timeout=10)
    except Exception:
        pass

    with open("artifacts/logs/task_status.json", "w", encoding="utf-8") as f:
        json.dump({
            "status": "idle", 
            "progress": 0, 
            "steps": {}, 
            "current_task": "Ready", 
            "current_command": "Idle.", 
            "chunking": False
        }, f)


    try:
        os.makedirs("artifacts/logs", exist_ok=True)
        for log_file in ["engine_trace.jsonl", "llm_audit.jsonl", "llm_audit_enhanced.jsonl", "network_traffic.jsonl", "selenium_journal.log"]:
            path = f"artifacts/logs/{log_file}"
            if os.path.exists(path):
                open(path, "w", encoding="utf-8").close()
    except Exception:
        pass

    gc.collect()

@app.on_event("startup")
def start_docker_log_streamer():
    def tail_docker_logs():
        import shutil
        if os.path.exists("/.dockerenv") or not shutil.which("docker"):
            return
        while True:
            try:
                process = subprocess.Popen(
                    ["docker", "compose", "-f", "docker-compose-windows.yml", "logs", "-f", "--tail=100", "--no-color"],
                    stdout=subprocess.PIPE,
                    stderr=subprocess.STDOUT,
                    text=True
                )
                for line in process.stdout:
                    if line.strip():
                        timestamp = datetime.now().strftime("%H:%M:%S.%f")[:-3]
                        trace_entry = {
                            "time": timestamp,
                            "cat": "DOCKER",
                            "msg": line.strip(),
                            "elapsed": 0, "inference": 0, "tokens": 0, "speed": 0
                        }
                        os.makedirs("artifacts/logs", exist_ok=True)
                        with open("artifacts/logs/engine_trace.jsonl", "a", encoding="utf-8") as f:
                            f.write(json.dumps(trace_entry) + "\n")
                            f.flush()
                process.wait()
                time.sleep(5)
            except Exception:
                time.sleep(10)

    t = threading.Thread(target=tail_docker_logs, daemon=True)
    t.start()

@app.exception_handler(Exception)
async def global_exception_handler(request: Request, exc: Exception):
    err_type = exc.__class__.__name__ if isinstance(exc, ATPBaseException) else "SystemError"
    return JSONResponse(status_code=500, content={"error": str(exc), "type": err_type})

@app.get("/", response_class=HTMLResponse)
def serve_dashboard():
    content = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'static', 'index.html'), 'r', encoding='utf-8').read()
    response = HTMLResponse(content)
    response.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
    response.headers["Pragma"] = "no-cache"
    response.headers["Expires"] = "0"
    return response

