@app.get("/api/system/calibrate/status")
def get_calibration_status():
    import redis, os
    default_payload = {"status": "IDLE", "current_thread": 0, "last_vram": 0, "last_time": 0.0, "optimal": 1}
    try:
        r = redis.Redis.from_url(os.environ.get("REDIS_URL", "redis://redis:6379/0"), socket_timeout=1.5)
        raw_status = r.get("calibration_status")
        if isinstance(raw_status, bytes):
            status_str = raw_status.decode("utf-8", errors="ignore")
        elif isinstance(raw_status, str):
            status_str = raw_status
        else:
            status_str = "IDLE"

        def _safe_num(key, default, cast_fn):
            try:
                v = r.get(key)
                return cast_fn(v) if v is not None else default
            except Exception:
                return default

        return {
            "status": status_str or "IDLE",
            "current_thread": _safe_num("calibration_current_thread", 0, int),
            "last_vram": _safe_num("calibration_last_vram", 0, int),
            "last_time": _safe_num("calibration_last_time", 0.0, float),
            "optimal": _safe_num("calibration_optimal", 1, int)
        }
    except Exception:
        return default_payload

class ConcurrencyPayload(BaseModel):
    concurrency: int

@app.post("/api/system/concurrency")
def update_concurrency(payload: ConcurrencyPayload):
    try:
        req_conc = payload.concurrency
        telemetry = get_system_and_gpu_telemetry()
        vram_avail_gb = 0.0
        
        if telemetry["gpu"]["status"] != "CPU_BOUND":
            vram_total_gb = telemetry["gpu"]["vram_total"] / 1024
        else:
            vram_total_gb = telemetry["system"]["ram_total_gb"]
            
        r = redis.Redis.from_url(os.environ.get("REDIS_URL", "redis://redis:6379/0"))
        safe_conc = min(max(1, int(vram_total_gb / 1.5)), 8)
        try:
            calibrated = int(r.get("calibration_optimal") or 0)
            safe_conc = max(safe_conc, calibrated)
        except: pass
        
        is_capped = False
        final_conc = req_conc
        msg = "Concurrency updated successfully."
        
        if req_conc > safe_conc:
            is_capped = True
            final_conc = safe_conc
            msg = f"Resource Shield Active: Requested {req_conc} threads exceeds safe hardware limit. Capped at {safe_conc}."
            
        r.set("mcp_global_concurrency", final_conc)
        return {"status": "success", "concurrency": final_conc, "capped": is_capped, "message": msg}
    except Exception as e:
        return {"status": "error", "message": str(e)}

