@app.post("/api/coverage/draft")
def api_draft_coverage_gap(payload: CoverageFulfillPayload):
    """Creates a test candidate without adding it to an executable suite."""
    try:
        try:
            from .engines.coverage_engine import CoverageMatrixEngine
        except ImportError:
            from aspice_qa_framework.engines.coverage_engine import CoverageMatrixEngine
        engine = CoverageMatrixEngine(".")
        draft = engine.fulfill_coverage_gap(payload.route, payload.discipline.upper(), payload.custom_instructions or "", payload.use_llm if payload.use_llm is not None else True, payload.model_name, persist=False)
        validation = engine.validate_coverage_draft(draft)
        draft_id = f"coverage_{int(time.time())}_{os.urandom(4).hex()}"
        draft.update({"draft_id": draft_id, "review_status": "valid" if validation["status"] == "valid" else "needs_fix", "validation": validation})
        os.makedirs(os.path.dirname(_coverage_draft_path(draft_id)), exist_ok=True)
        with open(_coverage_draft_path(draft_id), "w", encoding="utf-8") as destination:
            json.dump(draft, destination, indent=2)
        return {"status": "success", "draft": draft}
    except Exception as e:
        return {"status": "error", "message": str(e)}

@app.post("/api/coverage/draft/validate")
def api_validate_coverage_draft(payload: CoverageDraftActionPayload):
    try:
        with open(_coverage_draft_path(payload.draft_id), "r", encoding="utf-8") as source:
            draft = json.load(source)
        if payload.code_snippet is not None:
            draft["code_snippet"] = payload.code_snippet
        try:
            from .engines.coverage_engine import CoverageMatrixEngine
        except ImportError:
            from aspice_qa_framework.engines.coverage_engine import CoverageMatrixEngine
        validation = CoverageMatrixEngine(".").validate_coverage_draft(draft)
        draft.update({"validation": validation, "review_status": "valid" if validation["status"] == "valid" else "needs_fix"})
        with open(_coverage_draft_path(payload.draft_id), "w", encoding="utf-8") as destination:
            json.dump(draft, destination, indent=2)
        return {"status": "success", "draft": draft}
    except Exception as e:
        return {"status": "error", "message": str(e)}

@app.post("/api/coverage/draft/approve")
def api_approve_coverage_draft(payload: CoverageDraftActionPayload):
    try:
        with open(_coverage_draft_path(payload.draft_id), "r", encoding="utf-8") as source:
            draft = json.load(source)
        try:
            from .engines.coverage_engine import CoverageMatrixEngine
        except ImportError:
            from aspice_qa_framework.engines.coverage_engine import CoverageMatrixEngine
        approval = CoverageMatrixEngine(".").promote_coverage_draft(draft)
        if approval["status"] != "approved":
            return {"status": "error", "message": "SDET validation must pass before approval.", "validation": approval["validation"]}
        draft.update({"review_status": "approved", "approved_at": time.strftime("%Y-%m-%d %H:%M:%S"), "approval": approval})
        with open(_coverage_draft_path(payload.draft_id), "w", encoding="utf-8") as destination:
            json.dump(draft, destination, indent=2)
        return {"status": "success", "draft": draft, "updated_matrix": approval["updated_matrix"], "next_action": "Run the approved suite through the execution controls."}
    except Exception as e:
        return {"status": "error", "message": str(e)}

