@app.get("/api/bot-protection/status")
def api_get_bot_protection_status(target_url: Optional[str] = Query(None)):
    """
    Returns the current anti-bot protection diagnostics, saved cookie inventory,
    recent injection events, and historical challenge encounters.
    """
    try:
        try:
            from .engines.modern_ui_engine import ModernUIEngine
        except ImportError:
            from aspice_qa_framework.engines.modern_ui_engine import ModernUIEngine

        saved_cookies = ModernUIEngine.get_saved_cookies_list()
        used_log = ModernUIEngine.get_used_cookies_log(limit=25)

        recent_events = []
        rep_file = "artifacts/reports/anti_bot_report.json"
        if os.path.exists(rep_file):
            try:
                with open(rep_file, "r", encoding="utf-8") as f:
                    recent_events = json.load(f)[:25]
            except Exception:
                pass

        providers_seen = set()
        for ev in recent_events:
            p = ev.get("bot_protection", {}).get("provider")
            if p and p != "NONE":
                providers_seen.add(p)

        return {
            "status": "success",
            "summary": {
                "active_barriers_detected": len([e for e in recent_events if e.get("bot_protection", {}).get("is_active")]),
                "unique_providers_encountered": list(providers_seen),
                "total_clearance_cookies_saved": len(saved_cookies),
                "recent_injections_count": len(used_log)
            },
            "saved_cookies": [{"name": c.get("name"), "domain": c.get("domain"), "httpOnly": c.get("httpOnly"), "secure": c.get("secure")} for c in saved_cookies[:50]],
            "recent_events": recent_events,
            "used_cookies_log": used_log
        }
    except Exception as e:
        return {"status": "error", "message": str(e)}

@app.post("/api/bot-protection/inject-cookies")
def api_inject_cookies(payload: InjectCookiesPayload):
    """
    Saves external clearance cookies or Netscape/Playwright cookies into persistent storage and Redis.
    """
    try:
        try:
            from .engines.modern_ui_engine import ModernUIEngine
        except ImportError:
            from aspice_qa_framework.engines.modern_ui_engine import ModernUIEngine

        if not payload.cookies:
            return {"status": "error", "message": "No cookies provided in payload"}

        os.makedirs("artifacts/cookies", exist_ok=True)
        cookie_path = "artifacts/cookies/cf_session.json"
        existing = ModernUIEngine.get_saved_cookies_list()
        merged_dict = {c["name"]: c for c in existing if c.get("name")}
        for c in payload.cookies:
            if c.get("name") and c.get("value"):
                if payload.domain and not c.get("domain"):
                    c["domain"] = payload.domain
                merged_dict[c["name"]] = c

        final_list = list(merged_dict.values())
        with open(cookie_path, "w", encoding="utf-8") as f:
            json.dump(final_list, f, indent=2)

        ModernUIEngine.record_used_cookies(
            context="api_manual_injection",
            cookies=payload.cookies,
            domain=payload.domain or payload.target_url or ""
        )

        return {
            "status": "success",
            "message": f"Successfully registered {len(payload.cookies)} clearance cookies.",
            "total_saved": len(final_list)
        }
    except Exception as e:
        return {"status": "error", "message": str(e)}

