@app.post("/api/scripts/save")
def save_script(payload: ScriptPayload):
    os.makedirs("artifacts/scripts", exist_ok=True)
    mapping = {
        "lib": ("keywords_lib.py", "keywords_lib"),
        "ui": ("auto_ui_test.py", "ui_py"),
        "wdio": ("auto_ui_wdio.js", "wdio_js"),  # [UNICODE:26A1] WebdriverIO Save
        "playwright": ("auto_ui_playwright.spec.ts", "playwright_ts"),
        "java": ("AutoUITest.java", "java_code"),
        "api": ("auto_api_test.py", "api_py"),
        "k6": ("auto_load_test.js", "k6_js"),
        "unit": ("auto_unit_test.py", "unit_code"),
        "robot": ("auto_suite.robot", "robot_file"),
        "guide": ("../reports/README_RUN_GUIDE.md", "run_guide")
    }
    item = mapping.get(payload.script_type)
    if not item:
        return {"status": "error", "message": "Unknown script type"}
    filename, res_key = item
    filepath = f"artifacts/scripts/{filename}" if not filename.startswith("..") else f"artifacts/{filename[3:]}"
    with open(filepath, "w", encoding="utf-8") as f:
        f.write(payload.script_code)
    
    if os.path.exists("artifacts/logs/task_status.json"):
        try:
            with open("artifacts/logs/task_status.json", "r+", encoding="utf-8") as f:
                d = json.load(f)
                if "result" in d and isinstance(d["result"], dict):
                    d["result"][res_key] = payload.script_code
                    f.seek(0)
                    json.dump(d, f, indent=2)
                    f.truncate()
        except Exception: pass
        
    return {"status": "success", "message": f"Saved {filename}"}

@app.post("/api/scripts/chat_save")
def chat_save_script(payload: ChatSavePayload):
    # Ensure it only writes within artifacts directory for safety
    if ".." in payload.filepath or payload.filepath.startswith("/"):
        return {"status": "error", "message": "Invalid filepath"}
    
    filepath = payload.filepath
    if not filepath.startswith("artifacts/"):
        filepath = f"artifacts/scripts/{filepath}"
        
    os.makedirs(os.path.dirname(filepath), exist_ok=True)
    with open(filepath, "w", encoding="utf-8") as f:
        f.write(payload.content)
        
    return {"status": "success", "message": f"Saved to {filepath}"}


