@app.get("/api/telemetry/full-sync")
def full_telemetry_sync():
    def read_jsonl(path, limit=300):
        records = []
        if os.path.exists(path):
            try:
                file_size = os.path.getsize(path)
                with open(path, "r", encoding="utf-8") as f:
                    if file_size > 500 * 1024:
                        try:
                            f.seek(file_size - 300 * 1024)
                            f.readline()
                        except:
                            pass
                    lines = f.readlines()
                    for line in lines[-limit:]:
                        line_str = line.strip()
                        if line_str:
                            try: records.append(json.loads(line_str))
                            except: pass
            except: pass
        return records

    default_steps = {
        "step_1": {"name": "1. Recon & CVE", "status": "PENDING", "required": True},
        "step_2": {"name": "2. Auth & Spider", "status": "PENDING", "required": True},
        "step_3": {"name": "3. MCP Synthesis", "status": "PENDING", "required": True},
        "step_4": {"name": "4. SDET Validation", "status": "PENDING", "required": True},
        "step_5": {"name": "5. Assembly", "status": "PENDING", "required": True},
        "step_6": {"name": "6. Pabot Parallel", "status": "PENDING", "required": False}
    }

    default_steps = {
        "step_1": {"name": "1. Recon & CVE", "status": "PENDING", "required": True},
        "step_2": {"name": "2. Auth & Spider", "status": "PENDING", "required": True},
        "step_3": {"name": "3. MCP Synthesis", "status": "PENDING", "required": True},
        "step_4": {"name": "4. SDET Validation", "status": "PENDING", "required": True},
        "step_5": {"name": "5. Assembly", "status": "PENDING", "required": True},
        "step_6": {"name": "6. Pabot Parallel", "status": "PENDING", "required": False}
    }

    task_data = None
    if os.path.exists("artifacts/logs/task_status.json"):
        try:
            with open("artifacts/logs/task_status.json", "r", encoding="utf-8") as f:
                task_data = json.load(f)
        except Exception:
            task_data = {"status": "idle", "progress": 0, "steps": default_steps, "current_task": "Ready", "current_command": "Idle.", "chunking": False}

    if not isinstance(task_data, dict):
        task_data = {"status": "idle", "progress": 0, "steps": default_steps, "current_task": "Ready", "current_command": "Idle.", "chunking": False}

    if "status" not in task_data or not task_data["status"]:
        task_data["status"] = "idle"

    raw_steps = task_data.get("steps")
    if not isinstance(raw_steps, dict) or not raw_steps:
        task_data["steps"] = default_steps
    else:
        sanitized_steps = {}
        for sk, sv in raw_steps.items():
            if isinstance(sv, dict):
                sanitized_steps[sk] = {
                    "name": sv.get("name") or sk,
                    "status": sv.get("status") or "PENDING",
                    "required": sv.get("required", True)
                }
            else:
                sanitized_steps[sk] = {"name": sk, "status": "PENDING", "required": True}
        task_data["steps"] = sanitized_steps

    cmd_lower = str(task_data.get("current_command", "") + " " + task_data.get("current_task", "")).lower()
    if "k6" in cmd_lower or "perf" in cmd_lower or "load" in cmd_lower:
        active_discipline = "PERFORMANCE"
    elif "api" in cmd_lower or "endpoint" in cmd_lower or "contract" in cmd_lower or "requests" in cmd_lower:
        active_discipline = "API"
    elif "pabot" in cmd_lower or "robot" in cmd_lower or "browser" in cmd_lower or "ui" in cmd_lower or "selenium" in cmd_lower or "crawl" in cmd_lower or "spider" in cmd_lower:
        active_discipline = "UI"
    else:
        active_discipline = task_data.get("active_discipline") or ("UI" if task_data.get("status") in ("running", "processing") else None)
    task_data["active_discipline"] = active_discipline

    if os.path.exists("artifacts/logs/antibot_quarantine.json"):
        try:
            with open("artifacts/logs/antibot_quarantine.json", "r", encoding="utf-8") as _abf:
                _ab_data = json.load(_abf)
                task_data["antibot_quarantined"] = _ab_data.get("quarantined", True)
                task_data["antibot_quarantined_url"] = _ab_data.get("url")
                task_data["antibot_quarantined_msg"] = _ab_data.get("message")
        except Exception:
            pass

    selenium_journal = open("artifacts/logs/selenium_journal.log", "r", encoding="utf-8").read() if os.path.exists("artifacts/logs/selenium_journal.log") else "No Selenium actions recorded yet."
    
    review_iterations = []
    if os.path.exists("artifacts/logs/review_iterations.json"):
        try:
            with open("artifacts/logs/review_iterations.json", "r", encoding="utf-8") as f:
                review_iterations = json.load(f)
        except: pass

    # Ingest MRD and Scenarios for immediate frontend hydration
    mrd_text = ""
    for _mp in ["artifacts/reports/Master_Requirements_Document.md", "artifacts/reports/master_requirements_document.md"]:
        if os.path.exists(_mp):
            try:
                with open(_mp, "r", encoding="utf-8") as _mf: mrd_text = _mf.read()
                break
            except Exception: pass
    scen_text = ""
    if os.path.exists("artifacts/reports/test_scenarios.md"):
        try:
            with open("artifacts/reports/test_scenarios.md", "r", encoding="utf-8") as _sf: scen_text = _sf.read()
        except Exception: pass

    return {
        "task": task_data,
        "mrd_report": mrd_text,
        "scenarios_report": scen_text,
        "traces": read_jsonl("artifacts/logs/engine_trace.jsonl", limit=400),
        "selenium_journal": selenium_journal,
        "llm_records": read_jsonl("artifacts/logs/llm_audit.jsonl", limit=100),
        "llm_records_enhanced": read_jsonl("artifacts/logs/llm_audit_enhanced.jsonl", limit=100),
        "network_records": read_jsonl("artifacts/logs/network_traffic.jsonl", limit=200),
        "review_iterations": review_iterations,
        "telemetry": get_system_and_gpu_telemetry()
    }

@app.get("/api/storage/info")
def get_storage_info():
    def get_dir_size(path):
        total = 0
        if os.path.exists(path):
            for root, _, files in os.walk(path):
                for f in files: total += os.path.getsize(os.path.join(root, f))
        return round(total / (1024 * 1024), 2)
    
    models = []
    try:
        url = os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate").replace("/api/generate", "/api/tags")
        res = requests.get(url, timeout=2).json()
        for m in res.get("models", []):
            models.append({"name": m["name"], "size_gb": round(m.get("size", 0)/(1024**3), 2)})
    except: pass
    
    docker_stats = []
    try:
        df_res = subprocess.run(["docker", "system", "df", "--format", "{{json .}}"], capture_output=True, text=True, timeout=10)
        for line in df_res.stdout.strip().split("\n"):
            if line.strip(): docker_stats.append(json.loads(line))
    except: pass

    return {
        "logs_mb": get_dir_size("artifacts/logs"),
        "reports_mb": get_dir_size("artifacts/reports"),
        "scripts_mb": get_dir_size("artifacts/scripts"),
        "screencast_mb": get_dir_size("artifacts/screencast"),
        "ollama_models": models,
        "docker_stats": docker_stats
    }

def execute_safe_docker_clean():
    freed_parts = []
    details = {"containers": "0 B", "images": "0 B", "builder": "0 B", "temp_files_cleaned": 0}
    try:
        c_res = subprocess.run(["docker", "container", "prune", "-f"], capture_output=True, text=True, timeout=20)
        if "Total reclaimed space:" in c_res.stdout:
            sp = c_res.stdout.split("Total reclaimed space:")[1].strip().split("\n")[0]
            details["containers"] = sp
            if sp and sp != "0B": freed_parts.append(f"Containers: {sp}")
    except Exception: pass

    try:
        i_res = subprocess.run(["docker", "image", "prune", "-f"], capture_output=True, text=True, timeout=30)
        if "Total reclaimed space:" in i_res.stdout:
            sp = i_res.stdout.split("Total reclaimed space:")[1].strip().split("\n")[0]
            details["images"] = sp
            if sp and sp != "0B": freed_parts.append(f"Images: {sp}")
    except Exception: pass

    try:
        b_res = subprocess.run(["docker", "builder", "prune", "-f"], capture_output=True, text=True, timeout=30)
        if "Total reclaimed space:" in b_res.stdout:
            sp = b_res.stdout.split("Total reclaimed space:")[1].strip().split("\n")[0]
            details["builder"] = sp
            if sp and sp != "0B": freed_parts.append(f"Builder: {sp}")
    except Exception: pass

    temp_cleaned = 0
    import glob, tempfile
    try:
        tmp_dir = tempfile.gettempdir()
        for pat in ["chrome_core_*", ".org.chromium.*", ".com.google.Chrome.*"]:
            for p in glob.glob(os.path.join(tmp_dir, pat)):
                try:
                    if os.path.isdir(p):
                        shutil.rmtree(p, ignore_errors=True)
                        temp_cleaned += 1
                    elif os.path.isfile(p):
                        os.remove(p)
                        temp_cleaned += 1
                except Exception: pass
        if os.path.exists("artifacts/logs/chromedriver.log"):
            try:
                os.remove("artifacts/logs/chromedriver.log")
                temp_cleaned += 1
            except Exception: pass
    except Exception: pass
    details["temp_files_cleaned"] = temp_cleaned

    total_str = " | ".join(freed_parts) if freed_parts else "0 B (All resources optimal)"
    if temp_cleaned > 0:
        total_str += f" (+ {temp_cleaned} temp profiles swept)"
    return {"status": "success", "mode": "safe", "reclaimed_space": total_str, "details": details}

def execute_deep_docker_clean():
    freed_parts = []
    details = {"system": "0 B", "builder": "0 B", "volumes": "0 B", "stale_screencasts_purged": 0}
    try:
        s_res = subprocess.run(["docker", "system", "prune", "-f", "--volumes=false"], capture_output=True, text=True, timeout=60)
        if "Total reclaimed space:" in s_res.stdout:
            sp = s_res.stdout.split("Total reclaimed space:")[1].strip().split("\n")[0]
            details["system"] = sp
            if sp and sp != "0B": freed_parts.append(f"System: {sp}")
    except Exception: pass

    try:
        b_res = subprocess.run(["docker", "builder", "prune", "-a", "-f"], capture_output=True, text=True, timeout=60)
        if "Total reclaimed space:" in b_res.stdout:
            sp = b_res.stdout.split("Total reclaimed space:")[1].strip().split("\n")[0]
            details["builder"] = sp
            if sp and sp != "0B": freed_parts.append(f"Builder: {sp}")
    except Exception: pass

    try:
        v_res = subprocess.run(["docker", "volume", "prune", "-f"], capture_output=True, text=True, timeout=40)
        if "Total reclaimed space:" in v_res.stdout:
            sp = v_res.stdout.split("Total reclaimed space:")[1].strip().split("\n")[0]
            details["volumes"] = sp
            if sp and sp != "0B": freed_parts.append(f"Volumes: {sp}")
    except Exception: pass

    purged = 0
    try:
        for root, dirs, files in os.walk("artifacts/screencast"):
            for f in files:
                fp = os.path.join(root, f)
                try:
                    if os.path.getmtime(fp) < time.time() - 86400:
                        os.remove(fp)
                        purged += 1
                except Exception: pass
    except Exception: pass
    details["stale_screencasts_purged"] = purged

    total_str = " | ".join(freed_parts) if freed_parts else "0 B"
    if purged > 0:
        total_str += f" (+ {purged} stale frames swept)"
    return {"status": "success", "mode": "deep", "reclaimed_space": total_str, "details": details}

@app.post("/api/docker/storage/safe-clean")
def api_docker_safe_clean():
    return execute_safe_docker_clean()

@app.post("/api/docker/storage/deep-clean")
def api_docker_deep_clean():
    return execute_deep_docker_clean()

@app.get("/api/node/processes")
def get_node_processes():
    server_pid = os.getpid()
    curr_time = time.time()
    procs = []
    for p in psutil.process_iter(['pid', 'name', 'status', 'memory_info', 'create_time']):
        try:
            info = p.info
            pid = info.get('pid')
            name = str(info.get('name') or '')
            name_low = name.lower()
            mem_i = info.get('memory_info')
            mem_rss = mem_i.rss if mem_i else 0
            mem_mb = round(mem_rss / (1024 * 1024), 1)

            is_qa = any(x in name_low for x in ['chrome', 'chromium', 'chromedriver', 'celery', 'pabot', 'robot', 'pytest', 'k6', 'ollama', 'redis', 'uvicorn', 'python', 'node'])
            if is_qa or mem_mb > 50:
                try:
                    cmd_l = p.cmdline() or []
                    cmd = " ".join(cmd_l)
                except Exception:
                    cmd = name
                cmd_low = cmd.lower()

                if 'chromedriver' in name_low or 'chromedriver' in cmd_low:
                    cat = 'WebDriver Bridge'
                elif 'chrome' in name_low or 'chromium' in name_low:
                    cat = 'Web Browser (Headless)'
                elif 'celery' in name_low or 'celery' in cmd_low:
                    cat = 'Worker / Celery'
                elif 'pabot' in name_low or 'pabot' in cmd_low or 'robot' in name_low or 'robot' in cmd_low:
                    cat = 'Test Orchestrator'
                elif 'pytest' in name_low or 'pytest' in cmd_low:
                    cat = 'Test Runner'
                elif 'ollama' in name_low or 'llama' in name_low or 'ollama' in cmd_low:
                    cat = 'AI Engine (Ollama)'
                elif 'redis' in name_low:
                    cat = 'Cache Store (Redis)'
                elif 'k6' in name_low or 'artillery' in cmd_low:
                    cat = 'Load Engine (k6)'
                elif pid == server_pid or 'main.py' in cmd_low or 'uvicorn' in cmd_low:
                    cat = 'Core Engine (ATP Server)'
                elif 'python' in name_low:
                    cat = 'Python Worker'
                elif 'node' in name_low:
                    cat = 'Node.js Runtime'
                else:
                    cat = 'System Service'

                try:
                    cpu_val = round(p.cpu_percent(interval=None), 1)
                except Exception:
                    cpu_val = 0.0

                create_t = info.get('create_time', curr_time)
                uptime_s = int(curr_time - create_t) if create_t else 0

                procs.append({
                    "pid": pid,
                    "name": name,
                    "category": cat,
                    "cpu": cpu_val,
                    "mem_mb": mem_mb,
                    "status": str(info.get('status', 'running')),
                    "cmd": cmd[:70] + "..." if len(cmd) > 70 else cmd,
                    "full_cmd": cmd[:400],
                    "uptime_seconds": uptime_s,
                    "is_core": (pid == server_pid),
                    "is_killable": (pid != server_pid)
                })
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            pass

    procs.sort(key=lambda x: (x.get("cpu", 0) * 10 + x.get("mem_mb", 0)), reverse=True)
    mem = psutil.virtual_memory()
    return {
        "status": "success",
        "timestamp": curr_time,
        "summary": {
            "total_processes": len(psutil.pids()),
            "monitored_count": len(procs),
            "cpu_percent": psutil.cpu_percent(interval=None),
            "ram_used_mb": round(mem.used / (1024 * 1024), 1),
            "ram_total_mb": round(mem.total / (1024 * 1024), 1),
            "ram_percent": mem.percent
        },
        "processes": procs
    }

@app.post("/api/node/process/kill")
def kill_node_process(req: ProcessKillRequest):
    server_pid = os.getpid()
    if req.pid == server_pid and not req.force:
        return JSONResponse(status_code=400, content={"status": "error", "message": "Cannot terminate core ATP server process without force=True."})
    try:
        proc = psutil.Process(req.pid)
        p_name = proc.name()
        children = proc.children(recursive=True)
        for child in children:
            try:
                child.terminate()
            except Exception: pass
        _, still_alive = psutil.wait_procs(children, timeout=1.0)
        for child in still_alive:
            try:
                child.kill()
            except Exception: pass

        proc.terminate()
        try:
            proc.wait(timeout=1.5)
        except psutil.TimeoutExpired:
            proc.kill()

        return {"status": "success", "pid": req.pid, "name": p_name, "message": f"Successfully terminated {p_name} (PID {req.pid})"}
    except psutil.NoSuchProcess:
        return {"status": "success", "pid": req.pid, "message": f"Process PID {req.pid} was already terminated."}
    except Exception as e:
        return JSONResponse(status_code=500, content={"status": "error", "message": f"Failed to kill PID {req.pid}: {str(e)}"})

@app.post("/api/node/process/reset")
def reset_node_process(req: ProcessResetRequest):
    target = (req.target or "browsers").lower()
    killed_names = []

    if target in ["browsers", "browser"]:
        import glob, tempfile
        for p in psutil.process_iter(['pid', 'name']):
            try:
                n = str(p.info.get('name') or '').lower()
                if any(x in n for x in ['chrome', 'chromium', 'chromedriver']):
                    p.terminate()
                    killed_names.append(f"{n}:{p.info.get('pid')}")
            except Exception: pass
        try:
            tmp_dir = tempfile.gettempdir()
            for pat in ["chrome_core_*", ".org.chromium.*", ".com.google.Chrome.*"]:
                for d in glob.glob(os.path.join(tmp_dir, pat)):
                    try:
                        if os.path.isdir(d): shutil.rmtree(d, ignore_errors=True)
                    except Exception: pass
        except Exception: pass
        return {"status": "success", "target": "browsers", "killed_count": len(killed_names), "message": f"Reset browser pool: terminated {len(killed_names)} browser/driver processes and purged temp profiles."}

    elif target in ["workers", "runners"]:
        for p in psutil.process_iter(['pid', 'name']):
            try:
                n = str(p.info.get('name') or '').lower()
                if any(x in n for x in ['celery', 'pabot', 'robot', 'pytest']):
                    p.terminate()
                    killed_names.append(f"{n}:{p.info.get('pid')}")
            except Exception: pass
        try:
            import redis
            r = redis.Redis.from_url(os.environ.get("REDIS_URL", "redis://redis:6379/0"), decode_responses=True)
            r.delete("worker_speeds")
            r.delete("worker_heartbeats")
        except Exception: pass
        return {"status": "success", "target": "workers", "killed_count": len(killed_names), "message": f"Reset test workers: terminated {len(killed_names)} workers and cleared heartbeats."}

    elif target in ["model", "ollama"]:
        try:
            evict_ollama_model()
            return {"status": "success", "target": "model", "message": "Evicted active LLM model from VRAM."}
        except Exception as e:
            return {"status": "error", "message": str(e)}

    elif req.pid:
        try:
            p = psutil.Process(req.pid)
            name = p.name()
            p.terminate()
            return {"status": "success", "pid": req.pid, "message": f"Reset process {name} (PID {req.pid})"}
        except Exception as e:
            return {"status": "error", "message": str(e)}

    return {"status": "error", "message": f"Unknown reset target: {target}"}

@app.post("/api/storage/clean")
def clean_storage(req: StorageAction):
    freed_space = "0 B"
    details = None
    if req.action == "clean_logs":
        shutil.rmtree("artifacts/logs", ignore_errors=True); os.makedirs("artifacts/logs", exist_ok=True)
    elif req.action == "clean_reports":
        shutil.rmtree("artifacts/reports", ignore_errors=True); os.makedirs("artifacts/reports", exist_ok=True)
    elif req.action == "clean_screencast":
        shutil.rmtree("artifacts/screencast", ignore_errors=True); os.makedirs("artifacts/screencast", exist_ok=True)
    elif req.action == "clean_all":
        for d in ["logs", "reports", "scripts", "screencast", "specs"]:
            shutil.rmtree(f"artifacts/{d}", ignore_errors=True)
            os.makedirs(f"artifacts/{d}", exist_ok=True)
    elif req.action == "delete_model" and req.target:
        try:
            url = os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate").replace("/api/generate", "/api/delete")
            requests.delete(url, json={"name": req.target}, timeout=10)
        except Exception as e: return {"status": "error", "message": str(e)}
    elif req.action == "clean_docker_safe":
        res = execute_safe_docker_clean()
        freed_space = res["reclaimed_space"]
        details = res.get("details")
    elif req.action == "clean_docker_deep":
        res = execute_deep_docker_clean()
        freed_space = res["reclaimed_space"]
        details = res.get("details")
    
    resp = {"status": "success", "freed_space": freed_space}
    if details: resp["details"] = details
    return resp

class ModelPullRequest(BaseModel):
    model: str

active_pull_tasks: Dict[str, Any] = {}

@app.get("/api/models")
def get_models(q: Optional[str] = None):
    # Curated catalog of sovereign models suitable for enterprise QA, reasoning, and code synthesis
    CATALOG_SPECS = {
        # --- <3GB VRAM Safe (Ultra-Fast, Guaranteed 100% Resident on 4GB Laptops / RTX 3050) ---
        "deepseek-r1:1.5b": {"size_gb": 1.04, "is_under_3gb": True, "param": "1.8B", "quant": "Q4_K_M", "desc": "Reasoning & BDD Test Logic (Recommended)"},
        "qwen2.5-coder:1.5b": {"size_gb": 0.98, "is_under_3gb": True, "param": "1.5B", "quant": "Q4_K_M", "desc": "High-Speed AST Code Synthesizer"},
        "qwen2.5-coder:3b": {"size_gb": 1.95, "is_under_3gb": True, "param": "3.0B", "quant": "Q4_K_M", "desc": "Balanced Code Synthesizer & Heuristic Healer"},
        "qwen2.5:1.5b": {"size_gb": 0.98, "is_under_3gb": True, "param": "1.5B", "quant": "Q4_K_M", "desc": "General Instruction Following"},
        "qwen2.5:3b": {"size_gb": 1.95, "is_under_3gb": True, "param": "3.0B", "quant": "Q4_K_M", "desc": "Fast Multi-Turn Reasoning Agent"},
        "llama3.2:1b": {"size_gb": 1.31, "is_under_3gb": True, "param": "1.0B", "quant": "Q4_K_M", "desc": "Ultra-Fast Compact Agent"},
        "llama3.2:3b": {"size_gb": 2.01, "is_under_3gb": True, "param": "3.2B", "quant": "Q4_K_M", "desc": "Balanced High Performance Agent"},
        "phi3:mini": {"size_gb": 2.18, "is_under_3gb": True, "param": "3.8B", "quant": "Q4_K_M", "desc": "High-Density Compact Reasoning"},
        "phi3.5:3.8b": {"size_gb": 2.21, "is_under_3gb": True, "param": "3.8B", "quant": "Q4_K_M", "desc": "Multilingual High-Density Reasoning"},
        "gemma2:2b": {"size_gb": 1.63, "is_under_3gb": True, "param": "2.0B", "quant": "Q4_K_M", "desc": "Google Gemma 2 Ultra-Compact"},
        "starcoder2:3b": {"size_gb": 1.72, "is_under_3gb": True, "param": "3.0B", "quant": "Q4_K_M", "desc": "Fast StarCoder Code Synthesizer"},
        "nomic-embed-text:latest": {"size_gb": 0.26, "is_under_3gb": True, "param": "137M", "quant": "F16", "desc": "Vector DOM & Semantic Embedding"},

        # --- Heavy Models (>3GB VRAM - Workstation / Server Mode) ---
        "deepseek-r1:7b": {"size_gb": 4.68, "is_under_3gb": False, "param": "7.0B", "quant": "Q4_K_M", "desc": "Deep Architectural Reasoning (Workstation)"},
        "deepseek-r1:8b": {"size_gb": 4.92, "is_under_3gb": False, "param": "8.0B", "quant": "Q4_K_M", "desc": "Advanced Reasoning & Step Verification"},
        "qwen2.5-coder:7b": {"size_gb": 4.68, "is_under_3gb": False, "param": "7.0B", "quant": "Q4_K_M", "desc": "Heavy Multi-file Code Generation"},
        "qwen2.5:7b": {"size_gb": 4.68, "is_under_3gb": False, "param": "7.0B", "quant": "Q4_K_M", "desc": "High Accuracy General Intelligence"},
        "llama3.1:8b": {"size_gb": 4.92, "is_under_3gb": False, "param": "8.0B", "quant": "Q4_K_M", "desc": "Industry Standard General Model"},
        "codellama:7b": {"size_gb": 3.82, "is_under_3gb": False, "param": "7.0B", "quant": "Q4_K_M", "desc": "Specialized Python & Robot Synthesizer"},
        "mistral:7b": {"size_gb": 4.11, "is_under_3gb": False, "param": "7.0B", "quant": "Q4_0", "desc": "General Heavy Synthesizer (Workstation)"},
        "gemma2:9b": {"size_gb": 5.42, "is_under_3gb": False, "param": "9.0B", "quant": "Q4_K_M", "desc": "Google Gemma 2 Workstation Model"}
    }

    candidates = [
        os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate").replace("/api/generate", "/api/tags"),
        "http://ollama_engine:11434/api/tags",
        "http://localhost:11434/api/tags",
        "http://127.0.0.1:11434/api/tags",
        "http://host.docker.internal:11434/api/tags"
    ]

    installed_raw = []
    active_running = None

    for url in candidates:
        try:
            res = requests.get(url, timeout=2.5)
            if res.status_code == 200:
                installed_raw = res.json().get("models", [])
                # Also check active running model via /api/ps
                try:
                    ps_url = url.replace("/api/tags", "/api/ps")
                    ps_res = requests.get(ps_url, timeout=1.5)
                    if ps_res.status_code == 200:
                        ps_models = ps_res.json().get("models", [])
                        if ps_models: active_running = ps_models[0].get("name")
                except: pass
                break
        except: continue

    detailed_models = []
    downloaded_names = []
    under_3gb_names = []
    seen_names = set()

    # 1. Process all models actually installed in Ollama
    for m in installed_raw:
        name = m.get("name", "")
        if not name or name in seen_names: continue
        seen_names.add(name)

        size_bytes = m.get("size", 0)
        size_gb = round(size_bytes / (1024**3), 2)
        size_mb = round(size_bytes / (1024**2))
        details = m.get("details", {})
        param = details.get("parameter_size", CATALOG_SPECS.get(name, {}).get("param", "1.5B"))
        quant = details.get("quantization_level", CATALOG_SPECS.get(name, {}).get("quant", "Q4_K_M"))
        family = details.get("family", "")

        is_under_3gb = (size_gb <= 3.2)
        downloaded_names.append(name)
        if is_under_3gb: under_3gb_names.append(name)

        spec = CATALOG_SPECS.get(name, {})
        desc = spec.get("desc", f"Installed [BULLET] {size_gb} GB")

        detailed_models.append({
            "name": name,
            "size_bytes": size_bytes,
            "size_gb": size_gb,
            "size_mb": size_mb,
            "is_under_3gb": is_under_3gb,
            "vram_fit": "[UNICODE:26A1] 100% CUDA VRAM Safe (<3GB)" if is_under_3gb else "[WARN] High Memory (>3GB VRAM)",
            "is_downloaded": True,
            "parameter_size": param,
            "quantization": quant,
            "family": family,
            "description": desc,
            "is_active_running": (name == active_running)
        })

    # 2. Append catalog models that are not yet downloaded so users can easily discover and pull them
    for cat_name, cat_spec in CATALOG_SPECS.items():
        if cat_name not in seen_names:
            seen_names.add(cat_name)
            is_u3 = cat_spec["is_under_3gb"]
            if is_u3: under_3gb_names.append(cat_name)

            detailed_models.append({
                "name": cat_name,
                "size_bytes": int(cat_spec["size_gb"] * (1024**3)),
                "size_gb": cat_spec["size_gb"],
                "size_mb": int(cat_spec["size_gb"] * 1024),
                "is_under_3gb": is_u3,
                "vram_fit": "[UNICODE:26A1] 100% CUDA VRAM Safe (<3GB)" if is_u3 else "[WARN] High Memory (>3GB VRAM)",
                "is_downloaded": False,
                "parameter_size": cat_spec["param"],
                "quantization": cat_spec["quant"],
                "family": "",
                "description": f"{cat_spec['desc']} [BULLET] {cat_spec['size_gb']} GB (Needs Download)",
                "is_active_running": False
            })

    # Optional Search Query filtering across name, description, parameter size, and family
    if q and q.strip():
        q_term = q.strip().lower()
        detailed_models = [
            m for m in detailed_models
            if q_term in m["name"].lower() or q_term in m.get("description", "").lower() or q_term in m.get("parameter_size", "").lower() or q_term in m.get("family", "").lower()
        ]

    # Sort so: Downloaded first, then <3GB first, then alphabetical
    detailed_models.sort(key=lambda x: (not x["is_downloaded"], not x["is_under_3gb"], x["name"]))

    all_names = [m["name"] for m in detailed_models]

    return {
        "status": "success",
        "query": q,
        "models": all_names,
        "downloaded": [m["name"] for m in detailed_models if m["is_downloaded"]],
        "under_3gb_models": [m["name"] for m in detailed_models if m["is_under_3gb"]],
        "detailed_models": detailed_models,
        "active_running_model": active_running,
        "total_installed": len([m for m in detailed_models if m["is_downloaded"]]),
        "total_under_3gb": len([m for m in detailed_models if m["is_under_3gb"]]),
        "total_results": len(detailed_models)
    }

@app.post("/api/models/pull")
def pull_model_endpoint(payload: ModelPullRequest):
    """Robust REST endpoint to pull any model from the Ollama registry with non-blocking progress tracking."""
    model_name = payload.model.strip()
    if not model_name:
        return JSONResponse({"status": "error", "message": "Model name cannot be empty"}, status_code=400)

    pull_url = os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate").replace("/api/generate", "/api/pull")

    if model_name in active_pull_tasks and active_pull_tasks[model_name].get("status") in ["pulling", "downloading"]:
        return {"status": "in_progress", "task": active_pull_tasks[model_name]}

    active_pull_tasks[model_name] = {
        "model": model_name,
        "status": "pulling",
        "detail": "Initiating pull from Ollama registry...",
        "percent": 0,
        "completed": 0,
        "total": 0,
        "started_at": time.time(),
        "error": None
    }

    def _worker():
        try:
            res = requests.post(pull_url, json={"name": model_name}, stream=True, timeout=(10, 1800))
            for line in res.iter_lines():
                if line:
                    try:
                        data = json.loads(line.decode("utf-8"))
                        status_str = data.get("status", "pulling")
                        total = data.get("total", 0)
                        completed = data.get("completed", 0)
                        pct = round((completed / total) * 100) if total > 0 else 0

                        active_pull_tasks[model_name].update({
                            "status": "downloading" if "download" in status_str.lower() else status_str,
                            "detail": status_str,
                            "completed": completed,
                            "total": total,
                            "percent": pct
                        })
                    except: pass
            active_pull_tasks[model_name]["status"] = "success"
            active_pull_tasks[model_name]["percent"] = 100
            active_pull_tasks[model_name]["detail"] = "Successfully pulled and verified."
        except Exception as e:
            active_pull_tasks[model_name]["status"] = "error"
            active_pull_tasks[model_name]["error"] = str(e)
            active_pull_tasks[model_name]["detail"] = f"Failed to pull: {str(e)}"

    threading.Thread(target=_worker, daemon=True).start()
    return {"status": "started", "task": active_pull_tasks[model_name]}

@app.get("/api/models/pull/status")
def get_model_pull_status(model: str = Query(...)):
    """Check progress of a running model pull task."""
    task = active_pull_tasks.get(model.strip())
    if not task:
        return {"status": "not_found", "model": model, "percent": 0}
    return task

@app.delete("/api/models/{model_name:path}")
def delete_model_endpoint(model_name: str):
    """Delete a downloaded model from Ollama storage to reclaim disk space."""
    ollama_url = os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate").replace("/api/generate", "/api/delete")
    try:
        res = requests.delete(ollama_url, json={"name": model_name}, timeout=15)
        if res.status_code in [200, 204]:
            if model_name in active_pull_tasks:
                del active_pull_tasks[model_name]
            return {"status": "success", "message": f"Model {model_name} deleted successfully from Ollama."}
        return JSONResponse({"status": "error", "message": res.text}, status_code=res.status_code)
    except Exception as e:
        return JSONResponse({"status": "error", "message": str(e)}, status_code=500)

