@app.get("/api/diagnostics")
def run_preflight_diagnostics():
    auto_cleanup_routine()
    cfg = {}
    
    sock_path = "/var/run/docker.sock"
    if os.path.exists(sock_path) and os.access(sock_path, os.R_OK):
        cfg["Docker Socket"] = {"status": "ONLINE", "crit": True, "detail": "Mounted & Accessible"}
    else:
        cfg["Docker Socket"] = {"status": "ERROR", "crit": True, "detail": "Missing Socket Mount"}

    try:
        r = redis.Redis.from_url(os.environ.get("REDIS_URL", "redis://redis:6379/0"))
        if r.ping():
            cfg["Redis Broker"] = {"status": "ONLINE", "crit": True, "detail": "Connected & Healthy"}
    except Exception as e:
        cfg["Redis Broker"] = {"status": "ERROR", "crit": True, "detail": str(e)}

    try:
        socket.setdefaulttimeout(2)
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.connect(("postgres", 5432))
        cfg["PostgreSQL DB"] = {"status": "ONLINE", "crit": True, "detail": "Port 5432 Open"}
    except Exception as e:
        cfg["PostgreSQL DB"] = {"status": "ERROR", "crit": True, "detail": "Unreachable"}

    try:
        socket.setdefaulttimeout(2)
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.connect(("8.8.8.8", 53))
        cfg["External Network"] = {"status": "ONLINE", "crit": False, "detail": "Internet Reachable"}
    except:
        cfg["External Network"] = {"status": "WARNING", "crit": False, "detail": "No Internet Access"}

    celery_active = False
    try:
        inspect = celery_app.control.inspect(timeout=1.0)
        active_nodes = inspect.ping() if inspect else None
        if active_nodes:
            cfg["Compute Engine"] = {"status": "ONLINE", "crit": True, "detail": f"Celery Active ({len(active_nodes)} node(s))"}
            celery_active = True
    except: pass
    if not celery_active: cfg["Compute Engine"] = {"status": "ONLINE", "crit": True, "detail": "In-Process ThreadPool Active"}

    ollama_url = os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate").replace("/api/generate", "/api/tags")
    try: 
        res = requests.get(ollama_url, timeout=3)
        if res.status_code == 200: cfg["LLM Router"] = {"status": "ONLINE", "crit": True, "detail": "Ollama DeepSeek Ready"}
        else: cfg["LLM Router"] = {"status": "ERROR", "crit": True, "detail": f"HTTP {res.status_code}"}
    except Exception as e: cfg["LLM Router"] = {"status": "OFFLINE", "crit": True, "detail": str(e)}

    k6 = shutil.which("k6"); cfg["k6 Engine"] = {"status": "OK" if k6 else "MISSING", "crit": True, "detail": "Installed if k6 else Missing"}
    pabot = shutil.which("pabot"); cfg["Parallel Engine (Pabot)"] = {"status": "OK" if pabot else "MISSING", "crit": True, "detail": "Installed" if pabot else "Missing"}
    allure = shutil.which("allure"); cfg["Allure Reporter"] = {"status": "OK" if allure else "MISSING", "crit": True, "detail": "Installed" if allure else "Missing"}

    healthy = not any(v["status"] not in ["OK", "ONLINE"] and v["crit"] for v in cfg.values())
    return {"overall": "HEALTHY" if healthy else "ERROR", "config": cfg}

@app.post("/api/diagnostics/target")
def check_target_health(payload: TargetHealthPayload):
    import time
    try:
        start = time.time()
        res = requests.get(payload.url, timeout=10, verify=False)
        elapsed = round((time.time() - start) * 1000)
        if res.status_code < 400:
            return {"status": "ONLINE", "detail": f"HTTP {res.status_code} ({elapsed}ms)"}
        else:
            return {"status": "WARNING", "detail": f"HTTP {res.status_code} ({elapsed}ms)"}
    except requests.exceptions.Timeout:
        return {"status": "ERROR", "detail": "Timeout (>10s)"}
    except Exception as e:
        return {"status": "ERROR", "detail": "Connection Refused"}

@app.post("/api/diagnostics/nist")
def check_nist_compliance(payload: NISTPayload):
    import requests
    import urllib.parse
    # Extract primary keyword from tech stack (e.g., 'React' from 'React / Node')
    keyword = urllib.parse.quote(payload.stack.split()[0] if payload.stack else "web")
    try:
        # NVD API 2.0 with a small timeout, max 5 results for fast check
        res = requests.get(f"https://services.nvd.nist.gov/rest/json/cves/2.0?keywordSearch={keyword}&resultsPerPage=5", timeout=7, verify=False)
        if res.status_code == 200:
            data = res.json()
            total_vulns = data.get("totalResults", 0)
            cves = []
            highest_severity = "LOW"
            severity_order = {"LOW": 1, "MEDIUM": 2, "HIGH": 3, "CRITICAL": 4}
            for vuln in data.get("vulnerabilities", []):
                cve = vuln.get("cve", {})
                cve_id = cve.get("id", "UNKNOWN")
                metrics = cve.get("metrics", {})
                cvss_data = metrics.get("cvssMetricV31", metrics.get("cvssMetricV30", []))
                base_severity = "UNKNOWN"
                if cvss_data and len(cvss_data) > 0:
                    base_severity = cvss_data[0].get("cvssData", {}).get("baseSeverity", "UNKNOWN")
                cves.append({"id": cve_id, "severity": base_severity})
                if base_severity in severity_order and severity_order[base_severity] > severity_order.get(highest_severity, 0):
                    highest_severity = base_severity
            
            status = "DANGER" if highest_severity in ["HIGH", "CRITICAL"] else "WARNING" if total_vulns > 0 else "SECURE"
            return {"status": status, "total_vulns": total_vulns, "highest_severity": highest_severity, "cves": cves}
        else:
            return {"status": "ERROR", "detail": f"NVD HTTP {res.status_code}"}
    except requests.exceptions.Timeout:
        return {"status": "TIMEOUT", "detail": "NIST NVD API Timeout"}
    except Exception as e:
        return {"status": "ERROR", "detail": str(e)}

@app.get("/api/task")
def get_task_status():
    try:
        data = None
        if os.path.exists("artifacts/logs/task_status.json"):
            with open("artifacts/logs/task_status.json", "r", encoding="utf-8") as f:
                data = json.load(f)
        if not data or not isinstance(data, dict):
            data = {"status": "idle", "progress": 0, "steps": {}, "current_task": "Ready"}
        cmd_lower = str(data.get("current_command", "") + " " + data.get("current_task", "")).lower()
        if "k6" in cmd_lower or "perf" in cmd_lower or "load" in cmd_lower:
            data["active_discipline"] = "PERFORMANCE"
        elif "api" in cmd_lower or "endpoint" in cmd_lower or "contract" in cmd_lower or "requests" in cmd_lower:
            data["active_discipline"] = "API"
        elif "pabot" in cmd_lower or "robot" in cmd_lower or "browser" in cmd_lower or "ui" in cmd_lower or "selenium" in cmd_lower or "crawl" in cmd_lower or "spider" in cmd_lower:
            data["active_discipline"] = "UI"
        else:
            data["active_discipline"] = data.get("active_discipline") or ("UI" if data.get("status") in ("running", "processing") else None)
        if os.path.exists("artifacts/logs/antibot_quarantine.json"):
            try:
                with open("artifacts/logs/antibot_quarantine.json", "r", encoding="utf-8") as _abf:
                    _ab_data = json.load(_abf)
                    data["antibot_quarantined"] = _ab_data.get("quarantined", True)
                    data["antibot_quarantined_url"] = _ab_data.get("url")
                    data["antibot_quarantined_msg"] = _ab_data.get("message")
            except Exception:
                pass
        if not data.get("page_manifest"):
            for m_path in ["artifacts/reports/page_manifest.json", "artifacts/logs/site_manifest.json"]:
                if os.path.exists(m_path):
                    try:
                        with open(m_path, "r", encoding="utf-8") as mf:
                            manifest_data = json.load(mf)
                            if manifest_data:
                                data["page_manifest"] = manifest_data
                                break
                    except Exception:
                        pass
        return data
    except:
        return {"status": "idle", "progress": 0, "steps": {}, "current_task": "Ready"}

@app.get("/api/download/package")
def download_complete_package():
    zip_path = "artifacts/reports/Standalone_QA_Test_Package.zip"
    os.makedirs("artifacts/reports", exist_ok=True)

    # Ensure coverage matrix is up-to-date and persisted
    matrix_path = "artifacts/reports/coverage_matrix.json"
    if not os.path.exists(matrix_path):
        try:
            from .engines.coverage_engine import CoverageMatrixEngine
            CoverageMatrixEngine(".").analyze_coverage()
        except Exception:
            pass

    import zipfile
    with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as zipf:
        if os.path.exists("artifacts/scripts"):
            for f in os.listdir("artifacts/scripts"):
                full_p = os.path.join("artifacts/scripts", f)
                if os.path.isfile(full_p):
                    zipf.write(full_p, f"tests/{f}")
        if os.path.exists("artifacts/reports/test_scenarios.md"):
            zipf.write("artifacts/reports/test_scenarios.md", "tests/test_scenarios.md")
        if os.path.exists("artifacts/reports/Master_Requirements_Document.md"):
            zipf.write("artifacts/reports/Master_Requirements_Document.md", "tests/Master_Requirements_Document.md")
        if os.path.exists("artifacts/reports/SDET_Master_Test_Plan.md"):
            zipf.write("artifacts/reports/SDET_Master_Test_Plan.md", "tests/SDET_Master_Test_Plan.md")
        if os.path.exists("artifacts/reports/API_Performance_Test_Plan.md"):
            zipf.write("artifacts/reports/API_Performance_Test_Plan.md", "tests/API_Performance_Test_Plan.md")
        if os.path.exists("artifacts/reports/Defect_Triage_Report.md"):
            zipf.write("artifacts/reports/Defect_Triage_Report.md", "tests/Defect_Triage_Report.md")
        if os.path.exists("artifacts/reports/AI_Performance_Evaluation.md"):
            zipf.write("artifacts/reports/AI_Performance_Evaluation.md", "tests/AI_Performance_Evaluation.md")
        
        # Bundle persistent Coverage Matrix and DOM Vector Store into package
        if os.path.exists(matrix_path):
            zipf.write(matrix_path, "tests/coverage_matrix.json")
            zipf.write(matrix_path, "artifacts/reports/coverage_matrix.json")
        if os.path.exists("artifacts/reports/coverage_matrix.md"):
            zipf.write("artifacts/reports/coverage_matrix.md", "tests/coverage_matrix.md")
            zipf.write("artifacts/reports/coverage_matrix.md", "artifacts/reports/coverage_matrix.md")
        if os.path.exists("artifacts/db/dom_vector_index.json"):
            zipf.write("artifacts/db/dom_vector_index.json", "artifacts/reports/dom_vector_store.json")

        # 1. Write the full requirements array
        reqs = "selenium>=4.15.0\nrequests>=2.31.0\nrobotframework>=6.0.0\nrobotframework-pabot>=2.16.0\nrobotframework-seleniumlibrary>=3.3.1\nrobotframework-requests>=0.9.4\nallure-robotframework>=2.13.0\npytest>=7.4.3\nallure-pytest>=2.13.0\ncrawl4ai>=0.4.0\nrf-mcp>=0.35.0\npyppeteer>=2.0.0\n"
        zipf.writestr("requirements.txt", reqs)
        
        # 2. Phase 1: Environment Setup
        zipf.writestr("1_setup_env.bat", "@echo off\ncolor 0B\necho [PHASE 1] Installing testing dependencies...\npip install -r requirements.txt\necho Setup Complete.\npause")
        zipf.writestr("1_setup_env.sh", "#!/bin/bash\necho '[PHASE 1] Installing testing dependencies...'\npip install -r requirements.txt\necho 'Setup Complete.'\n")
        
        # 3. Phase 2: Parallel Execution (Orchestrated purely via Robot Framework)
        zipf.writestr("2_run_tests.bat", "@echo off\ncolor 0A\necho [PHASE 2] Running Master BDD Suite in Parallel with Pabot...\necho Pabot will orchestrate UI, API, and Load tests automatically via BDD keywords.\npabot --processes 4 tests\\auto_suite.robot\necho Execution Complete.\npause")
        zipf.writestr("2_run_tests.sh", "#!/bin/bash\necho '[PHASE 2] Running Master BDD Suite in Parallel with Pabot...'\necho 'Pabot will orchestrate UI, API, and Load tests automatically via BDD keywords.'\npabot --processes 4 tests/auto_suite.robot\necho 'Execution Complete.'\n")

        # 4. Phase 3: Graceful Teardown and Cleanup
        zipf.writestr("3_teardown_env.bat", "@echo off\ncolor 0C\necho [PHASE 3] Gracefully uninstalling all testing libraries...\npip uninstall -r requirements.txt -y\necho Clearing test artifacts, logs, caches, and compiled code...\nrmdir /S /Q tests\\__pycache__ 2>nul\nrmdir /S /Q allure-results 2>nul\nrmdir /S /Q pabot_results 2>nul\ndel /S /Q *.xml *.html *.png *.log 2>nul\necho Environment completely cleared.\npause")
        zipf.writestr("3_teardown_env.sh", "#!/bin/bash\necho '[PHASE 3] Gracefully uninstalling all testing libraries...'\npip uninstall -r requirements.txt -y\necho 'Clearing test artifacts, logs, caches, and compiled code...'\nrm -rf tests/__pycache__ allure-results pabot_results *.xml *.html *.png *.log\necho 'Environment completely cleared.'\n")

        zipf.writestr("README.md", "# Autonomous Enterprise QA Test Package\nGenerated by Enterprise ATP Framework.\n\n## Execution Lifecycle:\n1. Execute `1_setup_env` to safely install isolated dependencies.\n2. Execute `2_run_tests` to trigger the Master Robot Orchestrator. (This suite will internally trigger the UI Pytest, API Pytest, and k6 load tests via BDD keywords).\n3. Execute `3_teardown_env` to gracefully wipe all libraries, cached objects, and output logs from your machine.\n")

    from fastapi.responses import FileResponse
    return FileResponse(zip_path, media_type="application/zip", filename="Standalone_QA_Test_Package.zip")

@app.get("/api/download/script/{script_type}")
def download_single_script(script_type: str):
    file_map = {
        "lib": ("artifacts/scripts/keywords_lib.py", "keywords_lib.py"),
        "ui": ("artifacts/scripts/auto_ui_test.py", "auto_ui_test.py"),
        "api": ("artifacts/scripts/auto_api_test.py", "auto_api_test.py"),
        "k6": ("artifacts/scripts/auto_load_test.js", "auto_load_test.js"),
        "unit": ("artifacts/scripts/auto_unit_test.py", "auto_unit_test.py"),
        "robot": ("artifacts/scripts/auto_suite.robot", "auto_suite.robot"),
        "wdio": ("artifacts/scripts/auto_ui_wdio.js", "auto_ui_wdio.js"),  # [UNICODE:26A1] Single WDIO Download
        "guide": ("artifacts/reports/README_RUN_GUIDE.md", "README_RUN_GUIDE.md"),
        "brd": ("artifacts/reports/Master_Requirements_Document.md", "Master_Requirements_Document.md"),
        "mrd": ("artifacts/reports/Master_Requirements_Document.md", "Master_Requirements_Document.md"),
        "sdet_plan": ("artifacts/reports/SDET_Master_Test_Plan.md", "SDET_Master_Test_Plan.md"),
        "perf_plan": ("artifacts/reports/API_Performance_Test_Plan.md", "API_Performance_Test_Plan.md"),
        "triage": ("artifacts/reports/Defect_Triage_Report.md", "Defect_Triage_Report.md"),
        "eval": ("artifacts/reports/AI_Performance_Evaluation.md", "AI_Performance_Evaluation.md")
    }
    if script_type in file_map:
        path, name = file_map[script_type]
        if os.path.exists(path):
            return FileResponse(path, filename=name)
        elif script_type in ("mrd", "brd"):
            os.makedirs("artifacts/reports", exist_ok=True)
            with open(path, "w", encoding="utf-8") as f:
                f.write("# Master Requirements Document (MRD)\n\nAwaiting pipeline synthesis.")
            return FileResponse(path, filename=name)
    return JSONResponse(status_code=404, content={"error": "Script file not found. Generate tests first."})



@app.post("/api/project/import")
async def import_project(file: UploadFile = File(...)):
    try:
        import shutil, zipfile, os
        artifacts_dir = "artifacts"
        os.makedirs(artifacts_dir, exist_ok=True)
        
        zip_path = os.path.join(artifacts_dir, "uploaded_project.zip")
        with open(zip_path, "wb") as buffer:
            shutil.copyfileobj(file.file, buffer)
            
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            zip_ref.extractall(artifacts_dir)
            
        if os.path.exists(zip_path):
            os.remove(zip_path)

        # Restore DOM vector store if bundled
        dom_store_p = os.path.join(artifacts_dir, "reports", "dom_vector_store.json")
        if os.path.exists(dom_store_p):
            db_dir = os.path.join(artifacts_dir, "db")
            os.makedirs(db_dir, exist_ok=True)
            try:
                shutil.copyfile(dom_store_p, os.path.join(db_dir, "dom_vector_index.json"))
            except Exception:
                pass

        # Rehydrate and verify coverage matrix immediately on import
        try:
            try:
                from .engines.coverage_engine import CoverageMatrixEngine
            except ImportError:
                from aspice_qa_framework.engines.coverage_engine import CoverageMatrixEngine
            CoverageMatrixEngine(".").analyze_coverage()
        except Exception:
            pass

        return {"status": "success", "message": "Project imported successfully with Coverage Matrix preserved."}
    except Exception as e:
        from fastapi.responses import JSONResponse
        return JSONResponse(status_code=500, content={"error": str(e)})

from fastapi.responses import StreamingResponse
import json

@app.post("/api/project/chat")
async def project_chat(req: ChatRequest):
    import os, json, requests
    
    # Gather context
    context = []
    if os.path.exists("artifacts/reports/page_manifest.json"):
        try:
            with open("artifacts/reports/page_manifest.json", "r") as f:
                context.append(f"PAGE MANIFEST:\n{f.read()}")
        except: pass
    if os.path.exists("artifacts/reports/Master_Requirements_Document.md"):
        try:
            with open("artifacts/reports/Master_Requirements_Document.md", "r") as f:
                context.append(f"BRD & STRATEGY:\n{f.read()}")
        except: pass
            
    scripts_dir = "artifacts/scripts"
    if os.path.exists(scripts_dir):
        for fname in os.listdir(scripts_dir):
            if fname.endswith((".py", ".js", ".robot", ".md")):
                try:
                    with open(os.path.join(scripts_dir, fname), "r", encoding="utf-8") as f:
                        context.append(f"SCRIPT: {fname}\n```\n{f.read()}\n```")
                except: pass
                    
    combined_context = "\n\n".join(context)[:30000] # Truncate to avoid context limits
    
    system_prompt = f"""You are an expert SDET and QA Architect. You have access to the user's current project artifacts.
Respond to their queries intelligently. If the user asks to fix or enhance a script or document, you MUST output the updated file contents inside a markdown code block preceded by a magic header:
# FILE: <filename.ext>
```
<full updated code here>
```
If you do this, the system will automatically overwrite the file.

### CURRENT PROJECT CONTEXT:
{combined_context}
"""
    
    ollama_url = os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate")
    vram_req = probe_and_scale_vram_resources("deepseek-r1:1.5b")
    payload = {
        "model": "deepseek-r1:1.5b",
        "prompt": system_prompt + f"\n\nUSER MESSAGE: {req.message}",
        "stream": True,
        "options": {
            "temperature": 0.0,
            "top_p": 0.1,
            "top_k": 10,
            "repeat_penalty": 1.0,
            "num_ctx": vram_req.get("scaled_ctx", 8192),
            "num_gpu": -1,
            "use_mmap": True
        }
    }
    
    def generate():
        try:
            response = requests.post(ollama_url, json=payload, stream=True, timeout=60)
            for line in response.iter_lines():
                if line:
                    decoded = line.decode('utf-8')
                    try:
                        chunk = json.loads(decoded)
                        if "response" in chunk:
                            yield chunk["response"]
                    except: pass
        except Exception as e:
            yield f"Error connecting to LLM: {str(e)}"
            
    return StreamingResponse(generate(), media_type="text/plain")


@app.get("/api/download")
def download_logs():
    zip_filename = "qa_logs_export.zip"
    with zipfile.ZipFile(zip_filename, "w", zipfile.ZIP_DEFLATED) as zipf:
        for target_dir in ["logs", "scripts", "reports", "specs"]:
            path = os.path.join("artifacts", target_dir)
            if os.path.exists(path):
                for root, _, files in os.walk(path):
                    for file in files:
                        file_path = os.path.join(root, file)
                        arcname = os.path.relpath(file_path, "artifacts")
                        zipf.write(file_path, arcname)
    return FileResponse(zip_filename, media_type="application/zip", filename="Enterprise_QA_Logs.zip")

