@app.post("/api/execute")
async def execute_tests(payload: Dict[str, Any]):
    """
    Launches Pabot parallel test runner with portable binary resolution,
    reattempt self-healing fix injection, and single-file Allure report compilation.
    Body: {"processes": 4, "suite_path": "artifacts/scripts/auto_suite.robot", "max_retries": 2, "single_file": true}
    Consumer: Execution Worker Pool / Web UI
    """
    try:
        processes = payload.get("processes", 4)
        max_retries = min(max(1, int(payload.get("max_retries", 2))), 3)
        single_file = bool(payload.get("single_file", False))
        suite_path = payload.get("suite_path", "artifacts/scripts/auto_suite.robot")

        if not os.path.exists(suite_path):
            suite_path = "aspice_qa_framework/execution_suite.robot"
            if not os.path.exists(suite_path):
                suite_path = "artifacts/scripts/auto_suite.robot"

        robot_file = os.path.abspath(suite_path)
        allure_dir = os.path.abspath("artifacts/reports/allure-results")
        scripts_dir = os.path.abspath("artifacts/scripts")
        reports_dir = os.path.abspath("artifacts/reports")
        os.makedirs(allure_dir, exist_ok=True)
        os.makedirs(scripts_dir, exist_ok=True)
        os.makedirs(reports_dir, exist_ok=True)
        os.makedirs("artifacts/logs", exist_ok=True)

        exec_env = os.environ.copy()
        exec_env["PYTHONPATH"] = f"{scripts_dir}{os.pathsep}{os.getcwd()}{os.pathsep}{exec_env.get('PYTHONPATH', '')}"
        exec_env["ALLURE_RESULTS_DIR"] = allure_dir
        exec_env["ENABLE_SCREENCAST"] = "true"
        os.environ["ENABLE_SCREENCAST"] = "true"

        listener_arg = f"allure_robotframework;{allure_dir}"
        pabot_cmd_base = [shutil.which("pabot")] if shutil.which("pabot") else [sys.executable, "-m", "pabot.pabot"]
        base_output_xml = os.path.join(reports_dir, "output.xml")

        def run_pabot():
            gist_path = os.path.join(reports_dir, "reattempt_fixes_gist.json")
            gist_md = os.path.join(reports_dir, "reattempt_fixes_gist.md")
            gist_data = {
                "version": "1.0",
                "generated_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                "total_attempts": 1,
                "total_fixes": 0,
                "fixes": []
            }

            for attempt in range(1, max_retries + 1):
                is_rerun_selective = False
                rerun_xml = os.path.join(reports_dir, f"rerun_{attempt}.xml")

                if attempt > 1 and os.path.exists(base_output_xml) and os.path.getsize(base_output_xml) > 0:
                    try:
                        import xml.etree.ElementTree as ET
                        root = ET.parse(base_output_xml).getroot()
                        failed_tests = root.findall(".//test/status[@status='FAIL']")
                        if failed_tests:
                            is_rerun_selective = True
                    except Exception:
                        is_rerun_selective = False

                target_sut_url = resolve_global_target_url(None, fallback="http://localhost:8000")
                target_api_url = f"{target_sut_url.rstrip('/')}/api/v1/health"

                cmd = list(pabot_cmd_base) + [
                    "--testlevelsplit",
                    "--processes", str(max(1, processes)),
                    "--pythonpath", "artifacts/scripts",
                    "--listener", listener_arg,
                    "--variable", f"BASE_URL:{target_sut_url}",
                    "--variable", f"API_ENDPOINT:{target_api_url}",
                    "--outputdir", "artifacts/reports"
                ]
                if is_rerun_selective:
                    cmd.extend(["--rerunfailed", base_output_xml, "--output", f"rerun_{attempt}.xml"])
                cmd.append(robot_file)

                try:
                    result = subprocess.run(cmd, capture_output=True, text=True, timeout=600, env=exec_env)

                    # If selective rerun, merge results into master output.xml
                    if is_rerun_selective and os.path.exists(rerun_xml):
                        # REQ-HIST-041: Immutable history preservation for multi-attempt runs
                        try:
                            hist_xml_dir = os.path.abspath(os.path.join(reports_dir, "history", "robot_attempts"))
                            os.makedirs(hist_xml_dir, exist_ok=True)
                            ts_str = time.strftime("%Y%m%d_%H%M%S")
                            if os.path.exists(base_output_xml):
                                shutil.copy2(base_output_xml, os.path.join(hist_xml_dir, f"pre_rerun_attempt_{attempt}_{ts_str}.xml"))
                            shutil.copy2(rerun_xml, os.path.join(hist_xml_dir, f"rerun_attempt_{attempt}_{ts_str}.xml"))
                            
                            hist_log_path = os.path.abspath(os.path.join(reports_dir, "execution_history.jsonl"))
                            with open(hist_log_path, "a", encoding="utf-8") as hf:
                                hf.write(json.dumps({
                                    "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
                                    "event": "ROBOT_RERUN_ATTEMPT",
                                    "attempt": attempt,
                                    "pre_rerun_xml": f"pre_rerun_attempt_{attempt}_{ts_str}.xml",
                                    "rerun_xml": f"rerun_attempt_{attempt}_{ts_str}.xml"
                                }) + "\n")
                        except Exception:
                            pass

                        temp_merged = os.path.join(reports_dir, "merged_output.xml")
                        rebot_cmd = [sys.executable, "-m", "robot.rebot", "--merge", "--output", temp_merged, base_output_xml, rerun_xml]
                        r_res = subprocess.run(rebot_cmd, capture_output=True, text=True)
                        if r_res.returncode == 0 and os.path.exists(temp_merged):
                            shutil.copyfile(temp_merged, base_output_xml)
                            try: os.remove(temp_merged)
                            except Exception: pass
                            convert_robot_xml_to_allure(base_output_xml, allure_dir)
                            gist_data["fixes"].append({
                                "id": f"FIX-{attempt}-{len(gist_data['fixes'])+1:02d}",
                                "attempt": attempt,
                                "category": "SELECTIVE_RERUN_MERGE",
                                "title": f"Merged Rerun for Attempt {attempt}",
                                "details": f"Selectively reran failed tests and merged into master report via rebot --merge.",
                                "timestamp": time.strftime("%Y-%m-%d %H:%M:%S")
                            })

                    if result.returncode == 0 or attempt == max_retries:
                        break

                    # Inject fixes before next attempt
                    if attempt < max_retries and os.path.exists(robot_file):
                        try:
                            from aspice_qa_framework.engines.vector_dom_engine import DOMVectorEngine
                            v_engine = DOMVectorEngine()
                            with open(robot_file, "r", encoding="utf-8") as rf:
                                r_code = rf.read()

                            err_out = result.stdout or ""
                            broken = re.findall(r"Element with locator '([^']+)' not found", err_out)
                            healed_any = False
                            for b in broken:
                                h_res = v_engine.heal_broken_locator(b, error_trace=err_out)
                                top = h_res.get("top_suggestion")
                                if top and top.get("selector") and top.get("selector") != b:
                                    r_code = r_code.replace(b, top.get("selector"))
                                    healed_any = True
                                    gist_data["fixes"].append({
                                        "id": f"FIX-{attempt}-{len(gist_data['fixes'])+1:02d}",
                                        "attempt": attempt,
                                        "category": "DOM_VECTOR_HEAL",
                                        "title": f"Healed Locator '{b}'",
                                        "details": f"Replaced with '{top.get('selector')}' (Confidence: {top.get('confidence')})",
                                        "timestamp": time.strftime("%Y-%m-%d %H:%M:%S")
                                    })
                            if healed_any:
                                with open(robot_file, "w", encoding="utf-8") as rf:
                                    rf.write(r_code)
                        except Exception:
                            pass

                except Exception:
                    break

            gist_data["total_fixes"] = len(gist_data["fixes"])
            gist_data["total_attempts"] = attempt
            try:
                with open(gist_path, "w", encoding="utf-8") as jf:
                    json.dump(gist_data, jf, indent=2)
                md_out = [f"# ⚡ Reattempt Fixes Injected Gist\nTotal Fixes: {len(gist_data['fixes'])}\n"]
                for fix in gist_data["fixes"]:
                    md_out.append(f"- **Attempt {fix['attempt']} [{fix['category']}]**: {fix['title']} — {fix['details']}")
                with open(gist_md, "w", encoding="utf-8") as mf:
                    mf.write("\n".join(md_out))
            except Exception:
                pass

            try:
                generate_allure_report({"run_id": "latest", "include_trends": True, "single_file": single_file})
            except Exception:
                pass

            try:
                ts_file = "artifacts/logs/task_status.json"
                if os.path.exists(ts_file):
                    with open(ts_file, "r", encoding="utf-8") as tf:
                        ts_data = json.load(tf)
                    ts_data["status"] = "completed"
                    ts_data["current_task"] = "Pabot Execution Completed"
                    ts_data["reattempt_gist"] = gist_data
                    ts_data["current_command"] = f"Execution finished. Total attempts: {attempt}/{max_retries}."
                    if "steps" in ts_data and "step_6" in ts_data["steps"]:
                        ts_data["steps"]["step_6"]["status"] = "COMPLETED"
                    if "attempt_info" in ts_data and isinstance(ts_data["attempt_info"], dict):
                        ts_data["attempt_info"]["active"] = False
                    with open(ts_file, "w", encoding="utf-8") as tf:
                        json.dump(ts_data, tf, indent=2)
            except Exception:
                pass

        thread = threading.Thread(target=run_pabot)
        thread.daemon = True
        thread.start()

        return {
            "status": "running",
            "message": f"Pabot execution started with {processes} processes (Single-File: {single_file}, Max Retries: {max_retries}) for {os.path.basename(robot_file)}",
            "suite_path": robot_file,
            "single_file": single_file
        }
    except Exception as e:
        return JSONResponse(status_code=500, content={"status": "error", "message": str(e)})

@app.get("/api/telemetry/stream")
async def telemetry_stream(request: Request):
    """
    Server-Sent Events (SSE) streaming real-time GPU/RAM/Tok/s metrics.
    Consumer: Real-Time Telemetry Graphs
    """
    async def event_stream():
        try:
            while True:
                if await request.is_disconnected():
                    break
                telemetry = get_system_and_gpu_telemetry()
                data = json.dumps({
                    "type": "telemetry",
                    "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
                    **telemetry
                })
                yield "data: {0}\n\n".format(data)
                await asyncio.sleep(2)
        except Exception:
            pass
    
    return StreamingResponse(event_stream(), media_type="text/event-stream")

